user_id_counter = 1
tokens = {}
habits = {}
habit_id_counter = 1
entries = {}
entry_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class HabitCreate(BaseModel):
    name: str
    description: Optional[str] = None

class EntryCreate(BaseModel):
    habit_id: int
    note: Optional[str] = None

def get_user_id_from_token(authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = f"tok_{uid}_{datetime.now().timestamp()}"
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

