from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import secrets

app = FastAPI()

users = {}
tokens = {}
next_user_id = 1

workouts = {}
next_workout_id = 1

fitness_summaries = {}
next_summary_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class WorkoutCreate(BaseModel):
    type: str
    duration_minutes: int
    calories_burned: int

class FitnessSummaryCreate(BaseModel):
    user_id: int
    step_count: int
    calories_burned: int
    weekly_streaks: int

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/workouts/{workout_id}")
def get_workout(workout_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    w = workouts.get(workout_id)
    if w is None:
        raise HTTPException(status_code=404, detail="Workout not found")
    return w

@app.post("/workouts")
def create_workout(workout: WorkoutCreate, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    global next_workout_id
    wid = next_workout_id
    next_workout_id += 1
    workouts[wid] = {"id": wid, "user_id": user_id, "type": workout.type, "duration_minutes": workout.duration_minutes, "calories_burned": workout.calories_burned}
    return workouts[wid]

@app.get("/fitness/summary")
def get_fitness_summary(authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    total_steps = 0
    total_calories = 0
    weekly_streaks = 0
    for sid, s in fitness_summaries.items():
        if s["user_id"] == user_id:
            total_steps += s["step_count"]
            total_calories += s["calories_burned"]
            weekly_streaks = max(weekly_streaks, s["weekly_streaks"])
    return {"step_count": total_steps, "calories_burned": total_calories, "weekly_streaks": weekly_streaks}

