import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Signup
    signup_resp = session.post(f"{BASE_URL}/signup", params={"username": "testuser", "password": "testpass"})
    if signup_resp.status_code != 200:
        return False
    user_data = signup_resp.json()
    if "id" not in user_data or "username" not in user_data:
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", params={"username": "testuser", "password": "testpass"})
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    # Create profile
    headers = {"Authorization": f"Bearer {token}"}
    profile_resp = session.post(f"{BASE_URL}/profiles", params={"name": "Test", "goals": "Fitness", "workout_preferences": "Cardio"}, headers=headers)
    if profile_resp.status_code != 200:
        return False
    profile_data = profile_resp.json()
    if "id" not in profile_data or "user_id" not in profile_data:
        return False
    profile_id = profile_data["id"]

    # Fetch own profile
    fetch_resp = session.get(f"{BASE_URL}/profiles/{profile_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    fetched_profile = fetch_resp.json()
    if fetched_profile.get("id") != profile_id:
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

