import requests
import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    try:
        # Sign up a new user
        signup_resp = requests.post(f"{BASE_URL}/signup", json={"username": "testuser", "password": "testpass"})
        if signup_resp.status_code not in (200, 201):
            return False
        user_data = signup_resp.json()
        if "id" not in user_data or "username" not in user_data:
            return False

        # Log in with the new user
        login_resp = requests.post(f"{BASE_URL}/login", json={"username": "testuser", "password": "testpass"})
        if login_resp.status_code != 200:
            return False
        token = login_resp.json().get("token")
        if not token:
            return False
        auth_header = {"Authorization": f"Bearer {token}"}

        # Create a profile
        profile_payload = {
            "name": "Test Profile",
            "interests": ["coding", "testing"],
            "preferences": {"theme": "dark"},
            "account_tier": "premium"
        }
        create_resp = requests.post(f"{BASE_URL}/profiles", json=profile_payload, headers=auth_header)
        if create_resp.status_code not in (200, 201):
            return False
        profile_data = create_resp.json()
        profile_id = profile_data.get("id")
        if not profile_id:
            return False
        if profile_data.get("user_id") != user_data["id"]:
            return False

        # Fetch the created profile
        fetch_resp = requests.get(f"{BASE_URL}/profiles/{profile_id}", headers=auth_header)
        if fetch_resp.status_code != 200:
            return False
        fetched_data = fetch_resp.json()
        if fetched_data.get("id") != profile_id:
            return False
        if fetched_data.get("user_id") != user_data["id"]:
            return False

        return True

    except requests.exceptions.RequestException:
        return False

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

