from pydantic import BaseModel
from reportlab.lib.pagesizes import letter
from reportlab.pdfgen import canvas
from reportlab.lib.utils import ImageReader

app = FastAPI()

users = {}
orders = {}
products = {}
invoices = {}
tokens = {}
next_user_id = 1
next_order_id = 1
next_product_id = 1
next_invoice_id = 1
next_token_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class OrderCreate(BaseModel):
    product_id: int
    quantity: int
    image_url: str = None

class ProductCreate(BaseModel):
    name: str
    price: float

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            global next_token_id
            token = f"tok_{next_token_id}"
            next_token_id += 1
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/products")
def create_product(req: ProductCreate, authorization: str = Header(None)):
    get_user_from_token(authorization)
    global next_product_id
    pid = next_product_id
    next_product_id += 1
    products[pid] = {"name": req.name, "price": req.price}
    return {"product_id": pid}

@app.get("/products/{product_id}")
def get_product(product_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    p = products.get(product_id)
    if not p:
        raise HTTPException(status_code=404, detail="Product not found")
    return p

@app.post("/orders")
def create_order(req: OrderCreate, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    global next_order_id
    oid = next_order_id
    next_order_id += 1
    orders[oid] = {"user_id": user_id, "product_id": req.product_id, "quantity": req.quantity, "image_url": req.image_url}
    return {"order_id": oid}

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    o = orders.get(order_id)
    if not o:
        raise HTTPException(status_code=404, detail="Order not found")
    return o

@app.post("/invoice/generate")
def generate_invoice(order_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    if order["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your order")

    product = products.get(order["product_id"])
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    c.drawString(100, 750, f"Invoice for Order #{order_id}")
    c.drawString(100, 730, f"Product: {product['name'] if product else 'Unknown'}")
    c.drawString(100, 710, f"Quantity: {order['quantity']}")
    c.drawString(100, 690, f"Price: ${product['price'] if product else 0}")

    if order.get("image_url"):
        try:
            resp = requests.get(order["image_url"], timeout=5)
            if resp.status_code == 200:
                img_data = io.BytesIO(resp.content)
                img = ImageReader(img_data)
                c.drawImage(img, 100, 500, width=200, height=200)
        except:
            pass

    c.showPage()
    c.save()
    buf.seek(0)

    global next_invoice_id
    inv_id = next_invoice_id
    next_invoice_id += 1
    invoices[inv_id] = {"order_id": order_id, "user_id": user_id}

    return StreamingResponse(buf, media_type="application/pdf", headers={"Content-Disposition": f"attachment; filename=invoice_{order_id}.pdf"})

