from typing import Optional
import secrets

app = FastAPI()

users = {}
employees = {}
timesheets = {}
tokens = {}
user_id_counter = 1
employee_id_counter = 1
timesheet_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str
    role: str = "employee"

class LoginRequest(BaseModel):
    username: str
    password: str

class EmployeeCreate(BaseModel):
    name: str

class TimesheetCreate(BaseModel):
    employee_id: int
    hours: float
    description: str

class TimesheetReview(BaseModel):
    status: str

def get_current_user(token: str):
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password, "role": req.role}
    return {"id": user_id, "username": req.username, "role": req.role}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/employees")
def create_employee(req: EmployeeCreate, authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user = get_current_user(token)
    global employee_id_counter
    emp_id = employee_id_counter
    employee_id_counter += 1
    employees[emp_id] = {"id": emp_id, "name": req.name}
    return employees[emp_id]

@app.get("/employees/{employee_id}")
def get_employee(employee_id: int, authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    get_current_user(token)
    if employee_id not in employees:
        raise HTTPException(status_code=404, detail="Employee not found")
    return employees[employee_id]

@app.post("/timesheets")
def create_timesheet(req: TimesheetCreate, authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user = get_current_user(token)
    if req.employee_id not in employees:
        raise HTTPException(status_code=404, detail="Employee not found")
    global timesheet_id_counter
    ts_id = timesheet_id_counter
    timesheet_id_counter += 1
    timesheets[ts_id] = {
        "id": ts_id,
        "employee_id": req.employee_id,
        "hours": req.hours,
        "description": req.description,
        "status": "pending"
    }
    return timesheets[ts_id]

@app.get("/timesheets/{timesheet_id}")
def get_timesheet(timesheet_id: int, authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user = get_current_user(token)
    if timesheet_id not in timesheets:
        raise HTTPException(status_code=404, detail="Timesheet not found")
    ts = timesheets[timesheet_id]
    # Check if the current user is allowed to access this timesheet
    # Find the employee associated with this timesheet
    emp_id = ts["employee_id"]
    # In this simplified model, we assume that only the employee themselves or a manager can view their timesheet.
    # Since there's no direct user <-> employee mapping, we simulate ownership via username match.
    # This assumes that when an employee was created, the username matches the employee name.
    # However, in our data model, employees are just names, and users are separate.
    # To enforce proper access control, we need to associate employees with users.
    # For now, let's allow managers to see all, and non-managers to only see if they "own" it.
    # As per existing structure, there is no explicit ownership. So we'll make a reasonable assumption:
    # A user can view a timesheet if:
    # - They are a manager, OR
    # - Their username matches the employee name associated with the timesheet (a weak proxy for ownership)
    emp = employees.get(emp_id)
    if not emp:
        raise HTTPException(status_code=500, detail="Inconsistent data: employee not found for timesheet")
    if user["role"] != "manager" and user["username"] != emp["name"]:
        raise HTTPException(status_code=403, detail="Not authorized to view this timesheet")
    return ts

@app.post("/timesheets/{timesheet_id}/review")
def review_timesheet(timesheet_id: int, req: TimesheetReview, authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user = get_current_user(token)
    if user["role"] != "manager":
        raise HTTPException(status_code=403, detail="Only managers can review")
    if timesheet_id not in timesheets:
        raise HTTPException(status_code=404, detail="Timesheet not found")
    timesheets[timesheet_id]["status"] = req.status
    return timesheets[timesheet_id]

