users = {}
tokens = {}
deliveries = {}
next_user_id = 1
next_delivery_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class DeliveryCreate(BaseModel):
    description: str
    status: str = "pending"

class DeliveryUpdate(BaseModel):
    status: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if any(u["username"] == req.username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password_hash": hash_password(req.password)}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password_hash"] == hash_password(req.password):
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/delivery/{delivery_id}")
def get_delivery(delivery_id: int, authorization: str = Header(None)):
    user_id = get_user_id_from_token(authorization)
    if delivery_id not in deliveries:
        raise HTTPException(status_code=404, detail="Delivery not found")
    return deliveries[delivery_id]

@app.post("/delivery")
def create_delivery(req: DeliveryCreate, authorization: str = Header(None)):
    global next_delivery_id
    user_id = get_user_id_from_token(authorization)
    delivery_id = next_delivery_id
    next_delivery_id += 1
    deliveries[delivery_id] = {
        "id": delivery_id,
        "description": req.description,
        "status": req.status,
        "created_by": user_id
    }
    return deliveries[delivery_id]

@app.put("/delivery/{delivery_id}/status")
def update_delivery_status(delivery_id: int, req: DeliveryUpdate, authorization: str = Header(None)):
    user_id = get_user_id_from_token(authorization)
    if delivery_id not in deliveries:
        raise HTTPException(status_code=404, detail="Delivery not found")
    deliveries[delivery_id]["status"] = req.status
    return deliveries[delivery_id]

@app.get("/track/{delivery_id}")
def track_delivery(delivery_id: int):
    if delivery_id not in deliveries:
        raise HTTPException(status_code=404, detail="Delivery not found")
    return {"id": delivery_id, "status": deliveries[delivery_id]["status"]}

