from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
properties = {}
agents = {}
next_user_id = 1
next_agent_id = 1
next_property_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str
    role: str = "buyer"

class LoginRequest(BaseModel):
    username: str
    password: str

class AgentCreate(BaseModel):
    name: str
    email: str
    phone: str

class PropertyCreate(BaseModel):
    title: str
    description: str
    price: float
    location: str
    agent_id: int

def get_current_user(token: str = Header(None)):
    if not token:
        raise HTTPException(status_code=401, detail="No token provided")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password, "role": req.role}
    return {"id": user_id, "username": req.username, "role": req.role}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/agents")
def create_agent(req: AgentCreate, token: str = Header(None)):
    user_id = get_current_user(token)
    user = users[user_id]
    if user["role"] != "agent":
        raise HTTPException(status_code=403, detail="Only agents can create agent profiles")
    global next_agent_id
    agent_id = next_agent_id
    next_agent_id += 1
    agents[agent_id] = {"id": agent_id, "name": req.name, "email": req.email, "phone": req.phone, "user_id": user_id}
    return agents[agent_id]

@app.get("/agents/{agent_id}")
def get_agent(agent_id: int):
    agent = agents.get(agent_id)
    if not agent:
        raise HTTPException(status_code=404, detail="Agent not found")
    return agent

@app.post("/properties")
def create_property(req: PropertyCreate, token: str = Header(None)):
    user_id = get_current_user(token)
    user = users[user_id]
    if user["role"] != "agent":
        raise HTTPException(status_code=403, detail="Only agents can list properties")
    if req.agent_id not in agents:
        raise HTTPException(status_code=400, detail="Agent not found")
    global next_property_id
    property_id = next_property_id
    next_property_id += 1
    properties[property_id] = {
        "id": property_id,
        "title": req.title,
        "description": req.description,
        "price": req.price,
        "location": req.location,
        "agent_id": req.agent_id
    }
    return properties[property_id]

@app.get("/properties/{property_id}")
def get_property(property_id: int):
    prop = properties.get(property_id)
    if not prop:
        raise HTTPException(status_code=404, detail="Property not found")
    return prop

