from typing import Optional, Dict
import secrets

app = FastAPI()

users = {}
tokens = {}
events = {}
bookings = {}
next_user_id = 1
next_event_id = 1
next_booking_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreateEventRequest(BaseModel):
    name: str
    total_seats: int

class CreateBookingRequest(BaseModel):
    event_id: int
    seats: int

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest, authorization: Optional[str] = Header(None)):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/events/{event_id}")
def get_event(event_id: int):
    if event_id not in events:
        raise HTTPException(status_code=404, detail="Event not found")
    return events[event_id]

@app.post("/events")
def create_event(req: CreateEventRequest, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_event_id
    event_id = next_event_id
    next_event_id += 1
    events[event_id] = {"id": event_id, "name": req.name, "total_seats": req.total_seats, "available_seats": req.total_seats}
    return events[event_id]

@app.get("/bookings/{booking_id}")
def get_booking(booking_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if booking_id not in bookings:
        raise HTTPException(status_code=404, detail="Booking not found")
    booking = bookings[booking_id]
    if booking["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return booking

@app.post("/bookings")
def create_booking(req: CreateBookingRequest, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if req.event_id not in events:
        raise HTTPException(status_code=404, detail="Event not found")
    event = events[req.event_id]
    if event["available_seats"] < req.seats:
        raise HTTPException(status_code=400, detail="Not enough seats available")
    global next_booking_id
    booking_id = next_booking_id
    next_booking_id += 1
    bookings[booking_id] = {"id": booking_id, "event_id": req.event_id, "user_id": user_id, "seats": req.seats}
    event["available_seats"] -= req.seats
    return bookings[booking_id]

