from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import uuid
import datetime

app = FastAPI()

users = {}
tokens = {}
habits = {}
habit_logs = {}
user_id_counter = 1
habit_id_counter = 1
log_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for user in users.values():
        if user["username"] == username and user["password"] == password:
            token = str(uuid.uuid4())
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/habits")
def create_habit(name: str, description: str = "", authorization: Optional[str] = Header(None)):
    global habit_id_counter
    current_user = get_current_user(authorization)
    habit_id = habit_id_counter
    habit_id_counter += 1
    habits[habit_id] = {"id": habit_id, "name": name, "description": description, "user_id": current_user}
    return habits[habit_id]

@app.get("/habits/{habit_id}")
def get_habit(habit_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if habit_id not in habits:
        raise HTTPException(status_code=404, detail="Habit not found")
    return habits[habit_id]

@app.post("/habit-logs")
def create_habit_log(habit_id: int, date: str, note: str = "", authorization: Optional[str] = Header(None)):
    global log_id_counter
    current_user = get_current_user(authorization)
    if habit_id not in habits:
        raise HTTPException(status_code=404, detail="Habit not found")
    if habits[habit_id]["user_id"] != current_user:
        raise HTTPException(status_code=403, detail="Not your habit")
    log_id = log_id_counter
    log_id_counter += 1
    habit_logs[log_id] = {"id": log_id, "habit_id": habit_id, "date": date, "note": note, "user_id": current_user}
    return habit_logs[log_id]

@app.get("/habit-logs/{log_id}")
def get_habit_log(log_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if log_id not in habit_logs:
        raise HTTPException(status_code=404, detail="Log not found")
    return habit_logs[log_id]

@app.get("/habits/{habit_id}/logs")
def get_habit_logs(habit_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if habit_id not in habits:
        raise HTTPException(status_code=404, detail="Habit not found")
    if habits[habit_id]["user_id"] != current_user:
        raise HTTPException(status_code=403, detail="Not your habit")
    logs = [log for log in habit_logs.values() if log["habit_id"] == habit_id]
    return logs

