from pydantic import BaseModel
from typing import Optional, Dict, Any
import secrets
import time

app = FastAPI()

orders = {}
users = {}
tokens = {}
user_counter = 0
order_counter = 0

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class OrderItem(BaseModel):
    name: str
    quantity: int

class OrderCreate(BaseModel):
    items: list[OrderItem]
    delivery_address: str
    special_instructions: Optional[str] = None

class OrderUpdate(BaseModel):
    items: Optional[list[OrderItem]] = None
    delivery_address: Optional[str] = None
    special_instructions: Optional[str] = None
    status: Optional[str] = None

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_counter += 1
    users[req.username] = {"id": user_counter, "username": req.username, "password": req.password}
    return {"id": user_counter, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = req.username
    return {"token": token}

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")
    return orders[order_id]

@app.post("/orders")
def create_order(req: OrderCreate, authorization: Optional[str] = Header(None)):
    global order_counter
    get_current_user(authorization)
    order_counter += 1
    order = {
        "id": order_counter,
        "items": [item.dict() for item in req.items],
        "delivery_address": req.delivery_address,
        "special_instructions": req.special_instructions,
        "status": "pending",
        "created_at": time.time()
    }
    orders[order_counter] = order
    return order

@app.put("/orders/{order_id}")
def update_order(order_id: int, req: OrderUpdate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")

    order = orders[order_id]

    if req.items is not None:
        order["items"] = [item.dict() for item in req.items]
    if req.delivery_address is not None:
        order["delivery_address"] = req.delivery_address
    if req.special_instructions is not None:
        order["special_instructions"] = req.special_instructions
    if req.status is not None:
        allowed_statuses = ["pending", "confirmed", "preparing", "out_for_delivery", "delivered", "cancelled"]
        if req.status not in allowed_statuses:
            raise HTTPException(status_code=400, detail=f"Invalid status. Allowed: {allowed_statuses}")
        order["status"] = req.status

    orders[order_id] = order
    return order

