import time

app = FastAPI()

users = {}
tokens = {}
bookings = {}
booking_id_counter = 1

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreateBookingRequest(BaseModel):
    check_in: str
    check_out: str
    room_type: str
    guest_count: int
    special_requests: Optional[str] = ""

class UpdateBookingRequest(BaseModel):
    check_in: Optional[str] = None
    check_out: Optional[str] = None
    room_type: Optional[str] = None
    guest_count: Optional[int] = None
    special_requests: Optional[str] = None

BASE_PRICES = {"single": 100, "double": 150, "suite": 250}

def calculate_price(check_in: str, check_out: str, room_type: str, guest_count: int):
    try:
        in_dt = time.strptime(check_in, "%Y-%m-%d")
        out_dt = time.strptime(check_out, "%Y-%m-%d")
        nights = max(1, (time.mktime(out_dt) - time.mktime(in_dt)) // 86400)
    except:
        nights = 1
    base = BASE_PRICES.get(room_type, 100)
    guest_mult = 1 + max(0, guest_count - 2) * 0.25
    return int(nights * base * guest_mult)

