    user = get_current_user(authorization)
    global booking_id_counter
    bid = booking_id_counter
    booking_id_counter += 1
    price = calculate_price(req.check_in, req.check_out, req.room_type, req.guest_count)
    bookings[bid] = {
        "id": bid,
        "user": user,
        "check_in": req.check_in,
        "check_out": req.check_out,
        "room_type": req.room_type,
        "guest_count": req.guest_count,
        "special_requests": req.special_requests,
        "total_price": price
    }
    return bookings[bid]

@app.get("/bookings/{booking_id}")
def get_booking(booking_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if booking_id not in bookings:
        raise HTTPException(status_code=404, detail="Booking not found")
    return bookings[booking_id]

@app.put("/bookings/{booking_id}")
def update_booking(booking_id: int, req: UpdateBookingRequest, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if booking_id not in bookings:
        raise HTTPException(status_code=404, detail="Booking not found")
    booking = bookings[booking_id]
    if booking["user"] != user:
