from fastapi import FastAPI, HTTPException, Header, status
from pydantic import BaseModel
from typing import Optional, List
from datetime import datetime
import secrets
import copy

app = FastAPI()

users = {}
tokens = {}
shipments = {}
shipment_id_counter = 0
user_id_counter = 0

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ShipmentCreate(BaseModel):
    origin: str
    destination: str
    weight: float
    carrier_tier: str

class ShipmentUpdate(BaseModel):
    origin: Optional[str] = None
    destination: Optional[str] = None
    weight: Optional[float] = None
    delivery_status: Optional[str] = None
    carrier_tier: Optional[str] = None

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    user_id_counter += 1
    users[user_id_counter] = {"id": user_id_counter, "username": req.username, "password": req.password}
    return {"id": user_id_counter, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/shipments/{shipment_id}")
def get_shipment(shipment_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    return shipments[shipment_id]

@app.post("/shipments")
def create_shipment(req: ShipmentCreate, authorization: str = Header(None)):
    global shipment_id_counter
    user_id = get_current_user(authorization)
    shipment_id_counter += 1
    shipment = {
        "id": shipment_id_counter,
        "origin": req.origin,
        "destination": req.destination,
        "weight": req.weight,
        "delivery_status": "pending",
        "carrier_tier": req.carrier_tier,
        "history": [],
        "created_by": user_id
    }
    shipments[shipment_id_counter] = shipment
    return shipment

@app.patch("/shipments/{shipment_id}")
def update_shipment(shipment_id: int, req: ShipmentUpdate, authorization: str = Header(None)):
    get_current_user(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")

    s = shipments[shipment_id]
    old = copy.deepcopy(s)

    if req.origin is not None:
        s["origin"] = req.origin
    if req.destination is not None:
        s["destination"] = req.destination
    if req.weight is not None:
        s["weight"] = req.weight
    if req.delivery_status is not None:
        s["delivery_status"] = req.delivery_status
    if req.carrier_tier is not None:
        s["carrier_tier"] = req.carrier_tier

    change_record = {
        "timestamp": datetime.utcnow().isoformat(),
        "old": old,
        "new": copy.deepcopy(s)
    }
    s["history"].append(change_record)

    return s

