            if len(user1_interests) + len(user2_interests) > 0:
                compatibility = round(len(user1_interests & user2_interests) / len(user1_interests | user2_interests) * 100, 2)
            else:
                compatibility = 0
            matches[match_id] = {
                "id": match_id,
