def get_user(user_id: int, authorization: str = Header(None)):
    current_user_id = get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    u = users[user_id]
    return {"id": u["id"], "username": u["username"], "age": u["age"], "bio": u["bio"], "interests": u["interests"]}

