import time

app = FastAPI()

users = {}
tokens = {}
items = {}
bids = {}
item_id_counter = 1
bid_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ItemCreate(BaseModel):
    name: str
    reserve_price: float

class BidCreate(BaseModel):
    amount: float

def get_current_user(authorization: str = Header(None)):
