from pydantic import BaseModel
from typing import Optional, List
import secrets

app = FastAPI()

users = {}
rides = {}
bookings = {}
tokens = {}
next_user_id = 1
next_ride_id = 1
next_booking_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class RideCreate(BaseModel):
    driver_id: int
    origin: str
    destination: str
    departure_time: str
    available_seats: int

class BookingCreate(BaseModel):
    ride_id: int
    passenger_id: int

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/rides")
def create_ride(ride: RideCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if ride.driver_id != user_id:
        raise HTTPException(status_code=403, detail="Driver ID mismatch")
    global next_ride_id
    ride_id = next_ride_id
    next_ride_id += 1
    rides[ride_id] = {
        "id": ride_id,
        "driver_id": ride.driver_id,
        "origin": ride.origin,
        "destination": ride.destination,
        "departure_time": ride.departure_time,
        "available_seats": ride.available_seats
    }
    return rides[ride_id]

@app.get("/rides/{ride_id}")
def get_ride(ride_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if ride_id not in rides:
        raise HTTPException(status_code=404, detail="Ride not found")
    ride = rides[ride_id].copy()
    passenger_ids = [b["passenger_id"] for b in bookings.values() if b["ride_id"] == ride_id]
    ride["passengers"] = [users[pid] for pid in passenger_ids if pid in users]
    return ride

@app.post("/bookings")
def create_booking(booking: BookingCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    # Fix: Ensure the authenticated user is the passenger
    if booking.passenger_id != user_id:
        raise HTTPException(status_code=403, detail="Passenger ID mismatch")
    if booking.ride_id not in rides:
        raise HTTPException(status_code=404, detail="Ride not found")
    ride = rides[booking.ride_id]
    if ride["available_seats"] <= 0:
        raise HTTPException(status_code=400, detail="No available seats")
    global next_booking_id
    booking_id = next_booking_id
    next_booking_id += 1
    bookings[booking_id] = {
        "id": booking_id,
        "ride_id": booking.ride_id,
        "passenger_id": booking.passenger_id
    }
    ride["available_seats"] -= 1
    return bookings[booking_id]

@app.get("/bookings/{booking_id}")
