from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import hashlib
import secrets

app = FastAPI()

users = {}
patients = {}
appointments = {}
medications = {}
visit_summaries = {}
tokens = {}
id_counter = {"users": 1, "patients": 1, "appointments": 1, "medications": 1, "visit_summaries": 1}

def generate_token():
    return secrets.token_hex(32)

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = id_counter["users"]
    id_counter["users"] += 1
    users[req.username] = {"id": user_id, "username": req.username, "password_hash": hash_password(req.password)}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    user = users[req.username]
    if user["password_hash"] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = user["id"]
    return {"token": token}

@app.get("/patients/{patient_id}")
def get_patient(patient_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if patient_id not in patients:
        raise HTTPException(status_code=404, detail="Patient not found")
    patient = patients[patient_id]
    patient["upcoming_appointments"] = [a for a in appointments.values() if a["patient_id"] == patient_id]
    patient["medication_list"] = [m for m in medications.values() if m["patient_id"] == patient_id]
    patient["last_visit_summary"] = [v for v in visit_summaries.values() if v["patient_id"] == patient_id]
    if patient["last_visit_summary"]:
        patient["last_visit_summary"] = max(patient["last_visit_summary"], key=lambda x: x["date"])
    else:
        patient["last_visit_summary"] = None
    return patient

@app.get("/patients")
def get_all_patients(authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    return list(patients.values())

@app.post("/patients")
def create_patient(name: str, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    patient_id = id_counter["patients"]
    id_counter["patients"] += 1
    patients[patient_id] = {"id": patient_id, "name": name}
    return patients[patient_id]

@app.get("/appointments/{appointment_id}")
def get_appointment(appointment_id: int, authorization: Optional[str] = Header(None)):
