from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import random
import string
from datetime import datetime

app = FastAPI()

users = {}
tokens = {}
players = {}
matches = {}
leaderboard = {}
next_user_id = 1
next_player_id = 1
next_match_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PlayerCreate(BaseModel):
    name: str

class MatchResult(BaseModel):
    player_id: int
    score: int
    win: bool

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if any(u['username'] == req.username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username exists")
    user_id = next_user_id
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    next_user_id += 1
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u['username'] == req.username and u['password'] == req.password:
            token = generate_token()
            tokens[token] = u['id']
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/players")
def create_player(player: PlayerCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_player_id
    player_id = next_player_id
    players[player_id] = {"id": player_id, "name": player.name, "total_matches": 0, "wins": 0, "total_score": 0}
    leaderboard[player_id] = {"player_id": player_id, "name": player.name, "score": 0, "wins": 0, "matches": 0}
    next_player_id += 1
    return players[player_id]

@app.get("/players/{player_id}")
def get_player(player_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if player_id not in players:
        raise HTTPException(status_code=404, detail="Player not found")
    return players[player_id]

@app.get("/leaderboard")
def get_leaderboard(authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    sorted_players = sorted(leaderboard.values(), key=lambda x: x['score'], reverse=True)
    result = []
    for rank, p in enumerate(sorted_players, 1):
        win_rate = (p['wins'] / p['matches'] * 100) if p['matches'] > 0 else 0
        result.append({
            "rank": rank,
            "player_id": p['player_id'],
            "name": p['name'],
            "score": p['score'],
            "win_rate": round(win_rate, 2)
        })
    return result

@app.post("/matches")
def record_match(match: MatchResult, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_match_id
    if match.player_id not in players:
        raise HTTPException(status_code=404, detail="Player not found")
    match_id = next_match_id
    matches[match_id] = {
        "id": match_id,
        "player_id": match.player_id,
        "score": match.score,
        "win": match.win,
        "timestamp": datetime.now().isoformat()
    }
    next_match_id += 1
    p = players[match.player_id]
    p['total_matches'] += 1
    p['total_score'] += match.score
    if match.win:
        p['wins'] += 1
    lb = leaderboard[match.player_id]
    lb['score'] += match.score
    lb['wins'] = p['wins']
    lb['matches'] = p['total_matches']
    return matches[match_id]

@app.get("/players/{player_id}/history")
def get_player_history(player_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if player_id not in players:
        raise HTTPException(status_code=404, detail="Player not found")
    player_matches = [m for m in matches.values() if m['player_id'] == player_id]
    player_matches.sort(key=lambda x: x['timestamp'], reverse=True)
    return player_matches[:10]

