    global car_id_counter
    get_user_id_from_token(authorization)
    cid = car_id_counter
    car_id_counter += 1
    cars[cid] = {"id": cid, "model": car.model, "mileage": car.mileage, "daily_rate": car.daily_rate}
    return cars[cid]

