    if booking_id not in bookings:
        raise HTTPException(status_code=404, detail="Booking not found")
    return bookings[booking_id]

@app.post("/bookings")
def create_booking(booking: BookingCreate, authorization: str = Header(None)):
    global booking_id_counter
    user_id = get_user_id_from_token(authorization)
    if booking.car_id not in cars:
        raise HTTPException(status_code=404, detail="Car not found")
    start = datetime.strptime(booking.start_date, "%Y-%m-%d").date()
    end = datetime.strptime(booking.end_date, "%Y-%m-%d").date()
    if start >= end:
        raise HTTPException(status_code=400, detail="start_date must be before end_date")
    for b in bookings.values():
        if b["car_id"] == booking.car_id:
            b_start = datetime.strptime(b["start_date"], "%Y-%m-%d").date()
            b_end = datetime.strptime(b["end_date"], "%Y-%m-%d").date()
            if not (end <= b_start or start >= b_end):
                raise HTTPException(status_code=400, detail="Car not available for those dates")
    bid = booking_id_counter
    booking_id_counter += 1
    bookings[bid] = {
        "id": bid,
        "car_id": booking.car_id,
        "user_id": user_id,
        "start_date": booking.start_date,
        "end_date": booking.end_date
    }
    return bookings[bid]

