from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import uuid
import hashlib

app = FastAPI()

users = {}
tokens = {}
resources = {}
resource_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ResourceCreate(BaseModel):
    name: str
    type: str
    city: str
    cost: float
    rating: float

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = hashlib.sha256(req.password.encode()).hexdigest()
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != hashlib.sha256(req.password.encode()).hexdigest():
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = req.username
    return {"token": token}

@app.get("/resources/{resource_id}")
def get_resource(resource_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if resource_id not in resources:
        raise HTTPException(status_code=404, detail="Resource not found")
    return resources[resource_id]

@app.post("/resources")
def create_resource(resource: ResourceCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global resource_id_counter
    rid = resource_id_counter
    resources[rid] = {
        "id": rid,
        "name": resource.name,
        "type": resource.type,
        "city": resource.city,
        "cost": resource.cost,
        "rating": resource.rating
    }
    resource_id_counter += 1
    return resources[rid]

@app.get("/resources")
def list_resources(
