import string
from datetime import datetime

app = FastAPI()

# In-memory storage
users = {}
tokens = {}
groups = {}
group_id_counter = 1

# Simple token generation
def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

# Auth dependency
def get_user_from_token(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class GroupCreate(BaseModel):
    subject: str
    level: str
    meeting_time: str
    max_members: int
    current_count: int = 0

class GroupUpdate(BaseModel):
    subject: Optional[str] = None
    level: Optional[str] = None
    meeting_time: Optional[str] = None
    max_members: Optional[int] = None
    current_count: Optional[int] = None

# Auth endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = {"username": req.username, "password": req.password}
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

# Groups endpoints
@app.get("/groups/{group_id}")
def get_group(group_id: int, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    if group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    return groups[group_id]

@app.post("/groups")
def create_group(group: GroupCreate, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    global group_id_counter
    gid = group_id_counter
    group_id_counter += 1
    groups[gid] = {
        "id": gid,
        "subject": group.subject,
        "level": group.level,
        "meeting_time": group.meeting_time,
        "max_members": group.max_members,
        "current_count": group.current_count
    }
    return groups[gid]

@app.get("/groups")
def list_groups(
    subject: Optional[str] = None,
    level: Optional[str] = None,
    day_of_week: Optional[str] = None,
    available_spots: Optional[bool] = None,
    authorization: Optional[str] = Header(None)
):
    get_user_from_token(authorization)
    result = []
    for gid, group in groups.items():
        if subject and group["subject"].lower() != subject.lower():
            continue
        if level and group["level"].lower() != level.lower():
            continue
        if day_of_week:
            try:
                dt = datetime.strptime(group["meeting_time"], "%Y-%m-%d %H:%M")
                day_names = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
                if day_names[dt.weekday()] != day_of_week.lower():
                    continue
            except:
                continue
        if available_spots is not None and available_spots:
            if group["current_count"] >= group["max_members"]:
                continue
        result.append(group)
    return result

@app.put("/groups/{group_id}")
def update_group(group_id: int, group_update: GroupUpdate, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    if group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    group = groups[group_id]
    if group_update.subject is not None:
        group["subject"] = group_update.subject
    if group_update.level is not None:
        group["level"] = group_update.level
    if group_update.meeting_time is not None:
        group["meeting_time"] = group_update.meeting_time
    if group_update.max_members is not None:
        group["max_members"] = group_update.max_members
    if group_update.current_count is not None:
        group["current_count"] = group_update.current_count
    return group

@app.delete("/groups/{group_id}")
def delete_group(group_id: int, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    if group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    del groups[group_id]
    return {"ok": True}

