from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import time

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
quizzes = {}
questions = {}
answers = {}
scores = {}

# ID counters
user_id_counter = 1
quiz_id_counter = 1
question_id_counter = 1
answer_id_counter = 1
score_id_counter = 1

# Models
class UserCreate(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class QuizCreate(BaseModel):
    title: str
    teacher_id: int

class QuestionCreate(BaseModel):
    quiz_id: int
    question_type: str  # "multiple_choice" or "text"
    question_text: str
    correct_answer: str
    options: Optional[list] = None

class AnswerSubmission(BaseModel):
    student_id: int
    quiz_id: int
    answers: list  # list of {"question_id": int, "answer": str}

# Auth helper
def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No token provided")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Endpoints
@app.post("/signup")
def signup(user: UserCreate):
    global user_id_counter
    for u in users.values():
        if u["username"] == user.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    uid = user_id_counter
    user_id_counter += 1
    users[uid] = {"id": uid, "username": user.username, "password": user.password, "role": "student"}
    return {"user_id": uid, "message": "User created"}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/quizzes")
def create_quiz(quiz: QuizCreate, authorization: str = Header(None)):
    teacher_id = get_user_from_token(authorization)
    global quiz_id_counter
    qid = quiz_id_counter
    quiz_id_counter += 1
    quizzes[qid] = {"id": qid, "title": quiz.title, "teacher_id": teacher_id, "questions": []}
    return {"quiz_id": qid}

@app.get("/quizzes/{quiz_id}")
def get_quiz(quiz_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    return quizzes[quiz_id]

@app.post("/questions")
def create_question(question: QuestionCreate, authorization: str = Header(None)):
    teacher_id = get_user_from_token(authorization)
    if question.quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    if quizzes[question.quiz_id]["teacher_id"] != teacher_id:
        raise HTTPException(status_code=403, detail="Not your quiz")
    global question_id_counter
    qid = question_id_counter
    question_id_counter += 1
    questions[qid] = {
        "id": qid,
        "quiz_id": question.quiz_id,
        "question_type": question.question_type,
        "question_text": question.question_text,
        "correct_answer": question.correct_answer,
        "options": question.options
    }
    quizzes[question.quiz_id]["questions"].append(qid)
    return {"question_id": qid}

@app.get("/questions/{question_id}")
def get_question(question_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if question_id not in questions:
        raise HTTPException(status_code=404, detail="Question not found")
    return questions[question_id]

@app.post("/answers")
def submit_answers(submission: AnswerSubmission, authorization: str = Header(None)):
    student_id = get_user_from_token(authorization)
    if submission.quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    if student_id != submission.student_id:
        raise HTTPException(status_code=403, detail="Cannot submit for another student")

    quiz = quizzes[submission.quiz_id]
    total_questions = len(quiz["questions"])
    correct_count = 0

    answer_records = []
    for ans in submission.answers:
        qid = ans["question_id"]
        if qid not in questions or questions[qid]["quiz_id"] != submission.quiz_id:
            continue
        question = questions[qid]
        is_correct = ans["answer"].strip().lower() == question["correct_answer"].strip().lower()
        if is_correct:
            correct_count += 1
        answer_records.append({
            "question_id": qid,
            "student_answer": ans["answer"],
            "is_correct": is_correct
        })

    global answer_id_counter
    aid = answer_id_counter
    answer_id_counter += 1
    answers[aid] = {
        "id": aid,
        "student_id": student_id,
        "quiz_id": submission.quiz_id,
        "answers": answer_records
    }

    score = (correct_count / total_questions * 100) if total_questions > 0 else 0
    global score_id_counter
    sid = score_id_counter
    score_id_counter += 1
    scores[sid] = {
        "id": sid,
        "student_id": student_id,
        "quiz_id": submission.quiz_id,
        "score": score,
        "correct": correct_count,
        "total": total_questions
    }

    return {"answer_id": aid, "score_id": sid, "score": score}

@app.get("/answers/{answer_id}")
def get_answer(answer_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if answer_id not in answers:
        raise HTTPException(status_code=404, detail="Answer not found")
    return answers[answer_id]

@app.get("/scores/{score_id}")
def get_score(score_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if score_id not in scores:
        raise HTTPException(status_code=404, detail="Score not found")
    return scores[score_id]

