def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password_hash": hash_password(password)}
    return {"user_id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password_hash"] == hash_password(password):
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/agency")
def create_agency(name: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_agency_id
    agency_id = next_agency_id
    next_agency_id += 1
    agencies[agency_id] = {"id": agency_id, "name": name}
