    get_current_user(authorization)
    agency = agencies.get(agency_id)
    if not agency:
        raise HTTPException(status_code=404, detail="Agency not found")
    return agency

@app.post("/incident")
def create_incident(route_id: int, description: str, delay_minutes: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_incident_id
    incident_id = next_incident_id
    next_incident_id += 1
    incidents[incident_id] = {
