from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
flights = {}
hotels = {}
activities = {}
trips = {}
trip_items = {}

user_id_counter = 1
flight_id_counter = 1
hotel_id_counter = 1
activity_id_counter = 1
trip_id_counter = 1
trip_item_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class FlightCreate(BaseModel):
    airline: str
    flight_number: str
    departure: str
    arrival: str
    cost: float

class HotelCreate(BaseModel):
    name: str
    location: str
    check_in: str
    check_out: str
    cost: float

class ActivityCreate(BaseModel):
    name: str
    location: str
    date: str
    cost: float

class TripCreate(BaseModel):
    name: str

class TripItemCreate(BaseModel):
    trip_id: int
    resource_type: str
    resource_id: int

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid token")
    token = authorization[7:]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[req.username] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/flights")
def create_flight(flight: FlightCreate, authorization: str = Header(...)):
    get_current_user(authorization)
    global flight_id_counter
    flight_id = flight_id_counter
    flight_id_counter += 1
    flights[flight_id] = {"id": flight_id, **flight.dict()}
    return flights[flight_id]

@app.get("/flights/{flight_id}")
def get_flight(flight_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if flight_id not in flights:
        raise HTTPException(status_code=404, detail="Flight not found")
    return flights[flight_id]

@app.post("/hotels")
def create_hotel(hotel: HotelCreate, authorization: str = Header(...)):
    get_current_user(authorization)
    global hotel_id_counter
    hotel_id = hotel_id_counter
    hotel_id_counter += 1
    hotels[hotel_id] = {"id": hotel_id, **hotel.dict()}
    return hotels[hotel_id]

@app.get("/hotels/{hotel_id}")
