    get_current_user(authorization)
    global trip_id_counter
    trip_id = trip_id_counter
    trip_id_counter += 1
    trips[trip_id] = {"id": trip_id, "name": trip.name, "items": []}
    return trips[trip_id]

@app.get("/trips/{trip_id}")
def get_trip(trip_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    return trips[trip_id]

@app.post("/trip_items")
def add_trip_item(item: TripItemCreate, authorization: str = Header(...)):
    get_current_user(authorization)
    if item.trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    resource_map = {"flight": flights, "hotel": hotels, "activity": activities}
    if item.resource_type not in resource_map:
        raise HTTPException(status_code=400, detail="Invalid resource type")
    if item.resource_id not in resource_map[item.resource_type]:
        raise HTTPException(status_code=404, detail="Resource not found")
    global trip_item_id_counter
    trip_item_id = trip_item_id_counter
    trip_item_id_counter += 1
    trip_item = {"id": trip_item_id, "trip_id": item.trip_id, "resource_type": item.resource_type, "resource_id": item.resource_id}
    trip_items[trip_item_id] = trip_item
    trips[item.trip_id]["items"].append(trip_item)
    return trip_item

@app.get("/trips/{trip_id}/cost")
def get_trip_cost(trip_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    total = 0.0
