import requests
import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Signup
    signup_resp = session.post(f"{BASE_URL}/signup", json={
        "username": "testuser",
        "password": "testpass"
    })
    if signup_resp.status_code != 200:
        return False
    user_id = signup_resp.json().get("user_id")
    if not user_id:
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", json={
        "username": "testuser",
        "password": "testpass"
    })
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    headers = {"Authorization": f"Bearer {token}"}

    # Create a plan
    plan_resp = session.post(f"{BASE_URL}/plans", json={
        "name": "Basic",
        "delivery_frequency_days": 7,
        "theme": "Standard",
        "price_per_month": 29.99
    }, headers=headers)
    if plan_resp.status_code != 200:
        return False
    plan_id = plan_resp.json().get("id")
    if not plan_id:
        return False

    # Create subscription for own user
    sub_resp = session.post(f"{BASE_URL}/subscriptions", json={
        "user_id": user_id,
        "plan_id": plan_id,
        "start_date": "2025-01-01"
    }, headers=headers)
    if sub_resp.status_code != 200:
        return False
    sub_id = sub_resp.json().get("id")
    if not sub_id:
        return False

    # Fetch own subscription
    fetch_resp = session.get(f"{BASE_URL}/subscriptions/{sub_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    fetched_sub = fetch_resp.json()
    if fetched_sub.get("user_id") != user_id:
        return False
    if fetched_sub.get("id") != sub_id:
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

