from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
drivers = {}
deliveries = {}

user_counter = 0
driver_counter = 0
delivery_counter = 0


class SignupRequest(BaseModel):
    username: str
    password: str


class LoginRequest(BaseModel):
    username: str
    password: str


def get_user_from_token(authorization: Optional[str]):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing token")
    token = authorization.replace("Bearer ", "").strip()
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return users[user_id]


@app.post("/signup")
def signup(req: dict):
    global user_counter
    user_counter += 1
    record = dict(req)
    record["id"] = user_counter
    users[user_counter] = record
    return record


@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user.get("username") == req.username and user.get("password") == req.password:
            token = secrets.token_hex(16)
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Bad credentials")


@app.post("/drivers")
def register_driver(req: dict, authorization: Optional[str] = Header(None)):
    global driver_counter
    user = get_user_from_token(authorization)
    driver_counter += 1
    record = dict(req)
    record["id"] = driver_counter
    record["user_id"] = user["id"]
    drivers[driver_counter] = record
    return record


@app.get("/drivers/{driver_id}")
def get_driver(driver_id: int, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    driver = drivers.get(driver_id)
    if driver is None:
        raise HTTPException(status_code=404, detail="Driver not found")
    return driver


@app.post("/deliveries")
def create_delivery(req: dict, authorization: Optional[str] = Header(None)):
    global delivery_counter
    user = get_user_from_token(authorization)
    delivery_counter += 1
    record = dict(req)
    record["id"] = delivery_counter
    record["user_id"] = user["id"]
    deliveries[delivery_counter] = record
    return record


@app.get("/deliveries/{delivery_id}")
def get_delivery(delivery_id: int, authorization: Optional[str] = Header(None)):
    user = get_user_from_token(authorization)
    delivery = deliveries.get(delivery_id)
    if delivery is None:
        raise HTTPException(status_code=404, detail="Delivery not found")
    if delivery.get("user_id") != user["id"]:
        raise HTTPException(status_code=403, detail="Forbidden")
    return delivery


@app.post("/deliveries/{delivery_id}/assign")
def assign_delivery(delivery_id: int, req: dict, authorization: Optional[str] = Header(None)):
    user = get_user_from_token(authorization)
    delivery = deliveries.get(delivery_id)
    if delivery is None:
        raise HTTPException(status_code=404, detail="Delivery not found")
    if delivery.get("user_id") != user["id"]:
        raise HTTPException(status_code=403, detail="Forbidden")
    delivery["driver_id"] = req.get("driver_id")
