from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
loans = {}

user_counter = 0
loan_counter = 0


class SignupRequest(BaseModel):
    username: str
    password: str

    class Config:
        extra = "allow"


class LoginRequest(BaseModel):
    username: str
    password: str


class LoanRequest(BaseModel):
    amount: float
    term_months: int

    class Config:
        extra = "allow"


def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing token")
    token = authorization.replace("Bearer ", "").strip()
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id


@app.post("/signup")
def signup(req: SignupRequest):
    global user_counter
    user_counter += 1
    data = req.dict()
    data["id"] = user_counter
    data.setdefault("role", "member")
    data.setdefault("is_admin", False)
    users[user_counter] = data
    return {"id": user_counter, "username": data["username"]}


@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Bad credentials")


@app.post("/loans")
def create_loan(req: LoanRequest, authorization: Optional[str] = Header(None)):
    global loan_counter
    user_id = get_current_user(authorization)
    loan_counter += 1
    data = req.dict()
    data["id"] = loan_counter
    data["user_id"] = user_id
    data.setdefault("status", "pending")
    loans[loan_counter] = data
    return data


@app.get("/loans/{loan_id}")
def get_loan(loan_id: int):
    loan = loans.get(loan_id)
    if loan is None:
        raise HTTPException(status_code=404, detail="Loan not found")
    return loan


@app.get("/users/{user_id}")
def get_user(user_id: int):
    user = users.get(user_id)
    if user is None:
        raise HTTPException(status_code=404, detail="User not found")
    return user

