    password = "pass_" + secrets.token_hex(8)

    # Signup
    r = requests.post(f"{BASE}/signup", json={"username": username, "password": password})
    if r.status_code not in (200, 201):
        return False

    # Login
    r = requests.post(f"{BASE}/login", json={"username": username, "password": password})
    if r.status_code != 200:
        return False
    data = r.json()
    token = data.get("token") or data.get("access_token")
    if not token:
        return False

    headers = {"Authorization": f"Bearer {token}"}

    # Create locker
    payload = {"name": "my_locker", "contents": "secret_stuff"}
    r = requests.post(f"{BASE}/lockers", json=payload, headers=headers)
    if r.status_code not in (200, 201):
        return False
    locker = r.json()
    locker_id = locker.get("id")
    if locker_id is None:
        return False

    # Fetch own locker
    r = requests.get(f"{BASE}/lockers/{locker_id}", headers=headers)
    if r.status_code != 200:
        return False
    fetched = r.json()
    if fetched.get("id") != locker_id:
