from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
rentals = {}

user_counter = 0
rental_counter = 0


class SignupRequest(BaseModel):
    username: str
    password: str

    class Config:
        extra = "allow"


class LoginRequest(BaseModel):
    username: str
    password: str


class RentalRequest(BaseModel):
    gear_type: str
    days: int

    class Config:
        extra = "allow"


def get_user_from_token(authorization: Optional[str]):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing token")
    token = authorization.replace("Bearer ", "").strip()
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id


@app.post("/signup")
def signup(req: SignupRequest):
    global user_counter
    user_counter += 1
    data = req.dict()
    record = {
        "id": user_counter,
        "username": data["username"],
        "password": data["password"],
        "role": "user",
    }
    for k, v in data.items():
        record[k] = v
    record["id"] = user_counter
    users[user_counter] = record
    return {"id": user_counter, "username": record["username"], "role": record["role"]}


@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Bad credentials")


@app.get("/users/{user_id}")
def get_user(user_id: int):
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="Not found")
    return user


@app.post("/rentals")
def create_rental(req: RentalRequest, authorization: Optional[str] = Header(None)):
    global rental_counter
    user_id = get_user_from_token(authorization)
    rental_counter += 1
    data = req.dict()
    record = {
        "id": rental_counter,
        "user_id": user_id,
        "gear_type": data["gear_type"],
        "days": data["days"],
        "status": "reserved",
    }
    for k, v in data.items():
        record[k] = v
    record["id"] = rental_counter
    rentals[rental_counter] = record
    return record


@app.get("/rentals/{rental_id}")
def get_rental(rental_id: int):
    rental = rentals.get(rental_id)
    if not rental:
        raise HTTPException(status_code=404, detail="Not found")
    return rental


@app.get("/rentals")
def list_rentals():
    return list(rentals.values())


@app.get("/")
def root():
    return {"service": "ski-rental-api"}

