from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
import hashlib
import secrets
import uuid

app = FastAPI()

users = {}
tokens = {}
tasks = {}
task_id_counter = 1
team_stats_history = []
daily_stats = {}

def generate_token():
    return secrets.token_hex(16)

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = len(users) + 1
    users[username] = {"id": user_id, "username": username, "password": hash_password(password)}
    token = generate_token()
    tokens[token] = username
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username]["password"] != hash_password(password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = username
    return {"token": token}

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if user_id not in [u["id"] for u in users.values()]:
        raise HTTPException(status_code=404, detail="User not found")
    user = next(u for u in users.values() if u["id"] == user_id)
    return {"id": user["id"], "username": user["username"]}

@app.post("/users")
def create_user(username: str, password: str):
    return signup(username, password)

@app.get("/tasks/{task_id}")
def get_task(task_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if task_id not in tasks:
        raise HTTPException(status_code=404, detail="Task not found")
    return tasks[task_id]

@app.post("/tasks")
def create_task(title: str, assigned_to: str, authorization: str = Header(None)):
    global task_id_counter
    current_user = get_current_user(authorization)
    task = {
        "id": task_id_counter,
        "title": title,
        "assigned_to": assigned_to,
        "status": "pending",
        "created_at": datetime.utcnow().isoformat(),
        "completed_at": None
    }
    tasks[task_id_counter] = task
    task_id_counter += 1
    return task

@app.post("/tasks/{task_id}/complete")
def complete_task(task_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if task_id not in tasks:
        raise HTTPException(status_code=404, detail="Task not found")
    tasks[task_id]["status"] = "completed"
    tasks[task_id]["completed_at"] = datetime.utcnow().isoformat()
    return tasks[task_id]

@app.get("/team/stats")
def get_team_stats(authorization: str = Header(None)):
    current_user = get_current_user(authorization)

    today = datetime.utcnow().date()
    today_tasks = [t for t in tasks.values() if t["completed_at"] and datetime.fromisoformat(t["completed_at"]).date() == today]

    completed_today = len(today_tasks)

    completion_times = []
    for t in today_tasks:
        created = datetime.fromisoformat(t["created_at"])
        completed = datetime.fromisoformat(t["completed_at"])
        completion_times.append((completed - created).total_seconds() / 60)

    avg_completion_time = sum(completion_times) / len(completion_times) if completion_times else 0

    user_completions = {}
    for t in today_tasks:
        user = t["assigned_to"]
        created = datetime.fromisoformat(t["created_at"])
        completed = datetime.fromisoformat(t["completed_at"])
        time_taken = (completed - created).total_seconds() / 60
        if user not in user_completions:
            user_completions[user] = {"count": 0, "total_time": 0}
        user_completions[user]["count"] += 1
        user_completions[user]["total_time"] += time_taken

    top_performer = None
    best_velocity = float('inf')
    for user, stats in user_completions.items():
        velocity = stats["total_time"] / stats["count"] if stats["count"] > 0 else float('inf')
        if velocity < best_velocity:
            best_velocity = velocity
            top_performer = user

    stats = {
        "date": today.isoformat(),
        "tasks_completed_today": completed_today,
        "avg_completion_time_minutes": round(avg_completion_time, 2),
        "top_performer": top_performer,
        "top_performer_avg_time_minutes": round(best_velocity, 2) if top_performer else 0
    }

    daily_stats[today.isoformat()] = stats

    return stats

@app.get("/team/stats/history")
def get_stats_history(authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    return list(daily_stats.values())

