from pydantic import BaseModel
from typing import Optional, List
import yfinance as yf
import numpy as np
from datetime import datetime, timedelta
import hashlib
import random
import string

app = FastAPI()

users = {}
tokens = {}
orders = {}

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def hash_password(password: str):
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class OrderCreate(BaseModel):
    ticker: str
    quantity: int
    price: float

class PortfolioRequest(BaseModel):
    tickers: List[str]
    weights: List[float]
    start_date: str
    end_date: str

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/orders")
def create_order(order: OrderCreate, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    order_id = len(orders) + 1
    orders[order_id] = {"id": order_id, "user": user, **order.dict()}
    return orders[order_id]

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")
    return orders[order_id]

@app.get("/returns")
def portfolio_returns(tickers: str, weights: str, start_date: str, end_date: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    ticker_list = [t.strip() for t in tickers.split(",")]
    weight_list = [float(w.strip()) for w in weights.split(",")]

    if len(ticker_list) != len(weight_list):
        raise HTTPException(status_code=400, detail="Tickers and weights length mismatch")

    if abs(sum(weight_list) - 1.0) > 0.01:
        raise HTTPException(status_code=400, detail="Weights must sum to 1")

    data = yf.download(ticker_list, start=start_date, end=end_date)["Adj Close"]
    if data.empty:
        raise HTTPException(status_code=400, detail="No data for given range")

    returns = data.pct_change().dropna()
    portfolio_returns = (returns * weight_list).sum(axis=1)

    # VaR (95% confidence)
    var_95 = np.percentile(portfolio_returns, 5)

    # Sharpe ratio (assuming 0% risk-free rate)
    sharpe = portfolio_returns.mean() / portfolio_returns.std() * np.sqrt(252)

    # Max drawdown
    cumulative = (1 + portfolio_returns).cumprod()
    running_max = cumulative.cummax()
    drawdown = (cumulative - running_max) / running_max
    max_drawdown = drawdown.min()

    return {
        "var_95": round(var_95, 4),
        "sharpe_ratio": round(sharpe, 4),
        "max_drawdown": round(max_drawdown, 4)
    }

