app = FastAPI()

users = {}
tokens = {}
pull_history = {}
lootbox_items = []

rarities = ["common", "uncommon", "rare", "legendary"]
rarity_weights = [0.5, 0.3, 0.15, 0.05]
value_ranges = {
    "common": (1, 10),
    "uncommon": (10, 50),
    "rare": (50, 200),
    "legendary": (200, 1000)
}

item_names = [
    "Shadow Blade", "Phoenix Feather", "Dragon Scale", "Elixir of Power",
    "Mystic Orb", "Iron Shield", "Healing Salve", "Thunder Staff",
    "Crystal Amulet", "Warp Stone", "Frost Ring", "Ember Tome",
    "Void Shard", "Storm Bow", "Guardian Helm", "Soul Gem"
]

for name in item_names:
    rarity = random.choices(rarities, weights=rarity_weights)[0]
    min_val, max_val = value_ranges[rarity]
    value = round(random.uniform(min_val, max_val), 2)
    lootbox_items.append({
        "id": len(lootbox_items) + 1,
        "name": name,
        "rarity": rarity,
        "value": value
    })

