from pydantic import BaseModel
from typing import Optional, List, Dict
import random
import string

app = FastAPI()

users = {}
tokens = {}
quizzes = {}
quiz_questions = {}
quiz_answers = {}
next_user_id = 1
next_quiz_id = 1
next_token_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_user_from_token(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class QuizQuestion(BaseModel):
    question: str
    options: List[str]
    correct_answer: str

class QuizCreate(BaseModel):
    title: str
    questions: List[QuizQuestion]

class AnswerSubmission(BaseModel):
    student_name: str
    answers: Dict[int, str]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username exists")
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"username": req.username, "password": req.password}
    return {"user_id": uid}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = generate_token()
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/quiz")
def create_quiz(quiz: QuizCreate, authorization: str = Header(...)):
    uid = get_user_from_token(authorization)
    global next_quiz_id
    qid = next_quiz_id
    next_quiz_id += 1
    quizzes[qid] = {"title": quiz.title, "owner": uid, "questions": []}
    quiz_questions[qid] = {}
    for i, q in enumerate(quiz.questions):
        qnum = i + 1
        quiz_questions[qid][qnum] = {
            "question": q.question,
            "options": q.options,
            "correct_answer": q.correct_answer
        }
        quizzes[qid]["questions"].append(qnum)
    quiz_answers[qid] = {}
    return {"quiz_id": qid}

@app.get("/quiz/{quiz_id}")
def get_quiz(quiz_id: int, authorization: str = Header(...)):
    get_user_from_token(authorization)
    if quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    q = quizzes[quiz_id]
    questions_list = []
    for qnum in q["questions"]:
        qdata = quiz_questions[quiz_id][qnum]
        questions_list.append({
            "question_number": qnum,
            "question": qdata["question"],
            "options": qdata["options"]
        })
    return {"quiz_id": quiz_id, "title": q["title"], "questions": questions_list}

@app.post("/quiz/{quiz_id}/submit")
def submit_answers(quiz_id: int, submission: AnswerSubmission, authorization: str = Header(...)):
    get_user_from_token(authorization)
    if quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    student = submission.student_name
    if student in quiz_answers[quiz_id]:
        raise HTTPException(status_code=400, detail="Student already submitted")
    score = 0
    total = len(quiz_questions[quiz_id])
    for qnum, ans in submission.answers.items():
        if qnum in quiz_questions[quiz_id]:
            if ans == quiz_questions[quiz_id][qnum]["correct_answer"]:
                score += 1
    quiz_answers[quiz_id][student] = {"score": score, "total": total}
    return {"student": student, "score": score, "total": total}

@app.get("/quiz/{quiz_id}/results")
def get_results(quiz_id: int, authorization: str = Header(...)):
    uid = get_user_from_token(authorization)
    if quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    if quizzes[quiz_id]["owner"] != uid:
        raise HTTPException(status_code=403, detail="Not authorized to view these results")
    answers = quiz_answers[quiz_id]
    if not answers:
        return {"quiz_id": quiz_id, "students": [], "aggregate": {}}
    scores = [a["score"] for a in answers.values()]
    total_q = list(answers.values())[0]["total"]
    scores_sorted = sorted(scores)
    n = len(scores_sorted)
    if n % 2 == 1:
        median = scores_sorted[n // 2]
    else:
        median = (scores_sorted[n // 2 - 1] + scores_sorted[n // 2]) / 2
    distribution = {}
    for s in scores:
        distribution[s] = distribution.get(s, 0) + 1
    students = []
    for name, data in answers.items():
        students.append({"name": name, "score": data["score"], "total": data["total"]})
    return {
        "quiz_id": quiz_id,
        "students": students,
        "aggregate": {
            "median": median,
            "distribution": distribution,
            "total_students": n
        }
    }

