        "price": listing.price,
        "bedrooms": listing.bedrooms,
        "sqft": listing.sqft,
        "days_on_market": listing.days_on_market,
        "price_per_sqft": round(listing.price / listing.sqft, 2) if listing.sqft > 0 else 0,
        "created_by": user_id
    }
    return listings[listing_id]

@app.post("/listings/bulk")
def bulk_upload(bulk: ListingBulk, authorization: str = Header(...)):
