    global listing_id_counter
    created = []
    for listing in bulk.listings:
        listing_id = listing_id_counter
        listing_id_counter += 1
        listings[listing_id] = {
            "id": listing_id,
            "title": listing.title,
            "price": listing.price,
            "bedrooms": listing.bedrooms,
