    bedrooms: Optional[int] = None,
    min_sqft: Optional[float] = None,
    max_sqft: Optional[float] = None,
    authorization: str = Header(...)
):
    user_id = get_user_id_from_token(authorization)
    results = []
    for lid, listing in listings.items():
        if min_price is not None and listing["price"] < min_price:
            continue
        if max_price is not None and listing["price"] > max_price:
            continue
        if bedrooms is not None and listing["bedrooms"] != bedrooms:
            continue
        if min_sqft is not None and listing["sqft"] < min_sqft:
            continue
        if max_sqft is not None and listing["sqft"] > max_sqft:
            continue
        results.append(listing)
    results.sort(key=lambda x: (x["price_per_sqft"], x["days_on_market"]))
    return results

