from fastapi import FastAPI, HTTPException, Header, Depends
from datetime import datetime, timedelta
import secrets
import hashlib
from typing import Optional

app = FastAPI()

users = {}
tokens = {}
doctors = {
    1: {"name": "Dr. Smith", "specialty": "Cardiology"},
    2: {"name": "Dr. Jones", "specialty": "Dermatology"},
    3: {"name": "Dr. Lee", "specialty": "Pediatrics"},
    4: {"name": "Dr. Patel", "specialty": "Orthopedics"}
}
slots = {}
bookings = {}
booking_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[username] = hashlib.sha256(password.encode()).hexdigest()
    return {"message": "User created"}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != hashlib.sha256(password.encode()).hexdigest():
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

@app.get("/available-slots")
def get_available_slots(user: str = Depends(get_current_user)):
    now = datetime.now()
    available = []
    for doc_id, doc in doctors.items():
        for day_offset in range(7):
            day = now + timedelta(days=day_offset)
            if day.weekday() >= 5:
                continue
            for hour in range(9, 17):
                slot_time = day.replace(hour=hour, minute=0, second=0, microsecond=0)
                if slot_time <= now:
                    continue
                slot_id = f"{doc_id}_{slot_time.isoformat()}"
                if slot_id not in slots:
                    slots[slot_id] = {"doctor_id": doc_id, "time": slot_time, "booked": False}
                if not slots[slot_id]["booked"]:
                    available.append({
                        "slot_id": slot_id,
                        "doctor_name": doc["name"],
                        "specialty": doc["specialty"],
                        "time": slot_time.isoformat()
                    })
    return available

@app.post("/book")
