from pydantic import BaseModel
from typing import Optional, List
import secrets
import datetime

app = FastAPI()

users = {}
articles = {}
edit_history = {}
tokens = {}
next_user_id = 1
next_article_id = 1
next_history_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str
    role: str = "editor"

class LoginRequest(BaseModel):
    username: str
    password: str

class ArticleCreate(BaseModel):
    title: str
    content: str
    author_name: str
    category: str
    status: str = "draft"

class ArticleUpdate(BaseModel):
    status: Optional[str] = None
    author_name: Optional[str] = None
    category: Optional[str] = None
    editor_role: Optional[str] = None

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="User exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password,
        "role": req.role
    }
    return {"id": user_id, "username": req.username, "role": req.role}

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = user
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/articles")
def create_article(article: ArticleCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global next_article_id, next_history_id
    article_id = next_article_id
    next_article_id += 1
    now = datetime.datetime.utcnow().isoformat()
    articles[article_id] = {
        "id": article_id,
        "title": article.title,
        "content": article.content,
        "author_name": article.author_name,
        "category": article.category,
        "status": article.status,
        "created_by": user["id"],
        "created_at": now,
        "updated_at": now
    }
    edit_history[article_id] = []
    history_entry = {
        "id": next_history_id,
        "article_id": article_id,
        "edited_by": user["id"],
        "timestamp": now,
        "changes": {
            "status": article.status,
            "author_name": article.author_name,
            "category": article.category,
            "editor_role": user["role"]
        }
    }
    next_history_id += 1
    edit_history[article_id].append(history_entry)
    return articles[article_id]

