    if article_id not in articles:
        raise HTTPException(status_code=404, detail="Article not found")
    return articles[article_id]

@app.patch("/articles/{article_id}")
def update_article(article_id: int, update: ArticleUpdate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if article_id not in articles:
        raise HTTPException(status_code=404, detail="Article not found")
    global next_history_id
    article = articles[article_id]
    now = datetime.datetime.utcnow().isoformat()
    changes = {}
    if update.status is not None:
        changes["status"] = update.status
        article["status"] = update.status
    if update.author_name is not None:
        changes["author_name"] = update.author_name
        article["author_name"] = update.author_name
    if update.category is not None:
        changes["category"] = update.category
        article["category"] = update.category
    if update.editor_role is not None:
