        "article_id": article_id,
        "edited_by": user["id"],
        "timestamp": now,
        "changes": changes
    }
    next_history_id += 1
    edit_history[article_id].append(history_entry)
    return article

@app.get("/articles/{article_id}/history")
def get_article_history(article_id: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if article_id not in articles:
        raise HTTPException(status_code=404, detail="Article not found")
    return edit_history.get(article_id, [])

