from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import secrets
import hashlib

app = FastAPI()

users = {}
tokens = {}
playlists = {}
playlist_id_counter = 1
user_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreatePlaylistRequest(BaseModel):
    title: str
    artist: str

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[len("Bearer "):]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[req.username] = {"id": user_id, "password": hashlib.sha256(req.password.encode()).hexdigest()}
    return {"user_id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    stored = users[req.username]
    if hashlib.sha256(req.password.encode()).hexdigest() != stored["password"]:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = stored["id"]
    return {"token": token}

@app.post("/playlist")
def create_playlist(req: CreatePlaylistRequest, authorization: str = Header(...)):
    global playlist_id_counter
    user_id = get_current_user(authorization)
    playlist_id = playlist_id_counter
    playlist_id_counter += 1
    playlists[playlist_id] = {
        "id": playlist_id,
        "user_id": user_id,
        "title": req.title,
        "artist": req.artist,
        "songs": [],
        "play_count": 0
    }
    return playlists[playlist_id]

@app.get("/playlist/{playlist_id}")
def get_playlist(playlist_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    if playlist_id not in playlists:
        raise HTTPException(status_code=404, detail="Playlist not found")
    playlist = playlists[playlist_id]
    playlist["play_count"] += 1
    return playlist

