from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
properties = {}
inquiries = {}
next_user_id = 1
next_property_id = 1
next_inquiry_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PropertyCreate(BaseModel):
    price: float
    bedrooms: int
    location: str

class InquiryCreate(BaseModel):
    message: str
    property_id: int

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[req.username] = {"id": user_id, "password": req.password, "username": req.username}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.get("/properties")
def get_properties():
    result = []
    for pid, prop in properties.items():
        result.append({
            "id": pid,
            "price": prop["price"],
            "bedrooms": prop["bedrooms"],
            "location": prop["location"]
        })
    return result

@app.post("/properties")
def create_property(prop: PropertyCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_property_id
    pid = next_property_id
    next_property_id += 1
    properties[pid] = {
        "price": prop.price,
        "bedrooms": prop.bedrooms,
        "location": prop.location
    }
    return {"id": pid}

@app.get("/properties/{property_id}")
def get_property(property_id: int):
    if property_id not in properties:
        raise HTTPException(status_code=404, detail="Property not found")
    prop = properties[property_id]
    return {
        "id": property_id,
        "price": prop["price"],
        "bedrooms": prop["bedrooms"],
        "location": prop["location"]
    }

@app.post("/inquiry")
def create_inquiry(inq: InquiryCreate):
    if inq.property_id not in properties:
        raise HTTPException(status_code=404, detail="Property not found")
    global next_inquiry_id
    iid = next_inquiry_id
    next_inquiry_id += 1
    inquiries[iid] = {
        "message": inq.message,
        "property_id": inq.property_id
    }
    return {"id": iid}

@app.get("/inquiry/{inquiry_id}")
def get_inquiry(inquiry_id: int):
    if inquiry_id not in inquiries:
        raise HTTPException(status_code=404, detail="Inquiry not found")
    inq = inquiries[inquiry_id]
    return {
        "id": inquiry_id,
        "message": inq["message"],
        "property_id": inq["property_id"]
    }

