    get_user_from_token(authorization)
    global donation_id_counter
    donation_id_counter += 1
    donations[donation_id_counter] = {
        "id": donation_id_counter,
        "donor_name": donor_name,
        "amount": amount,
        "message": message,
        "timestamp": datetime.now().isoformat()
    }
    return donations[donation_id_counter]

@app.get("/donations")
def get_donations(authorization: str = Header(None)):
    get_user_from_token(authorization)
    total = sum(d["amount"] for d in donations.values())
    recent = sorted(donations.values(), key=lambda x: x["id"], reverse=True)[:10]
    return {"total": total, "recent": recent}

