    r = session.post(f"{BASE_URL}/alerts", params={"location": "CityA", "condition": "Rain"}, headers=headers)
    if r.status_code != 200:
        return False
    alert_data = r.json()
    alert_id = alert_data.get("id")
    if not alert_id:
        return False

    # Fetch own alert by ID
