import requests
import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    try:
        # Sign up a new user
        signup_resp = requests.post(f"{BASE_URL}/signup", json={"email": "test@example.com", "password": "password123"})
        if signup_resp.status_code not in (200, 201):
            return False
        signup_data = signup_resp.json()
        token = signup_data.get("token")
        if not token:
            return False
        user_id = signup_data.get("user_id")
        if not user_id:
            return False

        # Log in with the same credentials
        login_resp = requests.post(f"{BASE_URL}/login", json={"email": "test@example.com", "password": "password123"})
        if login_resp.status_code not in (200, 201):
            return False
        login_data = login_resp.json()
        token2 = login_data.get("token")
        if not token2:
            return False

        # Create a campaign
        headers = {"Authorization": f"Bearer {token}"}
        campaign_resp = requests.post(f"{BASE_URL}/campaigns", json={"name": "Test Campaign", "goal_amount": 1000.0}, headers=headers)
        if campaign_resp.status_code not in (200, 201):
            return False
        campaign_data = campaign_resp.json()
        campaign_id = campaign_data.get("id")
        if not campaign_id:
            return False

        # Fetch the created campaign
        get_campaign_resp = requests.get(f"{BASE_URL}/campaigns/{campaign_id}", headers=headers)
        if get_campaign_resp.status_code != 200:
            return False
        fetched_campaign = get_campaign_resp.json()
        if fetched_campaign.get("id") != campaign_id:
            return False

        # Create a donation for that campaign
        donation_resp = requests.post(f"{BASE_URL}/donations", json={"amount": 50.0, "campaign_id": campaign_id}, headers=headers)
        if donation_resp.status_code not in (200, 201):
            return False
        donation_data = donation_resp.json()
        donation_id = donation_data.get("id")
        if not donation_id:
            return False

        # Fetch the created donation
        get_donation_resp = requests.get(f"{BASE_URL}/donations/{donation_id}", headers=headers)
        if get_donation_resp.status_code != 200:
            return False
        fetched_donation = get_donation_resp.json()
        if fetched_donation.get("id") != donation_id:
            return False

        return True
    except Exception:
        return False

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

