# In-memory stores
users: Dict[int, dict] = {}
subscribers: Dict[int, dict] = {}
tokens: Dict[str, int] = {}  # token -> user_id
next_user_id = 1
next_subscriber_id = 1

# Auth helper
def get_user_id(authorization: str = Header(...)) -> int:
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

# User models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

# Endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

