from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
from datetime import datetime, timedelta
import secrets
import hashlib

app = FastAPI()

users = {}
tokens = {}
appointments = {}
appointment_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class AppointmentCreate(BaseModel):
    patient_name: str
    date: str
    reason: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/appointments")
def create_appointment(req: AppointmentCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global appointment_id_counter
    appointment_id = appointment_id_counter
    appointment_id_counter += 1
    appointments[appointment_id] = {
        "id": appointment_id,
        "patient_name": req.patient_name,
        "date": req.date,
        "reason": req.reason
    }
    return appointments[appointment_id]

@app.get("/appointments")
def list_appointments(authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    now = datetime.now()
    upcoming = []
    for appt in appointments.values():
        try:
            appt_date = datetime.strptime(appt["date"], "%Y-%m-%d")
            if appt_date >= now:
                upcoming.append(appt)
        except:
            pass
    upcoming.sort(key=lambda x: x["date"])
    return upcoming

@app.get("/appointments/{appointment_id}")
def get_appointment(appointment_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404, detail="Appointment not found")
    return appointments[appointment_id]

