from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import hashlib
import secrets

app = FastAPI()

menu = {
    1: {"name": "Burger", "price": 9.99, "description": "Juicy beef burger", "category": "Main"},
    2: {"name": "Fries", "price": 3.99, "description": "Crispy golden fries", "category": "Sides"},
    3: {"name": "Cola", "price": 1.99, "description": "Refreshing cola", "category": "Drinks"},
    4: {"name": "Salad", "price": 7.99, "description": "Fresh garden salad", "category": "Main"},
    5: {"name": "Ice Cream", "price": 4.99, "description": "Vanilla ice cream", "category": "Desserts"},
}

orders = {}
order_id_counter = 1

users = {}
user_id_counter = 1
tokens = {}  # token -> user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class OrderCreate(BaseModel):
    table_number: int
    item_ids: List[int]

@app.get("/menu")
def get_menu():
    categories = {}
    for item_id, item in menu.items():
        cat = item["category"]
        if cat not in categories:
            categories[cat] = []
        categories[cat].append({
            "id": item_id,
            "name": item["name"],
            "price": item["price"],
            "description": item["description"]
        })
    return categories

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="User exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": hashlib.sha256(req.password.encode()).hexdigest()
    }
    token = secrets.token_hex(16)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == hashlib.sha256(req.password.encode()).hexdigest():
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.get("/menu/{item_id}")
def get_menu_item(item_id: int):
    if item_id not in menu:
        raise HTTPException(status_code=404, detail="Not found")
    return menu[item_id]

@app.post("/orders")
def create_order(order: OrderCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global order_id_counter
    order_id = order_id_counter
    order_id_counter += 1
    items = []
    for item_id in order.item_ids:
        if item_id not in menu:
            raise HTTPException(status_code=400, detail=f"Item {item_id} not found")
        items.append(menu[item_id])
    total = sum(item["price"] for item in items)
    orders[order_id] = {
        "id": order_id,
        "table_number": order.table_number,
        "items": items,
        "total": total
    }
    return orders[order_id]

