tokens = {}
plans = {}
next_user_id = 1
next_plan_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PlanCreate(BaseModel):
    name: str
    difficulty: str
    duration: int

class PlanUpdate(BaseModel):
    name: Optional[str] = None
    difficulty: Optional[str] = None
    duration: Optional[int] = None
    user_access: Optional[list[str]] = None

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if req.username in [u["username"] for u in users.values()]:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password_hash": hash_password(req.password)
    }
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for user_id, user in users.items():
        if user["username"] == req.username and user["password_hash"] == hash_password(req.password):
            token = generate_token()
            tokens[token] = user_id
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/plans/{plan_id}")
