    next_plan_id += 1
    plans[plan_id] = {
        "id": plan_id,
        "name": plan.name,
        "difficulty": plan.difficulty,
        "duration": plan.duration,
        "user_access": [user_id],
        "created_by": user_id
    }
    return plans[plan_id]

@app.put("/plans/{plan_id}")
def update_plan(plan_id: int, plan: PlanUpdate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if plan_id not in plans:
        raise HTTPException(status_code=404, detail="Plan not found")
    if user_id not in plans[plan_id]["user_access"]:
        raise HTTPException(status_code=403, detail="Access denied")
    if plan.name is not None:
        plans[plan_id]["name"] = plan.name
    if plan.difficulty is not None:
        plans[plan_id]["difficulty"] = plan.difficulty
    if plan.duration is not None:
        plans[plan_id]["duration"] = plan.duration
    if plan.user_access is not None:
        plans[plan_id]["user_access"] = plan.user_access
    return plans[plan_id]

