    try:
        # Sign up
        signup_resp = requests.post(f"{BASE_URL}/signup", json={
            "username": "testuser",
            "password": "testpass"
        })
        if signup_resp.status_code not in (200, 201):
            print("SPEC_FAIL")
            return False

        # Login
        login_resp = requests.post(f"{BASE_URL}/login", json={
            "username": "testuser",
            "password": "testpass"
        })
        if login_resp.status_code not in (200, 201):
            print("SPEC_FAIL")
            return False
        token = login_resp.json().get("token")
        if not token:
            print("SPEC_FAIL")
            return False

        headers = {"Authorization": f"Bearer {token}"}

        # Create campaign
        campaign_data = {
            "headline": "Test Campaign",
            "target_audience": "Everyone",
            "budget": 1000.0,
            "publisher_tier": "gold"
        }
        create_resp = requests.post(f"{BASE_URL}/campaigns", json=campaign_data, headers=headers)
        if create_resp.status_code not in (200, 201):
            print("SPEC_FAIL")
            return False
        campaign = create_resp.json()
        campaign_id = campaign.get("id")
        if not campaign_id:
            print("SPEC_FAIL")
            return False

        # Fetch own campaign
        get_resp = requests.get(f"{BASE_URL}/campaigns/{campaign_id}", headers=headers)
        if get_resp.status_code != 200:
            print("SPEC_FAIL")
            return False
        fetched = get_resp.json()
        if fetched.get("id") != campaign_id or fetched.get("headline") != "Test Campaign":
            print("SPEC_FAIL")
            return False

        print("SPEC_PASS")
        return True
    except Exception:
        print("SPEC_FAIL")
        return False

if __name__ == "__main__":
