import random
import time
import threading
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel

app = FastAPI()

users = {}
tokens = {}
next_user_id = 1

portfolios = {}
next_portfolio_id = 1

holdings = {}
next_holding_id = 1

alerts = []
next_alert_id = 1

base_prices = {
    "AAPL": 150.0,
    "GOOGL": 2800.0,
    "MSFT": 300.0,
    "AMZN": 3400.0,
    "TSLA": 700.0
}

current_prices = {k: v for k, v in base_prices.items()}
price_history = {k: [] for k in base_prices}

def price_simulator():
    while True:
        for sym in current_prices:
            change = random.uniform(-0.05, 0.05)
            current_prices[sym] = round(current_prices[sym] * (1 + change), 2)
            price_history[sym].append(current_prices[sym])
            if len(price_history[sym]) > 20:
                price_history[sym].pop(0)
            if abs(change) > 0.03:
                alert_id = next_alert_id
                next_alert_id += 1
                alerts.append({
                    "id": alert_id,
                    "symbol": sym,
                    "price": current_prices[sym],
                    "change_pct": round(change * 100, 2),
                    "timestamp": time.time()
                })
        time.sleep(2)

threading.Thread(target=price_simulator, daemon=True).start()

def require_auth(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PortfolioCreate(BaseModel):
    name: str

class HoldingCreate(BaseModel):
    symbol: str
    quantity: int
    portfolio_id: int

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "username": req.username, "password": req.password}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = f"tok_{uid}_{random.randint(10000,99999)}"
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/portfolio/{portfolio_id}")
def get_portfolio(portfolio_id: int, authorization: str = Header(None)):
    uid = require_auth(authorization)
    if portfolio_id not in portfolios:
        raise HTTPException(status_code=404, detail="Portfolio not found")
    portfolio = portfolios[portfolio_id]
    portfolio_holdings = [h for h in holdings.values() if h["portfolio_id"] == portfolio_id]
    total_pnl = 0
    total_risk = 0
    enriched = []
    for h in portfolio_holdings:
        sym = h["symbol"]
        current_price = current_prices.get(sym, 0)
        cost_basis = h["avg_cost"]
        pnl = round((current_price - cost_basis) * h["quantity"], 2)
        total_pnl += pnl
        hist = price_history.get(sym, [])
        if len(hist) > 1:
            returns = [(hist[i] - hist[i-1]) / hist[i-1] for i in range(1, len(hist))]
            vol = round((sum(r**2 for r in returns) / len(returns))**0.5 * 100, 2) if returns else 0
        else:
            vol = 0
        total_risk += vol * h["quantity"]
        enriched.append({
            "id": h["id"],
            "symbol": sym,
            "quantity": h["quantity"],
            "avg_cost": cost_basis,
            "current_price": current_price,
            "pnl": pnl,
            "risk_score": vol
        })
    avg_risk = round(total_risk / len(enriched), 2) if enriched else 0
    return {
        "portfolio": portfolio,
        "holdings": enriched,
        "total_pnl": total_pnl,
        "risk_score": avg_risk
    }

@app.get("/alerts")
def get_alerts(authorization: str = Header(None)):
    uid = require_auth(authorization)
    return {"alerts": alerts[-20:]}

@app.post("/portfolio")
def create_portfolio(req: PortfolioCreate, authorization: str = Header(None)):
    uid = require_auth(authorization)
    global next_portfolio_id
    pid = next_portfolio_id
    next_portfolio_id += 1
    portfolios[pid] = {"id": pid, "name": req.name, "user_id": uid}
    return portfolios[pid]

@app.post("/holding")
def create_holding(req: HoldingCreate, authorization: str = Header(None)):
    uid = require_auth(authorization)
    if req.portfolio_id not in portfolios:
        raise HTTPException(status_code=404, detail="Portfolio not found")
    if portfolios[req.portfolio_id]["user_id"] != uid:
        raise HTTPException(status_code=403, detail="Not your portfolio")
    global next_holding_id
    hid = next_holding_id
    next_holding_id += 1
    holdings[hid] = {
        "id": hid,
        "symbol": req.symbol,
        "quantity": req.quantity,
        "avg_cost": current_prices.get(req.symbol, 100.0),
        "portfolio_id": req.portfolio_id
    }
    return holdings[hid]

@app.get("/portfolio")
def list_portfolios(authorization: str = Header(None)):
    uid = require_auth(authorization)
    user_portfolios = [p for p in portfolios.values() if p["user_id"] == uid]
    return {"portfolios": user_portfolios}

