from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import random
import math
from datetime import datetime

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
matches = {}
feedbacks = []
next_user_id = 1
next_match_id = 1

# Simple token generation
def generate_token():
    return ''.join(random.choices('abcdefghijklmnopqrstuvwxyz0123456789', k=32))

# Auth helper
def get_user_id(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    name: str
    email: str
    password: str
    latitude: float = 0.0
    longitude: float = 0.0
    interests: list[str] = []

class LoginRequest(BaseModel):
    email: str
    password: str

class Match(BaseModel):
    user_id: int
    status: str = "pending"  # pending/accepted/rejected

class FeedbackRequest(BaseModel):
    match_id: int
    thumbs: str  # up or down

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["email"] == req.email:
            raise HTTPException(status_code=400, detail="Email already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "name": req.name,
        "email": req.email,
        "password": req.password,
        "latitude": req.latitude,
        "longitude": req.longitude,
        "interests": req.interests,
        "created_at": datetime.now().isoformat()
    }
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["email"] == req.email and u["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    get_user_id(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/users")
def create_user(req: SignupRequest):
    return signup(req)

@app.get("/matches")
def get_matches(authorization: str = Header(None)):
    current_user_id = get_user_id(authorization)
    current_user = users[current_user_id]

    potential_matches = []
    for uid, u in users.items():
        if uid == current_user_id:
            continue

        # Compatibility score based on shared interests
        shared = set(current_user["interests"]) & set(u["interests"])
        compatibility = len(shared) / max(len(current_user["interests"]), 1) * 100

        # Distance calculation (simplified)
        lat1, lon1 = current_user["latitude"], current_user["longitude"]
        lat2, lon2 = u["latitude"], u["longitude"]
        distance = math.sqrt((lat1 - lat2)**2 + (lon1 - lon2)**2) * 111  # rough km

        potential_matches.append({
            "user_id": uid,
            "name": u["name"],
            "compatibility_score": round(compatibility, 1),
            "distance_km": round(distance, 1),
            "shared_interests": list(shared)
        })

    # Sort by compatibility descending
    potential_matches.sort(key=lambda x: x["compatibility_score"], reverse=True)
    return {"matches": potential_matches[:20]}  # top 20

@app.post("/matches")
def create_match(match: Match, authorization: str = Header(None)):
    global next_match_id
    current_user_id = get_user_id(authorization)

    if match.user_id not in users:
        raise HTTPException(status_code=404, detail="Target user not found")

    match_id = next_match_id
    next_match_id += 1
    matches[match_id] = {
        "id": match_id,
        "user_id": current_user_id,
        "target_user_id": match.user_id,
        "status": match.status,
        "created_at": datetime.now().isoformat()
    }
    return {"match_id": match_id}

@app.get("/matches/{match_id}")
def get_match(match_id: int, authorization: str = Header(None)):
    get_user_id(authorization)
    if match_id not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    return matches[match_id]

@app.post("/feedback")
def feedback(req: FeedbackRequest):
    if req.match_id not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    if req.thumbs not in ["up", "down"]:
        raise HTTPException(status_code=400, detail="Thumbs must be 'up' or 'down'")

    feedbacks.append({
        "match_id": req.match_id,
        "thumbs": req.thumbs,
        "timestamp": datetime.now().isoformat()
    })
    return {"status": "logged"}

