from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import random
import time
from datetime import datetime, timedelta

app = FastAPI()

users = {}
tokens = {}
next_user_id = 1
next_token_id = 1

estimates = {}
history_data = {}
next_estimate_id = 1

API_TOKEN = "supersecret123"

def verify_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token != API_TOKEN and token not in tokens.values():
        raise HTTPException(status_code=401, detail="Invalid token")
    return token

class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class EstimateRequest(BaseModel):
    zip_code: str

class EstimateResponse(BaseModel):
    id: int
    zip_code: str
    median_rent: float
    price_per_sqft: float
    vacancy_rate: float

@app.post("/signup")
def signup(user: UserSignup):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": user.username, "password": user.password}
    return {"id": user_id, "username": user.username}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            global next_token_id
            token = f"token_{next_token_id}"
            next_token_id += 1
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/estimate", response_model=EstimateResponse)
def create_estimate(req: EstimateRequest, authorization: str = Header(None)):
    verify_token(authorization)
    global next_estimate_id
    # Simulate real estate data
    random.seed(hash(req.zip_code) % (2**31))
    median_rent = round(random.uniform(800, 4000), 2)
    price_per_sqft = round(random.uniform(1.5, 5.0), 2)
    vacancy_rate = round(random.uniform(0.01, 0.15), 4)
    est_id = next_estimate_id
    next_estimate_id += 1
    estimates[est_id] = {
        "id": est_id,
        "zip_code": req.zip_code,
        "median_rent": median_rent,
        "price_per_sqft": price_per_sqft,
        "vacancy_rate": vacancy_rate
    }
    # Generate history data (6 months of simulated trends)
    hist = []
    base_rent = median_rent - random.uniform(100, 300)
    base_pps = price_per_sqft - random.uniform(0.3, 0.8)
    base_vac = vacancy_rate - random.uniform(0.01, 0.03)
    for i in range(6):
        month_date = (datetime.now() - timedelta(days=30*(5-i))).strftime("%Y-%m")
        hist.append({
            "month": month_date,
            "median_rent": round(base_rent + random.uniform(-50, 50) + i*20, 2),
            "price_per_sqft": round(base_pps + random.uniform(-0.2, 0.2) + i*0.1, 2),
            "vacancy_rate": round(max(0, base_vac + random.uniform(-0.01, 0.01) - i*0.005), 4)
        })
    history_data[est_id] = hist
    return estimates[est_id]

@app.get("/estimate/{estimate_id}", response_model=EstimateResponse)
def get_estimate(estimate_id: int, authorization: str = Header(None)):
    verify_token(authorization)
    if estimate_id not in estimates:
        raise HTTPException(status_code=404, detail="Estimate not found")
    return estimates[estimate_id]

@app.get("/history/{estimate_id}")
def get_history(estimate_id: int, authorization: str = Header(None)):
    verify_token(authorization)
    if estimate_id not in history_data:
        raise HTTPException(status_code=404, detail="History not found")
