    user_id = get_current_user(authorization)
    usage_id = next_usage_id
    next_usage_id += 1
    usage_records[usage_id] = {
        "id": usage_id,
        "user_id": user_id,
        "gallons": gallons,
        "timestamp": datetime.now().isoformat()
    }
    return usage_records[usage_id]

