    total_daily = sum(r["gallons"] for r in today_records)

    # weekly average
    week_ago = datetime.now() - timedelta(days=7)
    week_records = [r for r in usage_records.values() if r["user_id"] == user_id and datetime.fromisoformat(r["timestamp"]) >= week_ago]
    weekly_avg = sum(r["gallons"] for r in week_records) / 7 if week_records else 0

    # leak detection: check if any flow > 3 hours straight
    leak_detected = False
    user_records_sorted = sorted([r for r in usage_records.values() if r["user_id"] == user_id], key=lambda x: x["timestamp"])
    if len(user_records_sorted) >= 2:
        for i in range(len(user_records_sorted) - 1):
            t1 = datetime.fromisoformat(user_records_sorted[i]["timestamp"])
