    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    user = users[user_id]
    stats = leaderboard[user_id]
    win_rate = (stats["wins"] / stats["games_played"] * 100) if stats["games_played"] > 0 else 0
    return {
