from pydantic import BaseModel
from typing import Optional
import random
import string
from datetime import datetime

app = FastAPI()

users = {}
tokens = {}
leaderboard = {}
player_stats = {}
player_history = {}
next_user_id = 1
next_game_id = 1
games = {}

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class GameResult(BaseModel):
    score: int
    total_questions: int

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    leaderboard[user_id] = {"score": 0, "games_played": 0, "wins": 0}
    player_stats[user_id] = {"rank_history": []}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/leaderboard")
def get_leaderboard():
    sorted_users = sorted(leaderboard.items(), key=lambda x: (-x[1]["score"], x[1]["games_played"]))
    top10 = []
    for i, (uid, stats) in enumerate(sorted_users[:10]):
        user = users[uid]
        win_rate = (stats["wins"] / stats["games_played"] * 100) if stats["games_played"] > 0 else 0
        top10.append({
            "rank": i + 1,
            "username": user["username"],
            "score": stats["score"],
            "games_played": stats["games_played"],
            "win_rate": round(win_rate, 2)
        })
    return {"leaderboard": top10}

