    now = time.time()
    open_tickets = []
    for tid, t in tickets.items():
        if t["status"] == "open":
            last_update_delta = now - t["last_updated"]
            hours = int(last_update_delta // 3600)
            minutes = int((last_update_delta % 3600) // 60)
            if hours > 0:
                time_since = f"{hours}h {minutes}m ago"
            else:
                time_since = f"{minutes}m ago"
            open_tickets.append({
                "id": tid,
                "subject": t["subject"],
