from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
import random
import string
import json
from typing import Optional

app = FastAPI()

users = {}
profiles = {}
tokens = {}
next_user_id = 1
next_profile_id = 1
next_token_id = 1

def generate_token():
    global next_token_id
    token = f"tok_{next_token_id}_{''.join(random.choices(string.ascii_letters + string.digits, k=16))}"
    next_token_id += 1
    return token

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/profiles/{profile_id}")
def get_profile(profile_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if profile_id not in profiles:
        raise HTTPException(status_code=404, detail="Profile not found")
    return profiles[profile_id]

@app.post("/profiles")
def create_profile(
    name: str,
    age: int,
    interests: str,
    authorization: str = Header(...)
):
    global next_profile_id
    user_id = get_current_user(authorization)
    profile_id = next_profile_id
    next_profile_id += 1
    profiles[profile_id] = {
        "id": profile_id,
        "user_id": user_id,
        "name": name,
        "age": age,
        "interests": interests,
        "last_active": datetime.utcnow().isoformat()
    }
    return profiles[profile_id]

@app.get("/profiles")
def search_profiles(
    age_min: Optional[int] = None,
    interests: Optional[str] = None,
    authorization: str = Header(...)
):
    get_current_user(authorization)
    results = []
    for pid, p in profiles.items():
        if age_min is not None and p["age"] < age_min:
            continue
        if interests is not None:
            profile_interests = json.loads(p["interests"]) if isinstance(p["interests"], str) else p.get("interests", [])
            if isinstance(profile_interests, str):
                profile_interests = [profile_interests]
            query_interests = json.loads(interests) if isinstance(interests, str) else [interests]
            if not any(i in profile_interests for i in query_interests):
                continue
        compatibility = random.randint(50, 100)
        results.append({
            "profile": p,
            "compatibility_score": compatibility,
            "last_active": p["last_active"]
        })
    results.sort(key=lambda x: x["compatibility_score"], reverse=True)
    return results

