import secrets
from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import FileResponse
from pydantic import BaseModel

app = FastAPI()

users = {}
tokens = {}
invoices = {}
invoice_downloads = {}
invoice_id_counter = 1

INVOICES_DIR = "/invoices_dir"
os.makedirs(INVOICES_DIR, exist_ok=True)

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class InvoiceCreate(BaseModel):
    filename: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    user = tokens.get(token)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/invoices")
def create_invoice(req: InvoiceCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global invoice_id_counter
    invoice_id = invoice_id_counter
    invoice_id_counter += 1
    file_path = os.path.join(INVOICES_DIR, req.filename)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=400, detail="File does not exist on server")
    invoices[invoice_id] = {"id": invoice_id, "filename": req.filename, "path": file_path}
    invoice_downloads[invoice_id] = 0
    return invoices[invoice_id]

@app.get("/invoices/{invoice_id}")
def download_invoice(invoice_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    invoice = invoices.get(invoice_id)
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    invoice_downloads[invoice_id] = invoice_downloads.get(invoice_id, 0) + 1
    return FileResponse(invoice["path"], media_type="application/pdf", filename=invoice["filename"])

