import datetime
from reportlab.pdfgen import canvas
from io import BytesIO

app = FastAPI()

users = {}
user_tokens = {}
next_user_id = 1
trips = {}
next_trip_id = 1
itineraries = {}
next_itinerary_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TripCreate(BaseModel):
    name: str
    destination: str
    start_date: str
    end_date: str

class ItineraryCreate(BaseModel):
    trip_id: int
    day: int
    activity: str
    location: str
    notes: str = ""

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    for uid, t in user_tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "username": req.username, "password": req.password}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = f"tok_{uid}_{datetime.datetime.now().timestamp()}"
            user_tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/trips")
def create_trip(trip: TripCreate, authorization: str = Header(None)):
    uid = get_user_from_token(authorization)
    global next_trip_id
    tid = next_trip_id
    next_trip_id += 1
    trips[tid] = {
        "id": tid,
        "user_id": uid,
        "name": trip.name,
        "destination": trip.destination,
        "start_date": trip.start_date,
        "end_date": trip.end_date
    }
    return trips[tid]

@app.get("/trips/{trip_id}")
def get_trip(trip_id: int, authorization: str = Header(None)):
    uid = get_user_from_token(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    return trips[trip_id]

@app.post("/itineraries")
def create_itinerary(it: ItineraryCreate, authorization: str = Header(None)):
    uid = get_user_from_token(authorization)
    if it.trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    global next_itinerary_id
    iid = next_itinerary_id
    next_itinerary_id += 1
    itineraries[iid] = {
        "id": iid,
        "trip_id": it.trip_id,
        "day": it.day,
        "activity": it.activity,
        "location": it.location,
        "notes": it.notes
    }
    return itineraries[iid]

@app.get("/itineraries/{trip_id}")
def get_itineraries(trip_id: int, authorization: str = Header(None)):
    uid = get_user_from_token(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    trip_itineraries = [v for v in itineraries.values() if v["trip_id"] == trip_id]
    return trip_itineraries

@app.get("/itineraries/{trip_id}/export")
def export_itinerary(trip_id: int, format: str = "json", authorization: str = Header(None)):
    uid = get_user_from_token(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    trip = trips[trip_id]
    trip_itineraries = [v for v in itineraries.values() if v["trip_id"] == trip_id]

    if format == "json":
        data = {"trip": trip, "itineraries": trip_itineraries}
        return Response(content=json.dumps(data, indent=2), media_type="application/json")

    elif format == "pdf":
        buffer = BytesIO()
        p = canvas.Canvas(buffer)
        p.drawString(100, 800, f"Trip: {trip['name']}")
        p.drawString(100, 780, f"Destination: {trip['destination']}")
        p.drawString(100, 760, f"Dates: {trip['start_date']} - {trip['end_date']}")
        y = 730
        for it in trip_itineraries:
            p.drawString(100, y, f"Day {it['day']}: {it['activity']} @ {it['location']}")
            if it["notes"]:
                p.drawString(120, y - 15, f"Notes: {it['notes']}")
                y -= 30
            else:
                y -= 20
        p.save()
        buffer.seek(0)
        return Response(content=buffer.read(), media_type="application/pdf", headers={"Content-Disposition": f"attachment; filename=itinerary_{trip_id}.pdf"})

    raise HTTPException(status_code=400, detail="Invalid format")

