import os
import shutil
from fastapi import FastAPI, HTTPException, Header, Body
from fastapi.responses import FileResponse
from typing import Optional
import uuid
import hashlib
import time

app = FastAPI()

users = {}
tokens = {}
blueprints = {}
blueprint_versions = {}
next_user_id = 1
next_blueprint_id = 1

BLUEPRINT_STORAGE = "/blueprint_storage"

def verify_token(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "") if authorization.startswith("Bearer ") else authorization
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str = Body(...), password: str = Body(...)):
    global next_user_id
    for user in users.values():
        if user["username"] == username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str = Body(...), password: str = Body(...)):
    for user in users.values():
        if user["username"] == username and user["password"] == password:
            token = str(uuid.uuid4())
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/blueprints/{blueprint_id}")
def get_blueprint(blueprint_id: int, authorization: Optional[str] = Header(None)):
    verify_token(authorization)
    if blueprint_id not in blueprints:
        raise HTTPException(status_code=404, detail="Blueprint not found")
    return blueprints[blueprint_id]

@app.post("/blueprints")
def create_blueprint(name: str = Body(...), project_id: int = Body(...), authorization: Optional[str] = Header(None)):
    user_id = verify_token(authorization)
    global next_blueprint_id
    blueprint_id = next_blueprint_id
    next_blueprint_id += 1
    blueprints[blueprint_id] = {
        "id": blueprint_id,
        "name": name,
        "project_id": project_id,
        "created_by": user_id,
        "current_version": 1
    }
    blueprint_versions[blueprint_id] = {1: {"version": 1, "created_at": time.time()}}
    return blueprints[blueprint_id]

@app.get("/blueprints/{project_id}/{filename}")
def download_blueprint(project_id: int, filename: str, authorization: Optional[str] = Header(None)):
    verify_token(authorization)
    file_path = os.path.join(BLUEPRINT_STORAGE, str(project_id), filename)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="File not found")
    return FileResponse(file_path, media_type="application/octet-stream", filename=filename)

@app.get("/blueprints/{project_id}/{filename}/versions")
def get_blueprint_versions(project_id: int, filename: str, authorization: Optional[str] = Header(None)):
    verify_token(authorization)
    for bp_id, bp in blueprints.items():
        if bp["project_id"] == project_id and bp["name"] == filename:
            return blueprint_versions.get(bp_id, {})
    raise HTTPException(status_code=404, detail="Blueprint not found")

@app.get("/blueprints/{project_id}/{filename}/version/{version}")
def download_blueprint_version(project_id: int, filename: str, version: int, authorization: Optional[str] = Header(None)):
    verify_token(authorization)
    for bp_id, bp in blueprints.items():
        if bp["project_id"] == project_id and bp["name"] == filename:
            version_path = os.path.join(BLUEPRINT_STORAGE, str(project_id), f"v{version}", filename)
            if os.path.exists(version_path):
                return FileResponse(version_path, media_type="application/octet-stream", filename=filename)
            raise HTTPException(status_code=404, detail="Version not found")
    raise HTTPException(status_code=404, detail="Blueprint not found")

