import hashlib
import secrets
import os
from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import FileResponse
from pydantic import BaseModel

app = FastAPI()

users = {}
tokens = {}
tracks = {}
next_user_id = 1
next_track_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TrackCreate(BaseModel):
    title: str
    artist: str

def authenticate(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    password_hash = hashlib.sha256(req.password.encode()).hexdigest()
    users[user_id] = {"id": user_id, "username": req.username, "password_hash": password_hash}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username:
            if u["password_hash"] == hashlib.sha256(req.password.encode()).hexdigest():
                token = secrets.token_hex(32)
                tokens[token] = u["id"]
                return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/tracks/{track_id}")
def get_track(track_id: int, authorization: str = Header(None)):
    authenticate(authorization)
    if track_id not in tracks:
        raise HTTPException(status_code=404, detail="Track not found")
    return tracks[track_id]

@app.post("/tracks")
def create_track(track: TrackCreate, authorization: str = Header(None)):
    authenticate(authorization)
    global next_track_id
    track_id = next_track_id
    next_track_id += 1
    tracks[track_id] = {"id": track_id, "title": track.title, "artist": track.artist}
    return tracks[track_id]

@app.get("/tracks/{track_id}/preview")
def preview_track(track_id: int, authorization: str = Header(None)):
    authenticate(authorization)
    if track_id not in tracks:
        raise HTTPException(status_code=404, detail="Track not found")
    file_path = f"/audio/previews/{track_id}.mp3"
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="Preview file not found")
