import csv
import io
import zipfile
from pathlib import Path
from typing import Optional

from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import StreamingResponse
from pydantic import BaseModel
import uvicorn

app = FastAPI()

# In-memory stores
users = {}
next_user_id = 1
tokens = {}  # token -> user_id

# Resource stores (users can create arbitrary resources)
resources = {}
next_resource_id = 1

BASE_DIR = Path("/var/finance")

# ---------- Auth helpers ----------
def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

# ---------- Auth endpoints ----------
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    token = f"tok_{user_id}_{req.username}"
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = f"tok_{uid}_{req.username}"
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# ---------- Generic resource endpoints ----------
class CreateResourceRequest(BaseModel):
    name: str
    data: dict = {}

@app.get("/{resource}/{resource_id}")
def get_resource(resource: str, resource_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    key = (resource, resource_id)
    if key not in resources:
        raise HTTPException(status_code=404, detail="Resource not found")
    return resources[key]

@app.post("/{resource}")
def create_resource(resource: str, req: CreateResourceRequest, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_resource_id
    resource_id = next_resource_id
    next_resource_id += 1
    key = (resource, resource_id)
    resources[key] = {"id": resource_id, "name": req.name, "data": req.data}
    return {"id": resource_id, "name": req.name, "data": req.data}

# ---------- Finance-specific endpoints ----------
@app.get("/statement")
def get_statement(account: str, file: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    file_path = BASE_DIR / account / file
    if not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail="File not found")
    if file_path.suffix.lower() != ".csv":
        raise HTTPException(status_code=400, detail="Only CSV files are supported")
    with open(file_path, "r") as f:
        content = f.read()
    return StreamingResponse(iter([content]), media_type="text/csv", headers={"Content-Disposition": f"attachment; filename={file}"})

@app.get("/bulk")
def bulk_download(account: str, files: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    file_names = [f.strip() for f in files.split(",") if f.strip()]
    if not file_names:
        raise HTTPException(status_code=400, detail="No files specified")

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED) as zf:
        for fname in file_names:
            file_path = BASE_DIR / account / fname
            if not file_path.exists() or not file_path.is_file():
                continue  # skip missing files
            if file_path.suffix.lower() != ".csv":
                continue
            with open(file_path, "r") as f:
                zf.writestr(fname, f.read())
    zip_buffer.seek(0)
    return StreamingResponse(zip_buffer, media_type="application/zip", headers={"Content-Disposition": f"attachment; filename={account}_bulk.zip"})

if __name__ == "__main__":
    uvicorn.run(app, host="127.0.0.1", port=8000)

