import os
import secrets
import hashlib
from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import FileResponse
from pydantic import BaseModel
import uvicorn

app = FastAPI()

users = {}
tokens = {}
products_store = {}
next_user_id = 1
next_product_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ProductCreate(BaseModel):
    name: str
    price: float

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization.split(" ")[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = next_user_id
    next_user_id += 1
    users[req.username] = {"id": user_id, "username": req.username, "password": hash_password(req.password)}
    token = secrets.token_hex(32)
    tokens[token] = req.username
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if users[req.username]["password"] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = req.username
    return {"token": token}

@app.post("/product")
def create_product(req: ProductCreate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    global next_product_id
    product_id = next_product_id
    next_product_id += 1
    products_store[product_id] = {"id": product_id, "name": req.name, "price": req.price, "owner": current_user}
    return products_store[product_id]

@app.get("/product/{product_id}")
def get_product(product_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if product_id not in products_store:
        raise HTTPException(status_code=404, detail="Product not found")
    return products_store[product_id]

@app.get("/product/{sku}/images/{file}")
def get_product_image(sku: str, file: str, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    image_path = f"/var/products/{sku}/{file}"
    if not os.path.isfile(image_path):
        raise HTTPException(status_code=404, detail="Image not found")
    return FileResponse(image_path)

@app.get("/product/{sku}/images")
def list_product_images(sku: str, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    image_dir = f"/var/products/{sku}"
    if not os.path.isdir(image_dir):
        raise HTTPException(status_code=404, detail="Product directory not found")
    try:
        files = os.listdir(image_dir)
    except PermissionError:
        raise HTTPException(status_code=403, detail="Cannot access product directory")
    return {"sku": sku, "images": files}

if __name__ == "__main__":
    uvicorn.run(app, host="127.0.0.1", port=8000)

