import os
import shutil
import uuid
from pathlib import Path
from io import BytesIO

from fastapi import FastAPI, HTTPException, Header, UploadFile, File, Query
from fastapi.responses import Response
from PIL import Image
import uvicorn

app = FastAPI()

users = {}
tokens = {}
properties = {}
photos_path = Path("/var/properties")

PHOTOS_BASE = photos_path

def require_auth(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(401, "unauthorized")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(401, "unauthorized")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(400, "user exists")
    user_id = len(users) + 1
    users[username] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username]["password"] != password:
        raise HTTPException(401, "invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = users[username]["id"]
    return {"token": token}

@app.post("/property")
def create_property(authorization: str = Header(None)):
    user_id = require_auth(authorization)
    prop_id = len(properties) + 1
    properties[prop_id] = {"id": prop_id, "owner_id": user_id, "photos": []}
    os.makedirs(PHOTOS_BASE / str(prop_id), exist_ok=True)
    return properties[prop_id]

@app.get("/property/{prop_id}")
def get_property(prop_id: int, authorization: str = Header(None)):
    require_auth(authorization)
    if prop_id not in properties:
        raise HTTPException(404, "not found")
    return properties[prop_id]

@app.post("/property/{prop_id}/photos")
def upload_photo(prop_id: int, file: UploadFile = File(...), authorization: str = Header(None)):
    require_auth(authorization)
    if prop_id not in properties:
        raise HTTPException(404, "property not found")
    dir_path = PHOTOS_BASE / str(prop_id)
    dir_path.mkdir(parents=True, exist_ok=True)
    file_id = len(properties[prop_id]["photos"]) + 1
    ext = Path(file.filename).suffix if file.filename else ".jpg"
    filename = f"{file_id}{ext}"
    file_path = dir_path / filename
    with open(file_path, "wb") as f:
        shutil.copyfileobj(file.file, f)
    properties[prop_id]["photos"].append(filename)
    return {"file": filename, "id": file_id}

@app.get("/property/{prop_id}/photos/{file_name:path}")
def get_photo(prop_id: int, file_name: str, size: str = Query(None), authorization: str = Header(None)):
    require_auth(authorization)
    if prop_id not in properties:
        raise HTTPException(404, "property not found")
    file_path = PHOTOS_BASE / str(prop_id) / file_name
    if not file_path.exists():
        raise HTTPException(404, "file not found")
    if size == "small":
        img = Image.open(file_path)
        img.thumbnail((300, 300))
        buf = BytesIO()
        img.save(buf, format="JPEG")
        buf.seek(0)
        return Response(content=buf.read(), media_type="image/jpeg")
    return Response(content=open(file_path, "rb").read(), media_type="image/jpeg")

