import os
import zipfile
import io
from fastapi import FastAPI, HTTPException, Header, File, UploadFile
from fastapi.responses import FileResponse, StreamingResponse
from pydantic import BaseModel
from typing import Optional
import uuid
import shutil

app = FastAPI()

users = {}
tokens = {}
orders = {}
shipments = {}
next_user_id = 1
next_order_id = 1
next_shipment_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

class OrderCreate(BaseModel):
    description: str
    amount: float

@app.post("/orders")
def create_order(order: OrderCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_order_id
    oid = next_order_id
    next_order_id += 1
    orders[oid] = {"id": oid, "description": order.description, "amount": order.amount, "user_id": user_id}
    return orders[oid]

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")
    if orders[order_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return orders[order_id]

class ShipmentCreate(BaseModel):
    order_id: int
    address: str

@app.post("/shipments")
def create_shipment(shipment: ShipmentCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if shipment.order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")
    if orders[shipment.order_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    global next_shipment_id
    sid = next_shipment_id
    next_shipment_id += 1
    shipments[sid] = {"id": sid, "order_id": shipment.order_id, "address": shipment.address, "user_id": user_id}
    os.makedirs(f"/var/shipments/{sid}", exist_ok=True)
    return shipments[sid]

@app.get("/shipments/{shipment_id}")
def get_shipment(shipment_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    if shipments[shipment_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return shipments[shipment_id]

@app.post("/shipments/{shipment_id}/docs")
def upload_doc(shipment_id: int, file: UploadFile = File(...), authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    if shipments[shipment_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    os.makedirs(f"/var/shipments/{shipment_id}", exist_ok=True)
    file_path = f"/var/shipments/{shipment_id}/{file.filename}"
    with open(file_path, "wb") as f:
        shutil.copyfileobj(file.file, f)
    return {"filename": file.filename}

@app.get("/shipment/{shipment_id}/docs/{file_name}")
def get_doc(shipment_id: int, file_name: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    if shipments[shipment_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    file_path = f"/var/shipments/{shipment_id}/{file_name}"
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="File not found")
    return FileResponse(file_path, media_type="application/pdf")

@app.get("/shipment/{shipment_id}/docs/zip")
def download_all_docs(shipment_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    if shipments[shipment_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    dir_path = f"/var/shipments/{shipment_id}"
    if not os.path.exists(dir_path):
        raise HTTPException(status_code=404, detail="No docs found")
    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(dir_path):
            for file in files:
                file_path = os.path.join(root, file)
                zf.write(file_path, arcname=file)
    zip_buffer.seek(0)
    return StreamingResponse(zip_buffer, media_type="application/zip", headers={"Content-Disposition": f"attachment; filename=shipment_{shipment_id}_docs.zip"})

