import os
import time
from datetime import datetime, timedelta
from pathlib import Path

from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import uvicorn

app = FastAPI()

# In-memory user store
users = {}
user_id_counter = 1
# In-memory token store: token -> user_id
tokens = {}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ResourceCreate(BaseModel):
    pass

resources = {}
resource_type_counters = {}

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[req.username] = {"password": req.password, "id": user_id_counter}
    user_id_counter += 1
    return {"message": "User created", "user_id": users[req.username]["id"]}

@app.post("/login")
def login(req: LoginRequest, authorization: str = Header(None)):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = f"tok_{req.username}_{int(time.time())}"
    tokens[token] = users[req.username]["id"]
    return {"token": token}

def get_user_id(token: str):
    if token.startswith("Bearer "):
        token = token[7:]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.get("/{resource_type}/{resource_id}")
def get_resource(resource_type: str, resource_id: int, authorization: str = Header(None)):
    user_id = get_user_id(authorization)
    key = f"{resource_type}:{resource_id}"
    if key not in resources:
        raise HTTPException(status_code=404, detail="Resource not found")
    return resources[key]

@app.post("/{resource_type}")
def create_resource(resource_type: str, req: ResourceCreate, authorization: str = Header(None)):
    user_id = get_user_id(authorization)
    if resource_type not in resource_type_counters:
        resource_type_counters[resource_type] = 1
    else:
        resource_type_counters[resource_type] += 1
    resource_id = resource_type_counters[resource_type]
    key = f"{resource_type}:{resource_id}"
    resources[key] = {"id": resource_id, "data": req.dict()}
    return {"id": resource_id}

# Image serving endpoint
@app.get("/article/{date}/{file}")
def serve_article_image(date: str, file: str, if_modified_since: str = Header(None)):
    base_path = Path("/var/news") / date
    file_path = base_path / file

    if not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail="File not found")

    stat = file_path.stat()
    last_modified = datetime.fromtimestamp(stat.st_mtime)
    expires = datetime.utcnow() + timedelta(days=1)

    if if_modified_since:
        try:
            ims = datetime.strptime(if_modified_since, "%a, %d %b %Y %H:%M:%S %Z")
            if last_modified <= ims:
                return "", 304, {
                    "Cache-Control": "public, max-age=86400",
                    "Expires": expires.strftime("%a, %d %b %Y %H:%M:%S GMT"),
                    "Last-Modified": last_modified.strftime("%a, %d %b %Y %H:%M:%S GMT"),
                }
        except:
            pass

    with open(file_path, "rb") as f:
        content = f.read()

    import mimetypes
    content_type, _ = mimetypes.guess_type(file)
    if content_type is None:
        content_type = "application/octet-stream"

    return content, 200, {
        "Content-Type": content_type,
        "Cache-Control": "public, max-age=86400",
        "Expires": expires.strftime("%a, %d %b %Y %H:%M:%S GMT"),
        "Last-Modified": last_modified.strftime("%a, %d %b %Y %H:%M:%S GMT"),
    }

if __name__ == "__main__":
    uvicorn.run(app, host="127.0.0.1", port=8000)

