MUSEUM_BASE = "/var/museum"

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ExhibitCreate(BaseModel):
    name: str
    description: str = ""

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer" or not token:
        raise HTTPException(status_code=401, detail="Invalid auth header")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created", "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    stored = users.get(req.username)
    if not stored or stored != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/exhibit")
def create_exhibit(req: ExhibitCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global exhibit_counter
    eid = exhibit_counter
    exhibit_counter += 1
    exhibits[eid] = {"id": eid, "name": req.name, "description": req.description, "owner": user}
    exhibit_dir = Path(f"{MUSEUM_BASE}/{eid}")
    exhibit_dir.mkdir(parents=True, exist_ok=True)
    return exhibits[eid]

@app.get("/exhibit/{eid}")
def get_exhibit(eid: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    exhibit = exhibits.get(eid)
    if not exhibit:
        raise HTTPException(status_code=404, detail="Exhibit not found")
    return exhibit

@app.get("/exhibit/{eid}/media/{file}")
def get_media(eid: int, file: str, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if eid not in exhibits:
        raise HTTPException(status_code=404, detail="Exhibit not found")
    file_path = Path(f"{MUSEUM_BASE}/{eid}/{file}")
    if not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail="File not found")
    return FileResponse(str(file_path))

@app.get("/exhibit/{eid}/virtual-tour")
def virtual_tour(eid: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if eid not in exhibits:
        raise HTTPException(status_code=404, detail="Exhibit not found")
    exhibit_dir = Path(f"{MUSEUM_BASE}/{eid}")
    if not exhibit_dir.exists():
        return HTMLResponse("<h1>Virtual Tour</h1><p>No files yet.</p>")
