    get_user_from_token(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    photos_dir = f"/var/recipes/{recipe_id}"
    if not os.path.exists(photos_dir):
        raise HTTPException(status_code=404, detail="No photos directory")

    tar_buffer = io.BytesIO()
    with tarfile.open(fileobj=tar_buffer, mode="w:gz") as tar:
        for filename in os.listdir(photos_dir):
            filepath = os.path.join(photos_dir, filename)
            if os.path.isfile(filepath):
                tar.add(filepath, arcname=filename)
    tar_buffer.seek(0)
    return StreamingResponse(tar_buffer, media_type="application/gzip", headers={"Content-Disposition": f"attachment; filename=recipe_{recipe_id}_photos.tar.gz"})

