import os
import shutil
import time
import hashlib
import secrets
from pathlib import Path
from typing import Optional

from fastapi import FastAPI, HTTPException, Header, UploadFile, File, Form
from fastapi.responses import FileResponse

app = FastAPI()

users = {}
tokens = {}
teams = {}
doc_versions = {}

BASE_DIR = "/var/teams"

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
async def signup(username: str = Form(...), password: str = Form(...)):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    user_id = len(users) + 1
    users[username] = {"id": user_id, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
async def login(username: str = Form(...), password: str = Form(...)):
    if username not in users or users[username]["password"] != password:
        raise HTTPException(status_code=401, detail="Bad credentials")
    token = secrets.token_hex(32)
    tokens[token] = users[username]
    return {"token": token}

@app.post("/team")
async def create_team(name: str = Form(...), authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    team_id = len(teams) + 1
    teams[team_id] = {"id": team_id, "name": name, "owner": user["id"]}
    os.makedirs(f"{BASE_DIR}/{team_id}", exist_ok=True)
    return teams[team_id]

@app.get("/team/{team_id}")
async def get_team(team_id: int, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if team_id not in teams:
        raise HTTPException(status_code=404, detail="Team not found")
    return teams[team_id]

@app.post("/team/{team_id}/docs")
async def upload_doc(team_id: int, file: UploadFile = File(...), authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if team_id not in teams:
        raise HTTPException(status_code=404, detail="Team not found")
    team_dir = f"{BASE_DIR}/{team_id}"
    os.makedirs(team_dir, exist_ok=True)
    file_path = f"{team_dir}/{file.filename}"
    content = await file.read()
    with open(file_path, "wb") as f:
        f.write(content)
    if team_id not in doc_versions:
        doc_versions[team_id] = {}
    if file.filename not in doc_versions[team_id]:
        doc_versions[team_id][file.filename] = []
    version = len(doc_versions[team_id][file.filename]) + 1
    version_dir = f"{team_dir}/.versions/{file.filename}"
    os.makedirs(version_dir, exist_ok=True)
    shutil.copy2(file_path, f"{version_dir}/v{version}")
    doc_versions[team_id][file.filename].append({"version": version, "timestamp": time.time()})
    return {"filename": file.filename, "version": version}

@app.get("/team/{team_id}/docs/{file_path:path}")
async def get_doc(team_id: int, file_path: str, v: Optional[int] = None, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if team_id not in teams:
        raise HTTPException(status_code=404, detail="Team not found")
    if v:
        version_dir = f"{BASE_DIR}/{team_id}/.versions/{file_path}"
        version_file = f"{version_dir}/v{v}"
        if not os.path.exists(version_file):
            raise HTTPException(status_code=404, detail="Version not found")
        return FileResponse(version_file)
    full_path = f"{BASE_DIR}/{team_id}/{file_path}"
    if not os.path.exists(full_path):
        raise HTTPException(status_code=404, detail="File not found")
