from pydantic import BaseModel

app = FastAPI()

users = {}
tokens = {}
assets = {}
asset_versions = {}
asset_id_counter = 1

GAME_ASSETS_DIR = "/game_assets/"

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class AssetCreate(BaseModel):
    name: str
    file_path: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def verify_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/assets")
def create_asset(req: AssetCreate, authorization: str = Header(None)):
    user = verify_token(authorization)
    global asset_id_counter
    asset_id = asset_id_counter
    asset_id_counter += 1
    assets[asset_id] = {"id": asset_id, "name": req.name, "file_path": req.file_path, "owner": user}
    asset_versions[asset_id] = [{"version": 1, "file_path": req.file_path}]
    return {"id": asset_id, "name": req.name}

@app.get("/assets/{asset_id}")
def get_asset(asset_id: int, authorization: str = Header(None)):
    verify_token(authorization)
    if asset_id not in assets:
        raise HTTPException(status_code=404, detail="Asset not found")
    return assets[asset_id]

@app.get("/assets/{game_id}/{asset_path:path}")
def stream_asset(game_id: int, asset_path: str, version: int = Query(None), authorization: str = Header(None)):
    verify_token(authorization)
    full_path = os.path.join(GAME_ASSETS_DIR, asset_path)
    if not os.path.exists(full_path):
        raise HTTPException(status_code=404, detail="File not found")
    if version is not None:
        if game_id not in asset_versions:
            raise HTTPException(status_code=404, detail="No versions for this asset")
        version_data = next((v for v in asset_versions[game_id] if v["version"] == version), None)
        if not version_data:
            raise HTTPException(status_code=404, detail="Version not found")
        full_path = os.path.join(GAME_ASSETS_DIR, version_data["file_path"])
        if not os.path.exists(full_path):
            raise HTTPException(status_code=404, detail="Version file not found")
    return FileResponse(full_path, media_type="application/octet-stream")

