import hashlib
import os
from datetime import datetime
from io import BytesIO

from fastapi import FastAPI, HTTPException, Header, Query
from fastapi.responses import StreamingResponse
from pydantic import BaseModel
from reportlab.lib.pagesizes import letter
from reportlab.pdfgen import canvas

app = FastAPI()

# In-memory storage
users = {}
next_user_id = 1
tokens = {}
transactions = {}
next_txn_id = 1

# Simple auth helper
def get_user_from_token(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Missing or invalid token")
    token = authorization.split(" ")[1]
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

# --- Auth endpoints ---

class SignupRequest(BaseModel):
    username: str
    password: str

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[req.username] = {"id": user_id, "password": req.password}
    return {"user_id": user_id, "username": req.username}

class LoginRequest(BaseModel):
    username: str
    password: str

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = hashlib.sha256(os.urandom(32)).hexdigest()
    tokens[token] = user["id"]
    return {"token": token}

# --- Transaction endpoints ---

class TransactionCreate(BaseModel):
    amount: float
    date: str  # ISO format e.g. 2025-01-15

@app.post("/transactions")
def create_transaction(req: TransactionCreate, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    global next_txn_id
    txn_id = next_txn_id
    next_txn_id += 1
    transactions[txn_id] = {
        "id": txn_id,
        "user_id": user_id,
        "amount": req.amount,
        "date": req.date,
    }
    return {"id": txn_id, "amount": req.amount, "date": req.date}

@app.get("/transactions/{txn_id}")
def get_transaction(txn_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    txn = transactions.get(txn_id)
    if not txn:
        raise HTTPException(status_code=404, detail="Transaction not found")
    if txn["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return txn

# --- Receipt endpoints ---

@app.get("/receipts/{txn_id}")
def get_receipt(txn_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    txn = transactions.get(txn_id)
    if not txn:
        raise HTTPException(status_code=404, detail="Transaction not found")
    if txn["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")

    # Generate PDF
    buf = BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    c.drawString(100, 750, f"Receipt for Transaction #{txn_id}")
    c.drawString(100, 730, f"Date: {txn['date']}")
    c.drawString(100, 710, f"Amount: ${txn['amount']:.2f}")
    c.drawString(100, 690, "Thank you for your business!")
    c.save()
    buf.seek(0)

    return StreamingResponse(buf, media_type="application/pdf",
                             headers={"Content-Disposition": f"attachment; filename=receipt_{txn_id}.pdf"})

class BatchReceiptRequest(BaseModel):
    txn_ids: list[int]

@app.post("/receipts/batch")
def batch_receipts(req: BatchReceiptRequest, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    from PyPDF2 import PdfMerger
    merger = PdfMerger()
    for txn_id in req.txn_ids:
        txn = transactions.get(txn_id)
        if not txn or txn["user_id"] != user_id:
            continue
        buf = BytesIO()
        c = canvas.Canvas(buf, pagesize=letter)
        c.drawString(100, 750, f"Receipt for Transaction #{txn_id}")
        c.drawString(100, 730, f"Date: {txn['date']}")
        c.drawString(100, 710, f"Amount: ${txn['amount']:.2f}")
        c.drawString(100, 690, "Thank you for your business!")
        c.save()
        buf.seek(0)
        merger.append(buf)
    out = BytesIO()
    merger.write(out)
    out.seek(0)
    return StreamingResponse(out, media_type="application/pdf",
                             headers={"Content-Disposition": "attachment; filename=receipts_batch.pdf"})

