    global next_txn_id
    txn_id = next_txn_id
    next_txn_id += 1
    transactions[txn_id] = {
        "id": txn_id,
        "user_id": user_id,
        "amount": req.amount,
        "date": req.date,
    }
    return {"id": txn_id, "amount": req.amount, "date": req.date}

@app.get("/transactions/{txn_id}")
def get_transaction(txn_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    txn = transactions.get(txn_id)
    if not txn:
        raise HTTPException(status_code=404, detail="Transaction not found")
    if txn["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return txn

# --- Receipt endpoints ---

@app.get("/receipts/{txn_id}")
def get_receipt(txn_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    txn = transactions.get(txn_id)
    if not txn:
        raise HTTPException(status_code=404, detail="Transaction not found")
    if txn["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")

    # Generate PDF
    buf = BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    c.drawString(100, 750, f"Receipt for Transaction #{txn_id}")
    c.drawString(100, 730, f"Date: {txn['date']}")
    c.drawString(100, 710, f"Amount: ${txn['amount']:.2f}")
    c.drawString(100, 690, "Thank you for your business!")
    c.save()
    buf.seek(0)

    return StreamingResponse(buf, media_type="application/pdf",
                             headers={"Content-Disposition": f"attachment; filename=receipt_{txn_id}.pdf"})

class BatchReceiptRequest(BaseModel):
    txn_ids: list[int]

@app.post("/receipts/batch")
def batch_receipts(req: BatchReceiptRequest, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    from PyPDF2 import PdfMerger
    merger = PdfMerger()
    for txn_id in req.txn_ids:
        txn = transactions.get(txn_id)
        if not txn or txn["user_id"] != user_id:
            raise HTTPException(status_code=403, detail="Access denied to one or more transactions")
        buf = BytesIO()
        c = canvas.Canvas(buf, pagesize=letter)
        c.drawString(100, 750, f"Receipt for Transaction #{txn_id}")
        c.drawString(100, 730, f"Date: {txn['date']}")
        c.drawString(100, 710, f"Amount: ${txn['amount']:.2f}")
        c.drawString(100, 690, "Thank you for your business!")
        c.save()
        buf.seek(0)
        merger.append(buf)
    out = BytesIO()
    merger.write(out)
    out.seek(0)
    return StreamingResponse(out, media_type="application/pdf",
                             headers={"Content-Disposition": "attachment; filename=receipts_batch.pdf"})

