from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import secrets
import datetime

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
bills = {}
bill_items = {}
payments = {}
collectors = {}

# ID counters
user_id_counter = 1
bill_id_counter = 1
bill_item_id_counter = 1
payment_id_counter = 1

# Models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class BillCreate(BaseModel):
    title: str
    total_amount: float
    split_among: List[int]  # user IDs

class BillItemCreate(BaseModel):
    bill_id: int
    user_id: int
    amount: float
    description: Optional[str] = None

class PaymentCreate(BaseModel):
    bill_id: int
    from_user_id: int
    amount: float

class CollectorPromote(BaseModel):
    bill_id: int
    collector_user_id: int
    fee_percentage: float = 0.0

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Auth endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for uid, u in users.items():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password  # plaintext, we said no security
    }
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Resource endpoints
@app.get("/bills/{bill_id}")
def get_bill(bill_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    return bills[bill_id]

@app.post("/bills")
def create_bill(bill: BillCreate, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    global bill_id_counter
    bill_id = bill_id_counter
    bill_id_counter += 1
    bills[bill_id] = {
        "id": bill_id,
        "title": bill.title,
        "total_amount": bill.total_amount,
        "split_among": bill.split_among,
        "created_by": current_user,
        "created_at": datetime.datetime.now().isoformat()
    }
    return {"bill_id": bill_id, "message": "Bill created"}

@app.get("/bill_items/{item_id}")
def get_bill_item(item_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if item_id not in bill_items:
        raise HTTPException(status_code=404, detail="Bill item not found")
    return bill_items[item_id]

@app.post("/bill_items")
def create_bill_item(item: BillItemCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if item.bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    global bill_item_id_counter
    item_id = bill_item_id_counter
    bill_item_id_counter += 1
    bill_items[item_id] = {
        "id": item_id,
        "bill_id": item.bill_id,
        "user_id": item.user_id,
        "amount": item.amount,
        "description": item.description
    }
    return {"item_id": item_id, "message": "Bill item created"}

@app.get("/payments/{payment_id}")
def get_payment(payment_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if payment_id not in payments:
        raise HTTPException(status_code=404, detail="Payment not found")
    return payments[payment_id]

@app.post("/payments")
def create_payment(payment: PaymentCreate, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if payment.bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    global payment_id_counter
    payment_id = payment_id_counter
    payment_id_counter += 1
    payments[payment_id] = {
        "id": payment_id,
        "bill_id": payment.bill_id,
        "from_user_id": payment.from_user_id,
        "amount": payment.amount,
        "paid_by": current_user,
        "timestamp": datetime.datetime.now().isoformat()
    }
    return {"payment_id": payment_id, "message": "Payment recorded"}

# Collector endpoints
@app.post("/collectors/promote")
def promote_collector(req: CollectorPromote, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if req.bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    if req.collector_user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    collectors[req.bill_id] = {
        "bill_id": req.bill_id,
        "collector_user_id": req.collector_user_id,
        "fee_percentage": req.fee_percentage,
        "promoted_by": current_user
    }
    return {"message": f"User {req.collector_user_id} is now collector for bill {req.bill_id}"}

@app.post("/collectors/chase/{bill_id}")
def chase_payments(bill_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    if bill_id not in collectors:
        raise HTTPException(status_code=400, detail="No collector for this bill")
    collector = collectors[bill_id]
    if collector["collector_user_id"] != current_user:
        raise HTTPException(status_code=403, detail="You are not the collector")
    bill = bills[bill_id]
    total_paid = sum(p["amount"] for p in payments.values() if p["bill_id"] == bill_id)
    outstanding = bill["total_amount"] - total_paid
    fee = outstanding * (collector["fee_percentage"] / 100)
    return {
        "bill_id": bill_id,
        "outstanding": outstanding,
        "collector_fee": fee,
        "total_due": outstanding + fee,
        "message": "Chase sent (simulated)"
    }

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    u = users[user_id]
    return {"id": u["id"], "username": u["username"]}

@app.get("/collectors/{bill_id}")
def get_collector(bill_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if bill_id not in collectors:
        raise HTTPException(status_code=404, detail="No collector for this bill")
    return collectors[bill_id]

