    }
    return {"payment_id": payment_id, "message": "Payment recorded"}

# Collector endpoints
@app.post("/collectors/promote")
def promote_collector(req: CollectorPromote, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if req.bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    if req.collector_user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    bill = bills[req.bill_id]
    if current_user != bill["created_by"]:
        raise HTTPException(status_code=403, detail="Only the bill creator can promote a collector")
    collectors[req.bill_id] = {
        "bill_id": req.bill_id,
        "collector_user_id": req.collector_user_id,
        "fee_percentage": req.fee_percentage,
        "promoted_by": current_user
    }
    return {"message": f"User {req.collector_user_id} is now collector for bill {req.bill_id}"}

@app.post("/collectors/chase/{bill_id}")
def chase_payments(bill_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    if bill_id not in collectors:
        raise HTTPException(status_code=400, detail="No collector for this bill")
    collector = collectors[bill_id]
    if collector["collector_user_id"] != current_user:
        raise HTTPException(status_code=403, detail="You are not the collector")
    bill = bills[bill_id]
    total_paid = sum(p["amount"] for p in payments.values() if p["bill_id"] == bill_id)
    outstanding = bill["total_amount"] - total_paid
    fee = outstanding * (collector["fee_percentage"] / 100)
    return {
        "bill_id": bill_id,
        "outstanding": outstanding,
        "collector_fee": fee,
        "total_due": outstanding + fee,
        "message": "Chase sent (simulated)"
    }

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    u = users[user_id]
    return {"id": u["id"], "username": u["username"]}

@app.get("/collectors/{bill_id}")
def get_collector(bill_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if bill_id not in collectors:
        raise HTTPException(status_code=404, detail="No collector for this bill")
    collector = collectors[bill_id]
    bill = bills[bill_id]
    if current_user != bill["created_by"] and current_user not in bill["split_among"] and current_user != collector["collector_user_id"]:
        raise HTTPException(status_code=403, detail="Not authorized to view collector info for this bill")
    return collector

