from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import uuid
import datetime

app = FastAPI()

users = {}
tokens = {}
workspaces = {}
channels = {}
messages = {}
attachments = {}
next_user_id = 1
next_workspace_id = 1
next_channel_id = 1
next_message_id = 1
next_attachment_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return users[user_id]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password, "role": "user"}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == password:
            token = str(uuid.uuid4())
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/user/{user_id}")
def get_user(user_id: int):
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404)
    return {"id": user["id"], "username": user["username"], "role": user["role"]}

@app.post("/workspace")
def create_workspace(name: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    global next_workspace_id
    ws_id = next_workspace_id
    next_workspace_id += 1
    workspaces[ws_id] = {"id": ws_id, "name": name, "owner_id": user["id"], "admins": [user["id"]], "members": [user["id"]]}
    return workspaces[ws_id]

@app.get("/workspace/{ws_id}")
def get_workspace(ws_id: int):
    ws = workspaces.get(ws_id)
    if not ws:
        raise HTTPException(status_code=404)
    return ws

@app.post("/workspace/{ws_id}/join")
def join_workspace(ws_id: int, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    ws = workspaces.get(ws_id)
    if not ws:
        raise HTTPException(status_code=404)
    if user["id"] not in ws["members"]:
        ws["members"].append(user["id"])
    return {"status": "joined"}

@app.post("/workspace/{ws_id}/promote")
def promote_user(ws_id: int, user_id: int, authorization: Optional[str] = Header(None)):
    requester = get_current_user(authorization)
    ws = workspaces.get(ws_id)
    if not ws:
        raise HTTPException(status_code=404)
    if requester["id"] != ws["owner_id"]:
        raise HTTPException(status_code=403, detail="Only owner can promote")
    if user_id not in ws["members"]:
        raise HTTPException(status_code=400, detail="User not in workspace")
    if user_id not in ws["admins"]:
        ws["admins"].append(user_id)
    users[user_id]["role"] = "admin"
    return {"status": "promoted"}

@app.post("/channel")
def create_channel(workspace_id: int, name: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    ws = workspaces.get(workspace_id)
    if not ws:
        raise HTTPException(status_code=404)
    if user["id"] not in ws["members"]:
        raise HTTPException(status_code=403)
    global next_channel_id
    ch_id = next_channel_id
    next_channel_id += 1
    channels[ch_id] = {"id": ch_id, "workspace_id": workspace_id, "name": name, "permissions": {"read": ["user"], "write": ["user"]}}
    return channels[ch_id]

@app.get("/channel/{ch_id}")
def get_channel(ch_id: int):
    ch = channels.get(ch_id)
    if not ch:
        raise HTTPException(status_code=404)
    return ch

@app.post("/message")
def send_message(channel_id: int, content: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    ch = channels.get(channel_id)
    if not ch:
        raise HTTPException(status_code=404)
    ws = workspaces.get(ch["workspace_id"])
    if user["id"] not in ws["members"]:
        raise HTTPException(status_code=403)
    global next_message_id
    msg_id = next_message_id
    next_message_id += 1
    messages[msg_id] = {"id": msg_id, "channel_id": channel_id, "sender_id": user["id"], "content": content, "timestamp": datetime.datetime.now().isoformat(), "attachment_ids": []}
    return messages[msg_id]

@app.get("/message/{msg_id}")
def get_message(msg_id: int):
    msg = messages.get(msg_id)
    if not msg:
        raise HTTPException(status_code=404)
    return msg

@app.get("/channel/{ch_id}/messages")
def get_channel_messages(ch_id: int):
    return [m for m in messages.values() if m["channel_id"] == ch_id]

@app.post("/attachment")
def upload_attachment(channel_id: int, filename: str, file_url: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    ch = channels.get(channel_id)
    if not ch:
        raise HTTPException(status_code=404)
    ws = workspaces.get(ch["workspace_id"])
    if user["id"] not in ws["members"]:
        raise HTTPException(status_code=403)
    global next_attachment_id
    att_id = next_attachment_id
    next_attachment_id += 1
    attachments[att_id] = {"id": att_id, "channel_id": channel_id, "uploader_id": user["id"], "filename": filename, "file_url": file_url}
    return attachments[att_id]

@app.get("/attachment/{att_id}")
def get_attachment(att_id: int):
    att = attachments.get(att_id)
    if not att:
        raise HTTPException(status_code=404)
    return att

