from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict, List
import secrets
import datetime

app = FastAPI()

# In-memory stores
users: Dict[int, dict] = {}
tokens: Dict[str, int] = {}  # token -> user_id
profiles: Dict[int, dict] = {}
pets: Dict[int, dict] = {}
next_user_id = 1
next_profile_id = 1
next_pet_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ProfileCreate(BaseModel):
    name: str
    bio: Optional[str] = ""

class PetCreate(BaseModel):
    name: str
    feeding_schedule: str
    stay_duration_days: int
    photo_url: Optional[str] = ""

def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password  # plaintext because we ship fast
    }
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/profile")
def create_profile(req: ProfileCreate, authorization: str = Header(None)):
    global next_profile_id
    user_id = get_user_id_from_token(authorization)
    # First sitter becomes host
    if not profiles:
        role = "host"
    else:
        role = "sitter"
    profile_id = next_profile_id
    next_profile_id += 1
    profiles[profile_id] = {
        "id": profile_id,
        "user_id": user_id,
        "name": req.name,
        "bio": req.bio,
        "role": role,
        "co_hosts": []
    }
    return {"profile_id": profile_id, "role": role}

@app.get("/profile/{profile_id}")
def get_profile(profile_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    profile = profiles.get(profile_id)
    if not profile:
        raise HTTPException(status_code=404, detail="Profile not found")
    return profile

@app.post("/profile/{profile_id}/promote")
def promote_to_co_host(profile_id: int, target_user_id: int, authorization: str = Header(None)):
    user_id = get_user_id_from_token(authorization)
    profile = profiles.get(profile_id)
    if not profile:
        raise HTTPException(status_code=404, detail="Profile not found")
    if profile["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Only the host can promote")
    if profile["role"] != "host":
        raise HTTPException(status_code=400, detail="Only a host profile can promote")
    # Find target user's profile
    target_profile = None
    for p in profiles.values():
        if p["user_id"] == target_user_id:
            target_profile = p
            break
    if not target_profile:
        raise HTTPException(status_code=404, detail="Target user has no profile")
    if target_user_id not in profile["co_hosts"]:
        profile["co_hosts"].append(target_user_id)
    target_profile["role"] = "co_host"
    return {"message": f"User {target_user_id} promoted to co-host"}

@app.post("/pet")
def create_pet(req: PetCreate, authorization: str = Header(None)):
    global next_pet_id
    user_id = get_user_id_from_token(authorization)
    pet_id = next_pet_id
    next_pet_id += 1
    pets[pet_id] = {
        "id": pet_id,
        "owner_user_id": user_id,
        "name": req.name,
        "feeding_schedule": req.feeding_schedule,
        "stay_duration_days": req.stay_duration_days,
        "photo_url": req.photo_url,
        "photo_updates": []
    }
    return {"pet_id": pet_id}

@app.get("/pet/{pet_id}")
def get_pet(pet_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    pet = pets.get(pet_id)
    if not pet:
        raise HTTPException(status_code=404, detail="Pet not found")
    return pet

@app.post("/pet/{pet_id}/photo")
def update_pet_photo(pet_id: int, photo_url: str, authorization: str = Header(None)):
    user_id = get_user_id_from_token(authorization)
    pet = pets.get(pet_id)
    if not pet:
        raise HTTPException(status_code=404, detail="Pet not found")
    pet["photo_url"] = photo_url
    pet["photo_updates"].append({
        "url": photo_url,
        "timestamp": datetime.datetime.utcnow().isoformat(),
        "updated_by": user_id
    })
    return {"message": "Photo updated"}

