from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
events = {}
orders = {}
tickets = {}

user_id_counter = 1
event_id_counter = 1
order_id_counter = 1
ticket_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str, role: str = "user"):
    global user_id_counter
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": username, "password": password, "role": role}
    return {"user_id": user_id, "username": username, "role": role}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/promote/{user_id}")
def promote(user_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] != "admin":
        raise HTTPException(status_code=403, detail="Only admin can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["role"] = "box_office_manager"
    return {"user_id": user_id, "role": "box_office_manager"}

@app.post("/events")
def create_event(name: str, date: str, total_tickets: int, price: float, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    global event_id_counter
    event_id = event_id_counter
    event_id_counter += 1
    events[event_id] = {
        "id": event_id,
        "name": name,
        "date": date,
        "total_tickets": total_tickets,
        "available_tickets": total_tickets,
        "price": price,
        "created_by": current_user_id
    }
    return events[event_id]

@app.get("/events/{event_id}")
def get_event(event_id: int):
    if event_id not in events:
        raise HTTPException(status_code=404, detail="Event not found")
    return events[event_id]

@app.post("/orders")
def create_order(event_id: int, quantity: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if event_id not in events:
        raise HTTPException(status_code=404, detail="Event not found")
    event = events[event_id]
    if event["available_tickets"] < quantity:
        raise HTTPException(status_code=400, detail="Not enough tickets")
    total_price = event["price"] * quantity
    global order_id_counter
    order_id = order_id_counter
    order_id_counter += 1
    orders[order_id] = {
        "id": order_id,
        "user_id": current_user_id,
        "event_id": event_id,
        "quantity": quantity,
        "total_price": total_price,
        "status": "confirmed"
    }
    event["available_tickets"] -= quantity
    for _ in range(quantity):
        global ticket_id_counter
        ticket_id = ticket_id_counter
        ticket_id_counter += 1
        tickets[ticket_id] = {
            "id": ticket_id,
            "order_id": order_id,
            "event_id": event_id,
            "owner_id": current_user_id
        }
