from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
tenants = {}
listings = {}

user_id_counter = 1
tenant_id_counter = 1
listing_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"username": username, "password": password, "role": "user"}
    return {"user_id": user_id}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/tenants")
def create_tenant(name: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global tenant_id_counter
    tenant_id = tenant_id_counter
    tenant_id_counter += 1
    tenants[tenant_id] = {"name": name, "admin_id": user_id, "managers": []}
    return {"tenant_id": tenant_id}

@app.get("/tenants/{tenant_id}")
def get_tenant(tenant_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    tenant = tenants.get(tenant_id)
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")
    return tenant

@app.post("/tenants/{tenant_id}/promote")
def promote_to_manager(tenant_id: int, user_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    tenant = tenants.get(tenant_id)
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")
    if tenant["admin_id"] != current_user:
        raise HTTPException(status_code=403, detail="Only tenant admin can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if user_id not in tenant["managers"]:
        tenant["managers"].append(user_id)
    return {"message": "User promoted to manager"}

