from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict, List
import secrets

app = FastAPI()

users = {}
projects = {}
pledges = {}
stretch_goals = {}
backer_promotions = {}
auth_tokens = {}
next_user_id = 1
next_project_id = 1
next_pledge_id = 1
next_stretch_goal_id = 1
next_promotion_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ProjectCreate(BaseModel):
    title: str
    description: str
    funding_goal: float

class PledgeCreate(BaseModel):
    project_id: int
    amount: float

class StretchGoalCreate(BaseModel):
    project_id: int
    target_amount: float
    reward_description: str

class PromoteRequest(BaseModel):
    backer_user_id: int

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in auth_tokens:
        raise HTTPException(status_code=401, detail="Invalid auth token")
    return auth_tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = secrets.token_hex(32)
            auth_tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/project")
def create_project(req: ProjectCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_project_id
    project_id = next_project_id
    next_project_id += 1
    projects[project_id] = {
        "id": project_id,
        "title": req.title,
        "description": req.description,
        "funding_goal": req.funding_goal,
        "creator_user_id": user_id,
        "total_pledged": 0.0
    }
    return {"project_id": project_id}

@app.get("/project/{project_id}")
def get_project(project_id: int):
    project = projects.get(project_id)
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    total_pledged = sum(p["amount"] for p in pledges.values() if p["project_id"] == project_id)
    project["total_pledged"] = total_pledged
    progress = min(100, (total_pledged / project["funding_goal"]) * 100) if project["funding_goal"] > 0 else 0
    return {
        **project,
        "funding_progress_percent": round(progress, 2)
    }

@app.post("/pledge")
def create_pledge(req: PledgeCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if req.project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    global next_pledge_id
    pledge_id = next_pledge_id
    next_pledge_id += 1
    pledges[pledge_id] = {
        "id": pledge_id,
        "project_id": req.project_id,
        "backer_user_id": user_id,
        "amount": req.amount
    }
    project = projects[req.project_id]
    project["total_pledged"] += req.amount
    return {"pledge_id": pledge_id, "message": "Pledge created"}

@app.get("/pledge/{pledge_id}")
def get_pledge(pledge_id: int):
    pledge = pledges.get(pledge_id)
    if not pledge:
        raise HTTPException(status_code=404, detail="Pledge not found")
    return pledge

@app.post("/stretch_goal")
def create_stretch_goal(req: StretchGoalCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if req.project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    project = projects[req.project_id]
    if project["creator_user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Only project creator can add stretch goals")
    global next_stretch_goal_id
    sg_id = next_stretch_goal_id
    next_stretch_goal_id += 1
    stretch_goals[sg_id] = {
        "id": sg_id,
        "project_id": req.project_id,
        "target_amount": req.target_amount,
        "reward_description": req.reward_description,
        "reached": False
    }
    return {"stretch_goal_id": sg_id}

@app.get("/stretch_goal/{sg_id}")
def get_stretch_goal(sg_id: int):
    sg = stretch_goals.get(sg_id)
    if not sg:
        raise HTTPException(status_code=404, detail="Stretch goal not found")
    project = projects.get(sg["project_id"])
    if project and project["total_pledged"] >= sg["target_amount"]:
        sg["reached"] = True
    return sg

@app.post("/project/{project_id}/promote")
def promote_backer(project_id: int, req: PromoteRequest, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    project = projects.get(project_id)
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    if project["creator_user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Only project creator can promote backers")
    backer = users.get(req.backer_user_id)
    if not backer:
        raise HTTPException(status_code=404, detail="Backer not found")
    has_pledged = any(p["backer_user_id"] == req.backer_user_id and p["project_id"] == project_id for p in pledges.values())
    if not has_pledged:
        raise HTTPException(status_code=400, detail="User has not pledged to this project")
    global next_promotion_id
    promo_id = next_promotion_id
    next_promotion_id += 1
    backer_promotions[promo_id] = {
        "id": promo_id,
        "project_id": project_id,
        "backer_user_id": req.backer_user_id,
        "role": "co-producer"
    }
    return {"promotion_id": promo_id, "message": f"User {req.backer_user_id} promoted to co-producer"}

@app.get("/project/{project_id}/promotions")
def get_promotions(project_id: int):
    return [p for p in backer_promotions.values() if p["project_id"] == project_id]

