from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
groups = {}
group_id_counter = 1
user_id_counter = 1

def authenticate(authorization: Optional[str] = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(401, "Invalid auth")
    token = authorization[7:]
    if token not in tokens:
        raise HTTPException(401, "Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(400, "Username taken")
    uid = user_id_counter
    user_id_counter += 1
    users[uid] = {"id": uid, "username": username, "password": password}
    return {"id": uid, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(401, "Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    authenticate(authorization)
    if user_id not in users:
        raise HTTPException(404)
    return users[user_id]

@app.get("/groups/{group_id}")
def get_group(group_id: int, authorization: Optional[str] = Header(None)):
    authenticate(authorization)
    if group_id not in groups:
        raise HTTPException(404)
    return groups[group_id]

@app.post("/groups")
def create_group(name: str, book_title: str, authorization: Optional[str] = Header(None)):
    global group_id_counter
    uid = authenticate(authorization)
    gid = group_id_counter
    group_id_counter += 1
    groups[gid] = {
        "id": gid,
        "name": name,
        "book_title": book_title,
        "creator_id": uid,
        "members": [uid],
        "discussion_leaders": [],
        "reading_schedule": {},
        "discussion_notes": {}
    }
    return groups[gid]

@app.post("/groups/{group_id}/join")
def join_group(group_id: int, authorization: Optional[str] = Header(None)):
    uid = authenticate(authorization)
    if group_id not in groups:
        raise HTTPException(404)
    if uid in groups[group_id]["members"]:
        raise HTTPException(400, "Already a member")
    groups[group_id]["members"].append(uid)
