from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
from datetime import datetime
import random
import string

app = FastAPI()

# In-memory stores
users = {}
user_id_counter = 0
tokens = {}

newsletters = {}
newsletter_id_counter = 0

analytics = {}

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    email: str
    password: str

class LoginRequest(BaseModel):
    email: str
    password: str

class NewsletterCreate(BaseModel):
    subject: str
    body: str
    send_schedule: Optional[str] = None
    subscriber_segments: Optional[List[str]] = None
    a_test_enabled: bool = False
    b_test_enabled: bool = False
    a_subject: Optional[str] = None
    a_body: Optional[str] = None
    b_subject: Optional[str] = None
    b_body: Optional[str] = None

    class Config:
        extra = "forbid"

class NewsletterUpdate(BaseModel):
    subject: Optional[str] = None
    body: Optional[str] = None
    send_schedule: Optional[str] = None
    subscriber_segments: Optional[List[str]] = None
    a_test_enabled: Optional[bool] = None
    b_test_enabled: Optional[bool] = None
    a_subject: Optional[str] = None
    a_body: Optional[str] = None
    b_subject: Optional[str] = None
    b_body: Optional[str] = None

    class Config:
        extra = "forbid"

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    user_id_counter += 1
    users[user_id_counter] = {"email": req.email, "password": req.password}
    return {"user_id": user_id_counter}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["email"] == req.email and u["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/newsletters")
def create_newsletter(req: NewsletterCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global newsletter_id_counter
    newsletter_id_counter += 1
    nid = newsletter_id_counter
    newsletters[nid] = {
        "id": nid,
        "user_id": user_id,
        "subject": req.subject,
        "body": req.body,
        "send_schedule": req.send_schedule,
        "subscriber_segments": req.subscriber_segments or [],
        "a_test_enabled": req.a_test_enabled,
        "b_test_enabled": req.b_test_enabled,
        "a_subject": req.a_subject,
        "a_body": req.a_body,
        "b_subject": req.b_subject,
        "b_body": req.b_body,
        "created_at": datetime.now().isoformat()
    }
    # Initialize analytics for this newsletter
    analytics[nid] = {
        "sent": 0,
        "opened": 0,
        "clicked": 0,
        "a_sent": 0,
        "a_opened": 0,
        "a_clicked": 0,
        "b_sent": 0,
        "b_opened": 0,
        "b_clicked": 0
    }
    return newsletters[nid]

@app.get("/newsletters/{newsletter_id}")
def get_newsletter(newsletter_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    n = newsletters.get(newsletter_id)
    if not n:
        raise HTTPException(status_code=404, detail="Newsletter not found")
    if n["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your newsletter")
    return n

@app.put("/newsletters/{newsletter_id}")
def update_newsletter(newsletter_id: int, req: NewsletterUpdate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    n = newsletters.get(newsletter_id)
    if not n:
        raise HTTPException(status_code=404, detail="Newsletter not found")
    if n["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your newsletter")
    if req.subject is not None:
        n["subject"] = req.subject
    if req.body is not None:
        n["body"] = req.body
    if req.send_schedule is not None:
        n["send_schedule"] = req.send_schedule
    if req.subscriber_segments is not None:
        n["subscriber_segments"] = req.subscriber_segments
    if req.a_test_enabled is not None:
        n["a_test_enabled"] = req.a_test_enabled
    if req.b_test_enabled is not None:
        n["b_test_enabled"] = req.b_test_enabled
    if req.a_subject is not None:
        n["a_subject"] = req.a_subject
    if req.a_body is not None:
        n["a_body"] = req.a_body
    if req.b_subject is not None:
        n["b_subject"] = req.b_subject
    if req.b_body is not None:
        n["b_body"] = req.b_body
    return n

@app.get("/analytics/{newsletter_id}")
def get_analytics(newsletter_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    n = newsletters.get(newsletter_id)
    if not n:
        raise HTTPException(status_code=404, detail="Newsletter not found")
    if n["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your newsletter")
    return analytics.get(newsletter_id, {})

