from typing import Optional, List
import uuid
import shutil
import os
from datetime import datetime

app = FastAPI()

users = {}
tokens = {}
tickets = {}
ticket_id_counter = 1
uploads_dir = "uploads"
os.makedirs(uploads_dir, exist_ok=True)

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TicketCreate(BaseModel):
    description: str
    priority: Optional[str] = "medium"
    assigned_worker: Optional[str] = None
    status: Optional[str] = "open"

class TicketUpdate(BaseModel):
    description: Optional[str] = None
    priority: Optional[str] = None
    assigned_worker: Optional[str] = None
    status: Optional[str] = None

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = {"username": req.username, "password": req.password}
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = req.username
    return {"token": token}

