def get_ticket(ticket_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if ticket_id not in tickets:
        raise HTTPException(status_code=404, detail="Ticket not found")
    return tickets[ticket_id]

@app.post("/tickets")
def create_ticket(req: TicketCreate, authorization: str = Header(None)):
    get_user_from_token(authorization)
    global ticket_id_counter
    ticket = {
        "id": ticket_id_counter,
        "description": req.description,
        "priority": req.priority,
        "assigned_worker": req.assigned_worker,
        "status": req.status,
        "images": [],
        "history": [{"action": "created", "timestamp": datetime.now().isoformat()}]
    }
    tickets[ticket_id_counter] = ticket
    ticket_id_counter += 1
    return ticket

@app.patch("/tickets/{ticket_id}")
async def update_ticket(
    ticket_id: int,
    description: Optional[str] = Form(None),
    priority: Optional[str] = Form(None),
    assigned_worker: Optional[str] = Form(None),
    status: Optional[str] = Form(None),
    images: List[UploadFile] = File(None),
    authorization: str = Header(None)
):
    get_user_from_token(authorization)
    if ticket_id not in tickets:
        raise HTTPException(status_code=404, detail="Ticket not found")
    ticket = tickets[ticket_id]
    changes = []
    if description is not None and description != ticket["description"]:
        changes.append(f"description: '{ticket['description']}' -> '{description}'")
        ticket["description"] = description
    if priority is not None and priority != ticket["priority"]:
        changes.append(f"priority: '{ticket['priority']}' -> '{priority}'")
        ticket["priority"] = priority
    if assigned_worker is not None and assigned_worker != ticket["assigned_worker"]:
        changes.append(f"assigned_worker: '{ticket['assigned_worker']}' -> '{assigned_worker}'")
        ticket["assigned_worker"] = assigned_worker
    if status is not None and status != ticket["status"]:
        changes.append(f"status: '{ticket['status']}' -> '{status}'")
        ticket["status"] = status
    if images:
        for img in images:
            file_path = os.path.join(uploads_dir, f"{ticket_id}_{img.filename}")
            with open(file_path, "wb") as buffer:
                shutil.copyfileobj(img.file, buffer)
            ticket["images"].append(file_path)
            changes.append(f"image added: {img.filename}")
    if changes:
        ticket["history"].append({
            "action": "updated",
            "changes": changes,
            "timestamp": datetime.now().isoformat()
        })
    return ticket

