from pydantic import BaseModel
from typing import Optional
import secrets
import uvicorn

app = FastAPI()

users = {}
tokens = {}
assignments = {}
submissions = {}
next_user_id = 1
next_assign_id = 1
next_sub_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class AssignmentCreate(BaseModel):
    title: str
    max_score: float

class SubmissionCreate(BaseModel):
    assignment_id: int
    student_name: str
    score: float
    feedback: Optional[str] = ""

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    token = secrets.token_hex(16)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/assignments")
def create_assignment(assignment: AssignmentCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_assign_id
    assign_id = next_assign_id
    next_assign_id += 1
    assignments[assign_id] = {
        "id": assign_id,
        "title": assignment.title,
        "max_score": assignment.max_score,
        "created_by": user_id
    }
    return assignments[assign_id]

@app.get("/assignments/{assignment_id}")
def get_assignment(assignment_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if assignment_id not in assignments:
        raise HTTPException(status_code=404, detail="Assignment not found")
    return assignments[assignment_id]

@app.post("/submissions")
def create_submission(submission: SubmissionCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if submission.assignment_id not in assignments:
        raise HTTPException(status_code=404, detail="Assignment not found")
    assign = assignments[submission.assignment_id]
    if submission.score > assign["max_score"]:
        raise HTTPException(status_code=400, detail="Score exceeds max score")
    global next_sub_id
    sub_id = next_sub_id
    next_sub_id += 1
    submissions[sub_id] = {
        "id": sub_id,
        "assignment_id": submission.assignment_id,
        "student_name": submission.student_name,
        "score": submission.score,
        "feedback": submission.feedback,
        "graded_by": user_id
    }
