from pydantic import BaseModel
from typing import Optional
import uuid

app = FastAPI()

users = {}
tokens = {}
lists = {}
list_items = {}
list_id_counter = 0
item_id_counter = 0

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ListCreateRequest(BaseModel):
    name: str

class ListItemCreateRequest(BaseModel):
    name: str
    quantity: int = 1
    store_section: str = ""

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = req.password
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if users.get(req.username) != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = req.username
    return {"token": token}

@app.post("/lists")
def create_list(req: ListCreateRequest, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global list_id_counter
    list_id_counter += 1
    list_id = list_id_counter
    lists[list_id] = {"id": list_id, "name": req.name, "owner": user_id, "items": []}
    return lists[list_id]

@app.get("/lists/{list_id}")
def get_list(list_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    lst = lists.get(list_id)
    if not lst:
        raise HTTPException(status_code=404, detail="List not found")
    return lst

@app.post("/lists/{list_id}/items")
def add_item(list_id: int, req: ListItemCreateRequest, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    lst = lists.get(list_id)
    if not lst:
        raise HTTPException(status_code=404, detail="List not found")
    global item_id_counter
    item_id_counter += 1
    item = {
        "id": item_id_counter,
        "name": req.name,
        "quantity": req.quantity,
        "store_section": req.store_section,
        "purchased": False,
        "added_by": user_id
    }
    lst["items"].append(item)
    return item

@app.patch("/lists/{list_id}/items/{item_id}/purchase")
def mark_purchased(list_id: int, item_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    lst = lists.get(list_id)
    if not lst:
        raise HTTPException(status_code=404, detail="List not found")
    for item in lst["items"]:
        if item["id"] == item_id:
            item["purchased"] = True
            return item
    raise HTTPException(status_code=404, detail="Item not found")

