from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
from datetime import date
import secrets
import time

app = FastAPI()

users = {}
tokens = {}
trips = {}
trip_id_counter = 1
change_logs = []

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TripCreate(BaseModel):
    destination: str
    start_date: date
    end_date: date
    budget: float
    traveler_names: List[str]
    lodging_tier: str

class TripUpdate(BaseModel):
    destination: Optional[str] = None
    start_date: Optional[date] = None
    end_date: Optional[date] = None
    budget: Optional[float] = None
    traveler_names: Optional[List[str]] = None
    lodging_tier: Optional[str] = None

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = len(users) + 1
    users[req.username] = {"id": user_id, "password": req.password, "username": req.username}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = user["id"]
    return {"token": token}

@app.post("/trips")
def create_trip(trip: TripCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global trip_id_counter
    trip_id = trip_id_counter
    trip_id_counter += 1
    trip_data = trip.dict()
    trip_data["id"] = trip_id
    trip_data["user_id"] = user_id
    trips[trip_id] = trip_data
    return trip_data

@app.get("/trips/{trip_id}")
def get_trip(trip_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    return trip

@app.patch("/trips/{trip_id}")
def update_trip(trip_id: int, update: TripUpdate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if trip["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your trip")

    changes = {}
    for field, value in update.dict(exclude_unset=True).items():
        old_value = trip.get(field)
        if old_value != value:
            changes[field] = {"old": old_value, "new": value}
            trip[field] = value

    if changes:
        change_logs.append({
            "trip_id": trip_id,
            "timestamp": time.time(),
            "changes": changes,
            "user_id": user_id
        })

    return trip

@app.get("/trips/{trip_id}/change-logs")
def get_trip_change_logs(trip_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if trip["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your trip")
    return [log for log in change_logs if log["trip_id"] == trip_id]

