    target_metric: Optional[str] = None
    deadline: Optional[str] = None
    coach_assignment: Optional[str] = None
    member_tier_benefits: Optional[str] = None

def get_user_id_from_token(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = len(users) + 1
    users[req.username] = {"id": user_id, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[users[req.username]["id"]] = token
    return {"token": token}

