    get_user_id_from_token(authorization)
    if goal_id not in goals:
        raise HTTPException(status_code=404, detail="Goal not found")
    return goals[goal_id]

@app.post("/goals")
def create_goal(goal: Goal, authorization: str = Header(...)):
    get_user_id_from_token(authorization)
    global goal_id_counter
    new_goal = goal.dict()
    new_goal["id"] = goal_id_counter
    goals[goal_id_counter] = new_goal
    goal_id_counter += 1
    return new_goal

@app.put("/goals/{goal_id}")
def update_goal(goal_id: int, goal_update: GoalUpdate, authorization: str = Header(...)):
    get_user_id_from_token(authorization)
    if goal_id not in goals:
        raise HTTPException(status_code=404, detail="Goal not found")
    existing = goals[goal_id]
    update_data = goal_update.dict(exclude_unset=True)
    existing.update(update_data)
    goals[goal_id] = existing
    return existing

