from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List, Dict
import secrets
import datetime

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
profiles = {}
profile_history = {}
next_user_id = 1
next_profile_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ProfileUpdate(BaseModel):
    username: Optional[str] = None
    avatar: Optional[str] = None
    gaming_preferences: Optional[Dict[str, str]] = None
    skill_tier: Optional[str] = None
    is_admin: Optional[bool] = None

class ProfileCreate(BaseModel):
    username: str
    avatar: Optional[str] = None
    gaming_preferences: Optional[Dict[str, str]] = None
    skill_tier: Optional[str] = None
    is_admin: Optional[bool] = False

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    token = secrets.token_hex(16)
    users[user_id] = {"username": req.username, "password": req.password}
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/profiles")
def create_profile(profile: ProfileCreate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    global next_profile_id
    profile_id = next_profile_id
    next_profile_id += 1
    profile_data = {
        "id": profile_id,
        "user_id": current_user,
        "username": profile.username,
        "avatar": profile.avatar,
        "gaming_preferences": profile.gaming_preferences or {},
        "skill_tier": profile.skill_tier,
        "is_admin": profile.is_admin,
    }
    profiles[profile_id] = profile_data
    profile_history[profile_id] = []
    return profile_data

@app.get("/profiles/{profile_id}")
def get_profile(profile_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if profile_id not in profiles:
        raise HTTPException(status_code=404, detail="Profile not found")
    profile = profiles[profile_id]
    if profile["user_id"] != current_user:
        raise HTTPException(status_code=403, detail="Not your profile")
    return profile

@app.patch("/profiles/{profile_id}")
def update_profile(profile_id: int, update: ProfileUpdate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if profile_id not in profiles:
        raise HTTPException(status_code=404, detail="Profile not found")

    profile = profiles[profile_id]

    if profile["user_id"] != current_user:
        raise HTTPException(status_code=403, detail="Not your profile")

    changes = {}
    if update.username is not None:
        changes["username"] = {"old": profile["username"], "new": update.username}
        profile["username"] = update.username
    if update.avatar is not None:
        changes["avatar"] = {"old": profile["avatar"], "new": update.avatar}
        profile["avatar"] = update.avatar
    if update.gaming_preferences is not None:
        changes["gaming_preferences"] = {"old": profile["gaming_preferences"], "new": update.gaming_preferences}
        profile["gaming_preferences"] = update.gaming_preferences
    if update.skill_tier is not None:
        changes["skill_tier"] = {"old": profile["skill_tier"], "new": update.skill_tier}
        profile["skill_tier"] = update.skill_tier
    if update.is_admin is not None:
        if current_user not in [p["user_id"] for p in profiles.values() if p.get("is_admin")]:
            raise HTTPException(status_code=403, detail="Only admins can change admin status")
        changes["is_admin"] = {"old": profile.get("is_admin"), "new": update.is_admin}
        profile["is_admin"] = update.is_admin

    if changes:
        profile_history[profile_id].append({
            "timestamp": datetime.datetime.now().isoformat(),
            "changed_by": current_user,
            "changes": changes
        })

    return profile

