from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict, List
import uuid

app = FastAPI()

users = {}
tokens = {}
projects = {}
project_settings = {}
next_user_id = 1
next_project_id = 1
next_setting_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreateProjectRequest(BaseModel):
    name: str
    description: Optional[str] = ""

class UpdateProjectSettingsRequest(BaseModel):
    name: Optional[str] = None
    description: Optional[str] = None
    deadline: Optional[str] = None
    members: Optional[Dict[str, str]] = None

def get_user_id_from_token(authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/projects/{project_id}")
def get_project(project_id: int, authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    return projects[project_id]

@app.post("/projects")
def create_project(req: CreateProjectRequest, authorization: str = Header(...)):
    global next_project_id
    user_id = get_user_id_from_token(authorization)
    project_id = next_project_id
    next_project_id += 1
    projects[project_id] = {"id": project_id, "name": req.name, "description": req.description, "owner_id": user_id}
    return projects[project_id]

@app.put("/projects/{project_id}/settings")
def update_project_settings(project_id: int, req: UpdateProjectSettingsRequest, authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    if project_id not in project_settings:
        project_settings[project_id] = {"members": {}}
    settings = project_settings[project_id]
    if req.name is not None:
        projects[project_id]["name"] = req.name
    if req.description is not None:
        projects[project_id]["description"] = req.description
    if req.deadline is not None:
        settings["deadline"] = req.deadline
    if req.members is not None:
        for member_id, role in req.members.items():
            if role not in ["manager", "admin", "member"]:
                raise HTTPException(status_code=400, detail=f"Invalid role: {role}")
            settings["members"][member_id] = role
    project_settings[project_id] = settings
    return {
        "project": projects[project_id],
