from pydantic import BaseModel
from typing import Optional, List
import secrets
import datetime

app = FastAPI()

users = {}
tokens = {}
courses = {}
modules = {}
progress = {}
course_id_counter = 1
module_id_counter = 1
progress_id_counter = 1
user_id_counter = 1

class UserCreate(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class Course(BaseModel):
    title: str
    syllabus: str
    instructor: str
    pricing: float
    enrollment_cap: int

class Module(BaseModel):
    course_id: int
    title: str
    content: str
    order: int

class Progress(BaseModel):
    student_id: int
    course_id: int
    module_id: int
    completed: bool = False

def get_current_user(token: str = Header(...)):
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(user: UserCreate):
    global user_id_counter
    if user.username in [u['username'] for u in users.values()]:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": user.username, "password": user.password}
    return {"id": user_id, "username": user.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u['username'] == req.username and u['password'] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/courses")
def create_course(course: Course, user_id: int = Header(default=None)):
    global course_id_counter
    course_id = course_id_counter
    course_id_counter += 1
    courses[course_id] = {
        "id": course_id,
        "title": course.title,
        "syllabus": course.syllabus,
        "instructor": course.instructor,
        "pricing": course.pricing,
        "enrollment_cap": course.enrollment_cap,
        "created_by": user_id
    }
    return courses[course_id]

@app.get("/courses/{course_id}")
def get_course(course_id: int):
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    return courses[course_id]

@app.put("/courses/{course_id}")
def update_course(course_id: int, course: Course, token: str = Header(...)):
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    user_id = get_current_user(token)
    if courses[course_id].get("created_by") != user_id:
        raise HTTPException(status_code=403, detail="Not authorized to modify this course")
    courses[course_id]["syllabus"] = course.syllabus
    courses[course_id]["instructor"] = course.instructor
    courses[course_id]["pricing"] = course.pricing
    courses[course_id]["enrollment_cap"] = course.enrollment_cap
    return courses[course_id]

