    if user["role"] != "instructor":
        raise HTTPException(status_code=403, detail="Only instructors can set grades")
    if enrollment_id not in enrollments:
        raise HTTPException(status_code=404, detail="Enrollment not found")
    enrollments[enrollment_id]["grade"] = grade
    return enrollments[enrollment_id]

@app.get("/courses/{course_id}/enrollments")
def get_enrollments_by_course(course_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    result = []
    for e in enrollments.values():
        if e["course_id"] == course_id:
