class StockUpdate(BaseModel):
    sku: str
    quantity_change: int

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(user: UserCreate):
    global user_id_counter
    if user.username in [u["username"] for u in users.values()]:
        raise HTTPException(status_code=400, detail="Username taken")
    uid = user_id_counter
    users[uid] = {"id": uid, "username": user.username, "password": user.password}
    user_id_counter += 1
    return {"id": uid, "username": user.username}

@app.post("/login")
def login(login_data: UserLogin):
    for uid, u in users.items():
        if u["username"] == login_data.username and u["password"] == login_data.password:
            token = secrets.token_hex(32)
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/inventory/{id}")
def get_inventory_item(id: int, authorization: str = Header(None)):
    uid = get_current_user(authorization)
    if id not in inventory:
        raise HTTPException(status_code=404, detail="Not found")
    # Check ownership: only owner can access their items
    if inventory[id].get("owner_id") != uid:
        raise HTTPException(status_code=403, detail="Access denied")
    return inventory[id]

@app.post("/inventory")
def create_inventory(item: InventoryCreate, authorization: str = Header(None)):
    global inventory_id_counter
    uid = get_current_user(authorization)
    new_id = inventory_id_counter
    inventory[new_id] = {
        "id": new_id,
        "sku": item.sku,
        "quantity_on_hand": item.quantity_on_hand,
        "reorder_threshold": item.reorder_threshold,
        "supplier_name": item.supplier_name,
        "owner_id": uid  # Track who owns this inventory item
    }
    inventory_id_counter += 1
    return inventory[new_id]

@app.get("/inventory")
def get_all_inventory(authorization: str = Header(None)):
    uid = get_current_user(authorization)
    # Return only items owned by current user
    return [item for item in inventory.values() if item.get("owner_id") == uid]

@app.post("/stock-update")
def stock_update(update: StockUpdate, authorization: str = Header(None)):
    uid = get_current_user(authorization)
    for item_id, item in inventory.items():
        if item["sku"] == update.sku:
            # Ensure user owns the item before allowing update
            if item.get("owner_id") != uid:
                raise HTTPException(status_code=403, detail="Access denied")
