    current_user = get_current_user(authorization)
    global appointment_id_counter
    appointment_id_counter += 1
    appt_data = appt.dict()
    appt_data["id"] = appointment_id_counter
    appt_data["created_by"] = current_user
    appt_data["created_at"] = datetime.now().isoformat()
    appointments[appointment_id_counter] = appt_data
    attendance_history[appointment_id_counter] = []
    return appt_data

