import random
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List

app = FastAPI()

users = {}
next_user_id = 1
tokens = {}
matches = {}
next_match_id = 1
leaderboard = {}
player_history = {}

def generate_token():
    return ''.join(random.choices('abcdefghijklmnopqrstuvwxyz0123456789', k=32))

def get_user_from_token(authorization: str = Header(None)):
    if not authorization or not authorization.startswith('Bearer '):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str

class LoginRequest(BaseModel):
    username: str

class MatchResultRequest(BaseModel):
    team1: List[str]
    team2: List[str]
    winner: str

class UserCreate(BaseModel):
    username: str

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u['username'] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        'id': user_id,
        'username': req.username,
        'elo': 1000,
        'wins': 0,
        'losses': 0
    }
    token = generate_token()
    tokens[token] = user_id
    return {'token': token, 'user_id': user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u['username'] == req.username:
            token = generate_token()
            tokens[token] = uid
            return {'token': token, 'user_id': uid}
    raise HTTPException(status_code=404, detail="User not found")

@app.get("/leaderboard")
def get_leaderboard(authorization: str = Header(None)):
    get_user_from_token(authorization)
    sorted_users = sorted(users.values(), key=lambda u: u['elo'], reverse=True)[:100]
    result = []
    for rank, u in enumerate(sorted_users, 1):
        total = u['wins'] + u['losses']
        winrate = u['wins'] / total if total > 0 else 0.0
        result.append({
            'rank': rank,
            'username': u['username'],
            'winrate': round(winrate, 3)
        })
    return result

@app.post("/match/result")
def post_match_result(req: MatchResultRequest, authorization: str = Header(None)):
    get_user_from_token(authorization)
    global next_match_id

    all_players = req.team1 + req.team2
    player_ids = []
    for p in all_players:
        found = None
        for uid, u in users.items():
            if u['username'] == p:
                found = uid
                break
        if not found:
            raise HTTPException(status_code=404, detail=f"Player {p} not found")
        player_ids.append(found)

    team1_ids = player_ids[:len(req.team1)]
    team2_ids = player_ids[len(req.team1):]

    winner_team = req.winner
    if winner_team not in ['team1', 'team2']:
        raise HTTPException(status_code=400, detail="winner must be team1 or team2")

    k_factor = 32
    avg_elo1 = sum(users[uid]['elo'] for uid in team1_ids) / len(team1_ids)
    avg_elo2 = sum(users[uid]['elo'] for uid in team2_ids) / len(team2_ids)
    expected1 = 1 / (1 + 10 ** ((avg_elo2 - avg_elo1) / 400))
    expected2 = 1 - expected1

    if winner_team == 'team1':
        score1, score2 = 1, 0
    else:
        score1, score2 = 0, 1

    for uid in team1_ids:
        users[uid]['elo'] += int(k_factor * (score1 - expected1))
        if score1 == 1:
            users[uid]['wins'] += 1
        else:
            users[uid]['losses'] += 1
    for uid in team2_ids:
        users[uid]['elo'] += int(k_factor * (score2 - expected2))
        if score2 == 1:
            users[uid]['wins'] += 1
        else:
            users[uid]['losses'] += 1

    match_id = next_match_id
    next_match_id += 1
    matches[match_id] = {
        'id': match_id,
        'team1': req.team1,
        'team2': req.team2,
        'winner': winner_team
    }

    for p in all_players:
        if p not in player_history:
            player_history[p] = []
        player_history[p].append(match_id)

    return {'match_id': match_id}

@app.get("/stats/{player}")
def get_player_stats(player: str, authorization: str = Header(None)):
    get_user_from_token(authorization)
    found_user = None
    for uid, u in users.items():
        if u['username'] == player:
            found_user = u
            break
    if not found_user:
        raise HTTPException(status_code=404, detail="Player not found")

    history = player_history.get(player, [])
    match_details = []
    for mid in history:
        m = matches[mid]
        match_details.append({
            'match_id': mid,
            'team1': m['team1'],
            'team2': m['team2'],
            'winner': m['winner']
        })

    return {
        'username': player,
        'elo': found_user['elo'],
        'wins': found_user['wins'],
        'losses': found_user['losses'],
        'match_history': match_details
    }

@app.get("/user/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    u = users.get(user_id)
    if not u:
        raise HTTPException(status_code=404, detail="User not found")
    return u

@app.post("/user")
def create_user(req: UserCreate, authorization: str = Header(None)):
    get_user_from_token(authorization)
    global next_user_id
    for u in users.values():
        if u['username'] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        'id': user_id,
        'username': req.username,
        'elo': 1000,
        'wins': 0,
        'losses': 0
    }
    return users[user_id]

