from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict
import uuid
import time

app = FastAPI()

users: Dict[int, dict] = {}
tokens: Dict[str, int] = {}
inventory: Dict[int, dict] = {}
next_user_id = 1
next_inventory_id = 1

def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class InventoryItemCreate(BaseModel):
    sku: str
    quantity_on_hand: int
    reorder_threshold: int

class InventoryAdjustRequest(BaseModel):
    sku: str
    quantity_change: int

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/inventory")
def list_inventory(authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    return [{"sku": v["sku"], "quantity_on_hand": v["quantity_on_hand"], "reorder_threshold": v["reorder_threshold"]} for v in inventory.values()]

@app.post("/inventory/adjust")
def adjust_inventory(req: InventoryAdjustRequest, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    for item in inventory.values():
        if item["sku"] == req.sku:
            item["quantity_on_hand"] += req.quantity_change
            if item["quantity_on_hand"] < 0:
                item["quantity_on_hand"] = 0
            return {"sku": req.sku, "new_quantity": item["quantity_on_hand"]}
    raise HTTPException(status_code=404, detail="SKU not found")

@app.get("/alerts")
def get_alerts(authorization: str = Header(None)):
