from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import List, Optional, Dict
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
expenses = {}
groups = {}
settlements = {}
group_members = {}
next_user_id = 1
next_expense_id = 1
next_group_id = 1
next_settlement_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ExpenseCreate(BaseModel):
    group_id: int
    payer_id: int
    amount: float
    split_members: List[int]

class SettlementCreate(BaseModel):
    group_id: int
    from_user_id: int
    to_user_id: int
    amount: float

class GroupCreate(BaseModel):
    name: str
    member_ids: List[int]

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": hashlib.sha256(req.password.encode()).hexdigest()}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == hashlib.sha256(req.password.encode()).hexdigest():
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/groups")
def create_group(group: GroupCreate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    global next_group_id
    group_id = next_group_id
    next_group_id += 1
    groups[group_id] = {"id": group_id, "name": group.name, "created_by": current_user}
    group_members[group_id] = group.member_ids
    return {"group_id": group_id}

@app.get("/groups/{group_id}")
def get_group(group_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    return groups[group_id]

@app.post("/expenses")
def create_expense(expense: ExpenseCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_expense_id
    if expense.group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    if expense.payer_id not in group_members[expense.group_id]:
        raise HTTPException(status_code=400, detail="Payer not in group")
    for mid in expense.split_members:
        if mid not in group_members[expense.group_id]:
            raise HTTPException(status_code=400, detail=f"Member {mid} not in group")
    expense_id = next_expense_id
    next_expense_id += 1
    expenses[expense_id] = {
        "id": expense_id,
        "group_id": expense.group_id,
        "payer_id": expense.payer_id,
        "amount": expense.amount,
        "split_members": expense.split_members
    }
    return {"expense_id": expense_id}

@app.get("/expenses/{expense_id}")
def get_expense(expense_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if expense_id not in expenses:
        raise HTTPException(status_code=404, detail="Expense not found")
    return expenses[expense_id]

@app.get("/groups/{group_id}/balances")
def get_balances(group_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    members = group_members[group_id]
    balance = {uid: 0.0 for uid in members}
    for eid, exp in expenses.items():
        if exp["group_id"] != group_id:
            continue
        share = exp["amount"] / len(exp["split_members"])
        balance[exp["payer_id"]] += exp["amount"]
        for mid in exp["split_members"]:
            balance[mid] -= share
    for s in settlements.values():
        if s["group_id"] != group_id:
            continue
        balance[s["from_user_id"]] += s["amount"]
        balance[s["to_user_id"]] -= s["amount"]
    debts = []
    for uid, bal in balance.items():
        if bal > 0:
            for uid2, bal2 in balance.items():
                if bal2 < 0 and abs(bal2) > 0.01:
                    amount = min(bal, abs(bal2))
                    if amount > 0.01:
                        debts.append({"from": uid2, "to": uid, "amount": round(amount, 2)})
                        bal -= amount
                        balance[uid2] += amount
    return {"group_id": group_id, "debts": debts}

@app.post("/settlements")
def create_settlement(settlement: SettlementCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_settlement_id
    if settlement.group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    if settlement.from_user_id not in group_members[settlement.group_id] or settlement.to_user_id not in group_members[settlement.group_id]:
        raise HTTPException(status_code=400, detail="Users not in group")
    settlement_id = next_settlement_id
    next_settlement_id += 1
    settlements[settlement_id] = {
        "id": settlement_id,
        "group_id": settlement.group_id,
        "from_user_id": settlement.from_user_id,
        "to_user_id": settlement.to_user_id,
