import hashlib
import secrets
import json
from typing import Optional, List
from fastapi import FastAPI, HTTPException, Header, Body
from pydantic import BaseModel
import httpx
import pdfplumber
from io import BytesIO
import re

app = FastAPI()

users = {}
tokens = {}
resumes = {}
skills_counter = {}
current_user_id = 1
current_resume_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class UploadRequest(BaseModel):
    pdf_url: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

def parse_resume_from_url(url: str) -> dict:
    response = httpx.get(url, timeout=30)
    response.raise_for_status()

    with pdfplumber.open(BytesIO(response.content)) as pdf:
        text = ""
        for page in pdf.pages:
            text += page.extract_text() or ""

    name = ""
    email = ""
    skills = []
    work_history = []

    email_match = re.search(r'[\w\.-]+@[\w\.-]+\.\w+', text)
    if email_match:
        email = email_match.group()

    lines = text.split('\n')
    if lines:
        name = lines[0].strip()

    skill_keywords = ['python', 'java', 'javascript', 'react', 'node', 'sql', 'aws', 'docker', 'kubernetes', 'git', 'html', 'css', 'typescript', 'c++', 'c#', 'ruby', 'php', 'swift', 'kotlin', 'go', 'rust', 'scala', 'perl', 'r', 'matlab', 'angular', 'vue', 'django', 'flask', 'spring', 'express', 'mongodb', 'postgresql', 'mysql', 'redis', 'kafka', 'spark', 'hadoop', 'tensorflow', 'pytorch', 'machine learning', 'deep learning', 'nlp', 'computer vision', 'data analysis', 'data science', 'devops', 'ci/cd', 'terraform', 'ansible', 'jenkins']

    text_lower = text.lower()
    for skill in skill_keywords:
        if skill in text_lower:
            skills.append(skill)

    work_pattern = re.compile(r'(\d{4})\s*[-–to]+\s*(\d{4}|present)', re.IGNORECASE)
    work_matches = work_pattern.findall(text)

    for match in work_matches:
        company = ""
        title = ""

        match_start = text.find(match[0])
        if match_start > 0:
            before_text = text[max(0, match_start-200):match_start]
            lines_before = before_text.split('\n')
            if len(lines_before) >= 2:
                title = lines_before[-2].strip()
                company = lines_before[-1].strip()

        work_history.append({
            "company": company,
            "title": title,
            "start_year": match[0],
            "end_year": match[1]
        })

    return {
        "name": name,
        "email": email,
        "skills": list(set(skills)),
        "work_history": work_history
    }

@app.post("/signup")
def signup(req: SignupRequest):
    global current_user_id
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = current_user_id
    users[req.username] = {"id": user_id, "password_hash": hash_password(req.password)}
    current_user_id += 1
    token = generate_token()
    tokens[token] = user_id
    return {"id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password_hash"] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = user["id"]
    return {"token": token}

@app.post("/resumes/upload")
def upload_resume(req: UploadRequest, authorization: Optional[str] = Header(None)):
    global current_resume_id
    user_id = get_current_user(authorization)

    try:
        parsed = parse_resume_from_url(req.pdf_url)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to parse PDF: {str(e)}")

    resume_id = current_resume_id
    resumes[resume_id] = {
        "id": resume_id,
        "user_id": user_id,
        "name": parsed["name"],
        "email": parsed["email"],
        "skills": parsed["skills"],
        "work_history": parsed["work_history"]
    }
    current_resume_id += 1

    for skill in parsed["skills"]:
        skills_counter[skill] = skills_counter.get(skill, 0) + 1

    return resumes[resume_id]

@app.get("/resumes/{resume_id}")
def get_resume(resume_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    resume = resumes.get(resume_id)
    if not resume:
        raise HTTPException(status_code=404, detail="Resume not found")
    return resume

@app.get("/skills/trending")
def get_trending_skills(authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    sorted_skills = sorted(skills_counter.items(), key=lambda x: x[1], reverse=True)
    return {"trending_skills": [{"skill": s, "count": c} for s, c in sorted_skills]}

