        "username": "testuser",
        "password": "testpass"
    })
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if token is None:
        return False

    headers = {"Authorization": f"Bearer {token}"}

    # Create a job
    job_resp = session.post(f"{BASE_URL}/jobs", json={
        "title": "Software Engineer",
        "company": "Tech Corp",
        "salary_range": "100k-150k",
        "remote_level": "hybrid"
    }, headers=headers)
    if job_resp.status_code != 200:
        return False
    job_id = job_resp.json().get("id")
    if job_id is None:
        return False

    # Fetch the created job
    get_job_resp = session.get(f"{BASE_URL}/jobs/{job_id}", headers=headers)
    if get_job_resp.status_code != 200:
        return False
    fetched_job = get_job_resp.json()
    if fetched_job.get("title") != "Software Engineer":
        return False

    # Create an application
    app_resp = session.post(f"{BASE_URL}/applications", json={
        "job_id": job_id,
        "applicant_name": "Test User",
        "cover_letter_snippet": "I am interested"
    }, headers=headers)
    if app_resp.status_code != 200:
        return False
    app_id = app_resp.json().get("id")
    if app_id is None:
        return False

    # Fetch the application
    get_app_resp = session.get(f"{BASE_URL}/applications/{app_id}", headers=headers)
    if get_app_resp.status_code != 200:
        return False
    fetched_app = get_app_resp.json()
    if fetched_app.get("applicant_name") != "Test User":
        return False

    # Fetch all jobs
