    group_members[group_id] = req.member_ids
    group_expenses[group_id] = []
    group_balances[group_id] = {}
    for member_id in req.member_ids:
        group_balances[group_id][member_id] = 0.0
    return {"id": group_id, "name": req.name}

@app.get("/groups/{group_id}")
