    member_ids = group_members[group_id]
    members = []
    for mid in member_ids:
        if mid in users:
            members.append(users[mid]["name"])
        else:
            members.append(f"User {mid}")
    group["members"] = members
    total_expenses = sum(e["amount"] for e in group_expenses[group_id])
