        for mid, bal in balances.items():
            name = users[mid]["name"] if mid in users else f"User {mid}"
            balance_list.append({"user_id": mid, "name": name, "balance": bal})
        g["balances"] = balance_list
        result.append(g)
    return result

@app.post("/expense")
def add_expense(req: AddExpenseRequest, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    if req.group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    if req.paid_by not in group_members[req.group_id]:
        raise HTTPException(status_code=400, detail="Paid by user not in group")
    global next_expense_id
    expense_id = next_expense_id
    next_expense_id += 1
    expense = {
        "id": expense_id,
        "group_id": req.group_id,
        "amount": req.amount,
        "description": req.description,
        "paid_by": req.paid_by
    }
    group_expenses[req.group_id].append(expense)
    member_ids = group_members[req.group_id]
    share = req.amount / len(member_ids)
    for mid in member_ids:
        if mid == req.paid_by:
            group_balances[req.group_id][mid] += (req.amount - share)
        else:
            group_balances[req.group_id][mid] -= share
    return expense

@app.get("/expense/{expense_id}")
def get_expense(expense_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    for gid, expenses in group_expenses.items():
        for e in expenses:
            if e["id"] == expense_id:
                return e
    raise HTTPException(status_code=404, detail="Expense not found")

