    # Fetch the created appointment
    fetch_resp = session.get(f"{BASE_URL}/appointments/{appointment_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    data = fetch_resp.json()
    if data.get("patient_name") != "John Doe":
        return False

    return True

