    get_user_from_token(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    return shipments[shipment_id]

@app.post("/shipments")
def create_shipment(origin: str, destination: str, estimated_delivery: str, authorization: str = Header(None)):
    global shipment_id_counter
    get_user_from_token(authorization)
    shipment_id = shipment_id_counter
    shipment_id_counter += 1
    shipments[shipment_id] = {
        "id": shipment_id,
        "origin": origin,
        "destination": destination,
        "status": "in_transit",
        "estimated_delivery": estimated_delivery,
        "gps_coordinates": None
    }
    return {"id": shipment_id}

@app.get("/shipments/{shipment_id}/track")
def track_shipment(shipment_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    s = shipments[shipment_id]
    if s["gps_coordinates"]:
        return {"gps_coordinates": s["gps_coordinates"]}
    return {"gps_coordinates": None, "message": "GPS coordinates not available"}

