from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import random
import string

app = FastAPI()

users = {}
tokens = {}
profiles = {}
swipes = {}
next_user_id = 1
next_profile_id = 1
next_swipe_id = 1
next_token_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    for uid, tok in tokens.items():
        if tok == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(username: str, password: str, age: int, bio: str, interests: str):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {
        "id": uid,
        "username": username,
        "password": password,
        "age": age,
        "bio": bio,
        "interests": interests.split(",")
    }
    token = generate_token()
    tokens[uid] = token
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = generate_token()
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/profiles")
def get_profiles(authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    current_user_data = users[current_user]
    current_interests = set(current_user_data["interests"])

    result = []
    for pid, p in profiles.items():
        if p["user_id"] == current_user:
            continue
        shared = len(current_interests & set(p["interests"]))
        total = len(current_interests | set(p["interests"]))
        compatibility = round(shared / total * 100, 2) if total > 0 else 0
        result.append({
            "id": pid,
            "age": p["age"],
            "bio": p["bio"],
            "interests": p["interests"],
            "compatibility_score": compatibility
        })
    return result

@app.post("/profiles/swipe")
def swipe(profile_id: int, direction: str, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if profile_id not in profiles:
        raise HTTPException(status_code=404, detail="Profile not found")
    if direction not in ("like", "pass"):
        raise HTTPException(status_code=400, detail="Direction must be 'like' or 'pass'")

    global next_swipe_id
    sid = next_swipe_id
    next_swipe_id += 1
    swipes[sid] = {
        "id": sid,
        "user_id": current_user,
        "profile_id": profile_id,
        "direction": direction
    }

    match = False
    if direction == "like":
        for s in swipes.values():
            if s["user_id"] == profiles[profile_id]["user_id"] and s["profile_id"] == current_user and s["direction"] == "like":
                match = True
                break

