            continue
        shared = len(current_interests & set(p["interests"]))
        total = len(current_interests | set(p["interests"]))
        compatibility = round(shared / total * 100, 2) if total > 0 else 0
        result.append({
            "id": pid,
            "age": p["age"],
            "bio": p["bio"],
