        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

def reset_weekly():
    global weekly_last_reset
    now = datetime.now()
    if weekly_last_reset.weekday() != 0 or weekly_last_reset.date() != now.date():
        if now.weekday() == 0:
            weekly_scores.clear()
            weekly_last_reset = now

@app.post("/signup")
def signup(username: str, password: str):
    user_id = len(users) + 1
    users[user_id] = {"username": username, "password": password}
