    user_id = get_current_user(authorization)
    scores[user_id]["score"] += score
    scores[user_id]["games_played"] += 1
    reset_weekly()
    if user_id not in weekly_scores:
        weekly_scores[user_id] = {"score": 0, "games_played": 0}
    weekly_scores[user_id]["score"] += score
    weekly_scores[user_id]["games_played"] += 1
