from fastapi import FastAPI, HTTPException, Header
from typing import Optional
from datetime import datetime
import secrets

app = FastAPI()

users = {}
projects = {}
tasks = {}
tokens = {}
user_ids = 1
project_ids = 1
task_ids = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_ids
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username taken")
    user_id = user_ids
    users[user_id] = {"id": user_id, "username": username, "password": password}
    user_ids += 1
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/boards")
def get_boards(authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    result = []
    for pid, p in projects.items():
        task_count = 0
        completed_count = 0
        last_activity = None
        for t in tasks.values():
            if t["project_id"] == pid:
                task_count += 1
                if t.get("completed"):
                    completed_count += 1
                if last_activity is None or t["created_at"] > last_activity:
                    last_activity = t["created_at"]
        result.append({
            "id": pid,
            "name": p["name"],
            "task_count": task_count,
            "completed_count": completed_count,
            "last_activity": last_activity
        })
    return result

@app.post("/boards/{board_id}/tasks")
def add_task(board_id: int, assignee: str, deadline: str, authorization: Optional[str] = Header(None)):
    global task_ids
    current_user = get_current_user(authorization)
    if board_id not in projects:
        raise HTTPException(status_code=404, detail="Board not found")
    task = {
        "id": task_ids,
        "project_id": board_id,
        "assignee": assignee,
        "deadline": deadline,
        "completed": False,
        "created_at": datetime.utcnow().isoformat()
    }
    tasks[task_ids] = task
    task_ids += 1
    return task

@app.get("/{resource}/{id}")
def get_resource(resource: str, id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    store = {"users": users, "projects": projects, "tasks": tasks}
    if resource not in store:
        raise HTTPException(status_code=404, detail="Resource not found")
    item = store[resource].get(id)
    if not item:
        raise HTTPException(status_code=404, detail="Item not found")
    return item

@app.post("/{resource}")
def create_resource(resource: str, data: dict, authorization: Optional[str] = Header(None)):
    global project_ids
    current_user = get_current_user(authorization)
    if resource == "projects":
        if "name" not in data:
            raise HTTPException(status_code=400, detail="Name required")
        project = {"id": project_ids, "name": data["name"], "owner": current_user}
        projects[project_ids] = project
        project_ids += 1
        return project
    elif resource == "tasks":
        global task_ids
        if "project_id" not in data or "assignee" not in data or "deadline" not in data:
            raise HTTPException(status_code=400, detail="Missing fields")
        if data["project_id"] not in projects:
            raise HTTPException(status_code=404, detail="Project not found")
        task = {
            "id": task_ids,
            "project_id": data["project_id"],
            "assignee": data["assignee"],
            "deadline": data["deadline"],
            "completed": data.get("completed", False),
            "created_at": datetime.utcnow().isoformat()
        }
        tasks[task_ids] = task
        task_ids += 1
        return task
    else:
        raise HTTPException(status_code=400, detail="Unsupported resource")

