from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import datetime

app = FastAPI()

users = {}
tokens = {}
goals = {}
progress_logs = {}
goal_id_counter = 1
progress_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class GoalCreate(BaseModel):
    target_value: float
    deadline: str
    title: str = ""

class ProgressLog(BaseModel):
    goal_id: int
    measurement: float

def get_user_id_from_token(authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = len(users) + 1
    users[req.username] = {"id": user_id, "password": req.password, "username": req.username}
    token = secrets.token_hex(16)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = user["id"]
    return {"user_id": user["id"], "token": token}

@app.get("/goals/{goal_id}")
def get_goal(goal_id: int, authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    goal = goals.get(goal_id)
    if not goal:
        raise HTTPException(status_code=404, detail="Goal not found")
    return goal

@app.get("/goals")
def list_goals(authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    user_goals = [g for g in goals.values() if g["user_id"] == user_id]
    return user_goals

@app.post("/goals")
def create_goal(goal: GoalCreate, authorization: str = Header(...)):
    global goal_id_counter
    user_id = get_user_id_from_token(authorization)
    new_goal = {
        "id": goal_id_counter,
        "user_id": user_id,
        "target_value": goal.target_value,
        "deadline": goal.deadline,
        "title": goal.title,
        "current_progress": 0.0,
        "completion_percentage": 0.0,
        "streak_days": 0,
        "last_logged_date": None
    }
    goals[goal_id_counter] = new_goal
    goal_id_counter += 1
    return new_goal

@app.post("/goals/progress")
def log_progress(progress: ProgressLog, authorization: str = Header(...)):
    global progress_id_counter
    user_id = get_user_id_from_token(authorization)
    goal = goals.get(progress.goal_id)
    if not goal:
        raise HTTPException(status_code=404, detail="Goal not found")

    today = datetime.date.today().isoformat()

    log_entry = {
        "id": progress_id_counter,
        "goal_id": progress.goal_id,
        "measurement": progress.measurement,
        "logged_at": today
    }
    progress_logs[progress_id_counter] = log_entry
    progress_id_counter += 1

    goal["current_progress"] += progress.measurement
    if goal["target_value"] > 0:
        goal["completion_percentage"] = min(100.0, (goal["current_progress"] / goal["target_value"]) * 100)
    else:
        goal["completion_percentage"] = 0.0

    if goal["last_logged_date"] == today:
        pass
    elif goal["last_logged_date"] == (datetime.date.today() - datetime.timedelta(days=1)).isoformat():
        goal["streak_days"] += 1
    else:
        goal["streak_days"] = 1

    goal["last_logged_date"] = today

    return {"message": "Progress logged", "goal": goal}

