from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict, List
import secrets

app = FastAPI()

users: Dict[int, dict] = {}
tokens: Dict[str, int] = {}
next_user_id = 1

warehouses: Dict[int, dict] = {}
next_warehouse_id = 1

stock_items: Dict[int, dict] = {}
next_stock_item_id = 1

purchase_orders: Dict[int, dict] = {}
next_po_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class WarehouseCreate(BaseModel):
    name: str

class StockItemCreate(BaseModel):
    warehouse_id: int
    name: str
    bin_location: str
    quantity: int
    reorder_threshold: int

class RestockRequest(BaseModel):
    warehouse_id: int

def auth_user(authorization: Optional[str] = Header(None)) -> int:
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"username": req.username, "password": req.password}
    token = secrets.token_hex(16)
    tokens[token] = uid
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/warehouse")
def create_warehouse(req: WarehouseCreate, authorization: Optional[str] = Header(None)):
    auth_user(authorization)
    global next_warehouse_id
    wid = next_warehouse_id
    next_warehouse_id += 1
    warehouses[wid] = {"id": wid, "name": req.name}
    return warehouses[wid]

@app.get("/warehouse/{wid}")
def get_warehouse(wid: int, authorization: Optional[str] = Header(None)):
    auth_user(authorization)
    if wid not in warehouses:
        raise HTTPException(status_code=404, detail="Warehouse not found")
    return warehouses[wid]

@app.get("/warehouse/{wid}/stock")
def get_stock(wid: int, authorization: Optional[str] = Header(None)):
    auth_user(authorization)
    if wid not in warehouses:
        raise HTTPException(status_code=404, detail="Warehouse not found")
    items = []
    for sid, item in stock_items.items():
        if item["warehouse_id"] == wid:
            reorder_alert = item["quantity"] <= item["reorder_threshold"]
            items.append({
                "name": item["name"],
                "bin_location": item["bin_location"],
                "quantity": item["quantity"],
                "reorder_alert": reorder_alert
            })
    return {"warehouse_id": wid, "stock": items}

@app.post("/stock")
def create_stock_item(req: StockItemCreate, authorization: Optional[str] = Header(None)):
    auth_user(authorization)
    global next_stock_item_id
    sid = next_stock_item_id
    next_stock_item_id += 1
    stock_items[sid] = {
        "id": sid,
        "warehouse_id": req.warehouse_id,
        "name": req.name,
        "bin_location": req.bin_location,
        "quantity": req.quantity,
        "reorder_threshold": req.reorder_threshold
    }
    return stock_items[sid]

@app.get("/stock/{sid}")
def get_stock_item(sid: int, authorization: Optional[str] = Header(None)):
    auth_user(authorization)
    if sid not in stock_items:
        raise HTTPException(status_code=404, detail="Stock item not found")
    return stock_items[sid]

@app.post("/warehouse/restock")
def restock_warehouse(req: RestockRequest, authorization: Optional[str] = Header(None)):
    auth_user(authorization)
    wid = req.warehouse_id
    if wid not in warehouses:
        raise HTTPException(status_code=404, detail="Warehouse not found")
    low_stock_items = []
    for sid, item in stock_items.items():
        if item["warehouse_id"] == wid and item["quantity"] <= item["reorder_threshold"]:
            low_stock_items.append(item)
    if not low_stock_items:
        return {"message": "No low stock items", "purchase_order_id": None}
    global next_po_id
    po_id = next_po_id
    next_po_id += 1
    po_items = []
    for item in low_stock_items:
        order_qty = item["reorder_threshold"] * 2 - item["quantity"]
        po_items.append({
            "stock_item_id": item["id"],
            "name": item["name"],
            "order_quantity": order_qty
        })
    purchase_orders[po_id] = {
        "id": po_id,
        "warehouse_id": wid,
        "items": po_items
    }
    return {"message": "Purchase order created", "purchase_order_id": po_id, "items": po_items}

@app.get("/purchase_order/{po_id}")
def get_purchase_order(po_id: int, authorization: Optional[str] = Header(None)):
    auth_user(authorization)
    if po_id not in purchase_orders:
        raise HTTPException(status_code=404, detail="Purchase order not found")
    return purchase_orders[po_id]

