    pid = playlist_id_counter
    playlist_id_counter += 1
    playlists[pid] = {"id": pid, "name": req.name, "user_id": user_id, "created_at": datetime.now().isoformat()}
    playlist_videos[pid] = []
    return playlists[pid]

@app.get("/playlists/{playlist_id}")
