    if not pl:
        raise HTTPException(status_code=404, detail="Playlist not found")
    if pl["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your playlist")
    return {"playlist": pl, "videos": playlist_videos.get(playlist_id, [])}

