    pl = playlists.get(playlist_id)
    if not pl:
        raise HTTPException(status_code=404, detail="Playlist not found")
    videos = playlist_videos.get(playlist_id, [])
    recommendations = []
    for pid, p in playlists.items():
        if pid != playlist_id and p["user_id"] == user_id:
            recommendations.append({"id": pid, "name": p["name"]})
    return {
        "playlist_name": pl["name"],
        "videos": [{"url": v["url"], "resume_timestamp": v["resume_timestamp"]} for v in videos],
