    expires_at = datetime.now() + timedelta(hours=req.expiry_hours)
    playlist_shares[share_id] = {
        "playlist_id": req.playlist_id,
        "expires_at": expires_at.isoformat(),
        "created_by": user_id
    }
    return {"share_link": f"/shared/{share_id}", "expires_at": expires_at.isoformat()}

@app.get("/shared/{share_id}")
def access_shared_playlist(share_id: str):
    share = playlist_shares.get(share_id)
    if not share:
        raise HTTPException(status_code=404, detail="Share link not found")
    if datetime.fromisoformat(share["expires_at"]) < datetime.now():
        raise HTTPException(status_code=410, detail="Share link expired")
    pl = playlists.get(share["playlist_id"])
    if not pl:
        raise HTTPException(status_code=404, detail="Playlist not found")
    videos = playlist_videos.get(share["playlist_id"], [])
    return {
        "playlist_name": pl["name"],
        "videos": [{"url": v["url"], "resume_timestamp": v["resume_timestamp"]} for v in videos]
    }

