    menu = restaurants[restaurant_id]["menu"]
    if dietary:
        diet_list = [d.strip().lower() for d in dietary.split(",")]
        menu = [d for d in menu if any(diet in d["dietary"] for diet in diet_list)]
    menu = sorted(menu, key=lambda x: x["popularity"], reverse=True)
    return {"restaurant_id": restaurant_id, "recommended": menu}

