from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
from datetime import datetime, date, timedelta
import uuid
import math

app = FastAPI()

users = {}
habits = {}
habit_logs = {}
tokens = {}
user_id_counter = 1
habit_id_counter = 1
log_id_counter = 1

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreateHabitRequest(BaseModel):
    name: str
    description: Optional[str] = ""

class LogHabitRequest(BaseModel):
    habit_id: int
    notes: Optional[str] = ""
    mood_rating: Optional[int] = 3

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    uid = user_id_counter
    user_id_counter += 1
    users[uid] = {"id": uid, "username": req.username, "password": req.password}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/habits/{habit_id}")
def get_habit(habit_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    habit = habits.get(habit_id)
    if not habit:
        raise HTTPException(status_code=404, detail="Habit not found")
    return habit

@app.post("/habits")
def create_habit(req: CreateHabitRequest, authorization: str = Header(None)):
    global habit_id_counter
    user_id = get_current_user(authorization)
    hid = habit_id_counter
    habit_id_counter += 1
    habits[hid] = {
        "id": hid,
        "user_id": user_id,
        "name": req.name,
        "description": req.description,
        "created_at": datetime.utcnow().isoformat()
    }
    return habits[hid]

@app.get("/habits/{habit_id}/streak")
def get_streak(habit_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    habit = habits.get(habit_id)
    if not habit:
        raise HTTPException(status_code=404, detail="Habit not found")
    if habit["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your habit")

    logs = [l for l in habit_logs.values() if l["habit_id"] == habit_id]
    logs.sort(key=lambda x: x["logged_date"], reverse=True)

    if not logs:
        return {
            "current_streak": 0,
            "history_graph": "",
            "next_milestone": 1
        }

    today = date.today()
    current_streak = 0
    check_date = today
    log_dates = set()
    for l in logs:
        log_dates.add(l["logged_date"])

    while check_date in log_dates:
        current_streak += 1
        check_date -= timedelta(days=1)

    history = []
    for i in range(30):
        d = today - timedelta(days=i)
        history.append("X" if d in log_dates else ".")

    history_graph = "".join(reversed(history))

    milestones = [1, 3, 7, 14, 21, 30, 60, 90, 180, 365]
    next_milestone = 1
    for m in milestones:
        if current_streak < m:
            next_milestone = m
            break

    return {
        "current_streak": current_streak,
        "history_graph": history_graph,
        "next_milestone": next_milestone
    }

@app.post("/habits/log")
def log_habit(req: LogHabitRequest, authorization: str = Header(None)):
    global log_id_counter
    user_id = get_current_user(authorization)
    habit = habits.get(req.habit_id)
    if not habit:
        raise HTTPException(status_code=404, detail="Habit not found")
    if habit["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your habit")

    lid = log_id_counter
    log_id_counter += 1
    habit_logs[lid] = {
        "id": lid,
        "habit_id": req.habit_id,
        "user_id": user_id,
        "notes": req.notes,
        "mood_rating": req.mood_rating,
        "logged_date": date.today().isoformat(),
        "logged_at": datetime.utcnow().isoformat()
    }
    return habit_logs[lid]

