from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import random
import string
from datetime import datetime, timedelta

app = FastAPI()

users = {}
tokens = {}
artists = {}
shows = {}
artist_shows = {}
show_id_counter = 1
artist_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class UserCreate(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class ArtistCreate(BaseModel):
    name: str
    genre: Optional[str] = None

class ShowCreate(BaseModel):
    artist_id: int
    venue: str
    date: str
    attendance: int
    setlist: List[str]

class PastShowsResponse(BaseModel):
    shows: list

class PredictResponse(BaseModel):
    estimated_next_tour_dates: List[str]

@app.post("/signup")
def signup(user: UserCreate):
    if user.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = len(users) + 1
    users[user.username] = {"id": user_id, "username": user.username, "password": user.password}
    return {"id": user_id, "username": user.username}

@app.post("/login")
def login(user: UserLogin):
    if user.username not in users or users[user.username]["password"] != user.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = user.username
    return {"token": token}

@app.post("/artists")
def create_artist(artist: ArtistCreate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    global artist_id_counter
    artist_id = artist_id_counter
    artist_id_counter += 1
    artists[artist_id] = {"id": artist_id, "name": artist.name, "genre": artist.genre, "shows": []}
    return artists[artist_id]

@app.get("/artists/{artist_id}")
def get_artist(artist_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if artist_id not in artists:
        raise HTTPException(status_code=404, detail="Artist not found")
    return artists[artist_id]

@app.post("/shows")
def create_show(show: ShowCreate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    global show_id_counter
    if show.artist_id not in artists:
        raise HTTPException(status_code=404, detail="Artist not found")
    show_id = show_id_counter
    show_id_counter += 1
    show_data = {
        "id": show_id,
        "artist_id": show.artist_id,
        "venue": show.venue,
        "date": show.date,
        "attendance": show.attendance,
        "setlist": show.setlist
    }
    shows[show_id] = show_data
    artists[show.artist_id]["shows"].append(show_id)
    if show.artist_id not in artist_shows:
        artist_shows[show.artist_id] = []
    artist_shows[show.artist_id].append(show_data)
    return show_data

@app.get("/shows/{show_id}")
def get_show(show_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if show_id not in shows:
        raise HTTPException(status_code=404, detail="Show not found")
    return shows[show_id]

@app.get("/artists/{artist_id}/past-shows")
def get_past_shows(artist_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if artist_id not in artists:
        raise HTTPException(status_code=404, detail="Artist not found")
    artist_shows_list = artist_shows.get(artist_id, [])
    sorted_shows = sorted(artist_shows_list, key=lambda x: x["date"], reverse=True)
    result = []
    for s in sorted_shows:
        result.append({
            "setlist": s["setlist"],
            "venue": s["venue"],
            "attendance": s["attendance"],
            "date": s["date"]
        })
    return {"shows": result}

@app.post("/shows/predict")
def predict_tour_dates(authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if not artist_shows:
        return {"estimated_next_tour_dates": []}

    all_dates = []
    for artist_id, show_list in artist_shows.items():
        for s in show_list:
            try:
                all_dates.append(datetime.strptime(s["date"], "%Y-%m-%d"))
            except:
                pass

    if not all_dates:
        return {"estimated_next_tour_dates": []}

    all_dates.sort()
    gaps = []
    for i in range(1, len(all_dates)):
        gap = (all_dates[i] - all_dates[i-1]).days
        gaps.append(gap)

    avg_gap = sum(gaps) / len(gaps) if gaps else 90
    last_date = all_dates[-1]

    next_dates = []
    for i in range(3):
        next_date = last_date + timedelta(days=int(avg_gap * (i + 1)))
        next_dates.append(next_date.strftime("%Y-%m-%d"))

    return {"estimated_next_tour_dates": next_dates}

