from datetime import datetime, timedelta
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
workouts = {}
workout_id_counter = 1
user_workout_ids = {}

def generate_token():
    return secrets.token_hex(16)

def hash_password(password: str):
    return hashlib.sha256(password.encode()).hexdigest()

def get_user_from_token(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[username] = {"password": hash_password(password), "created_at": datetime.now()}
    token = generate_token()
    tokens[token] = username
    return {"token": token, "username": username}

@app.post("/login")
def login(username: str, password: str):
    if username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if users[username]["password"] != hash_password(password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = username
    return {"token": token, "username": username}

@app.post("/workouts")
def create_workout(authorization: Optional[str] = Header(None)):
    global workout_id_counter
    username = get_user_from_token(authorization)
    workout_id = workout_id_counter
    workout_id_counter += 1
    workouts[workout_id] = {
        "id": workout_id,
        "username": username,
        "exercises": [],
        "created_at": datetime.now().isoformat()
    }
    if username not in user_workout_ids:
        user_workout_ids[username] = []
    user_workout_ids[username].append(workout_id)
    return workouts[workout_id]

@app.get("/workouts/{workout_id}")
def get_workout(workout_id: int, authorization: Optional[str] = Header(None)):
    username = get_user_from_token(authorization)
    if workout_id not in workouts:
        raise HTTPException(status_code=404, detail="Workout not found")
    return workouts[workout_id]

@app.post("/workouts/{workout_id}/exercises")
def add_exercise(workout_id: int, exercise_name: str, sets: int, reps: int, weight: float, authorization: Optional[str] = Header(None)):
    username = get_user_from_token(authorization)
    if workout_id not in workouts:
        raise HTTPException(status_code=404, detail="Workout not found")
    workout = workouts[workout_id]
    exercise = {
        "name": exercise_name,
        "sets": sets,
        "reps": reps,
        "weight": weight
    }
    workout["exercises"].append(exercise)
    return workout

@app.get("/weekly-summary")
def weekly_summary(authorization: Optional[str] = Header(None)):
    username = get_user_from_token(authorization)
    now = datetime.now()
    week_ago = now - timedelta(days=7)

    total_exercises = 0
    total_sets = 0
    total_reps = 0
    total_volume = 0.0
    workout_count = 0

    if username in user_workout_ids:
        for wid in user_workout_ids[username]:
            workout = workouts[wid]
            created = datetime.fromisoformat(workout["created_at"])
            if created >= week_ago:
                workout_count += 1
                for ex in workout["exercises"]:
                    total_exercises += 1
                    total_sets += ex["sets"]
                    total_reps += ex["reps"] * ex["sets"]
                    total_volume += ex["weight"] * ex["reps"] * ex["sets"]

    return {
        "username": username,
        "workout_count": workout_count,
        "total_exercises": total_exercises,
        "total_sets": total_sets,
        "total_reps": total_reps,
        "total_volume_kg": round(total_volume, 2),
        "period": "last 7 days"
    }

