tokens = {}
workflows = {}
workflow_id_counter = 1
execution_logs = []
execution_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class WorkflowCreate(BaseModel):
    trigger: dict
    actions: list

class WorkflowUpdate(BaseModel):
    trigger: dict = None
    actions: list = None

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = {"password": req.password}
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/workflows")
def create_workflow(workflow: WorkflowCreate, authorization: str = Header(None)):
    global workflow_id_counter
    user = get_current_user(authorization)
    wid = workflow_id_counter
    workflow_id_counter += 1
    workflows[wid] = {
        "id": wid,
        "trigger": workflow.trigger,
        "actions": workflow.actions,
        "created_by": user,
        "created_at": datetime.utcnow().isoformat()
    }
    return workflows[wid]

