from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import secrets
import datetime

app = FastAPI()

# In-memory storage
users = {}
tokens = {}
cards = {}
card_id_counter = 0
review_counts = {}

# Simple auth dependency
def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CardCreate(BaseModel):
    front: str
    back: str
    difficulty: int

class CardUpdate(BaseModel):
    front: str = None
    back: str = None
    difficulty: int = None

# Auth endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = {"password": req.password}
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

# Card endpoints
@app.get("/cards/{card_id}")
def get_card(card_id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    if card_id not in cards:
        raise HTTPException(status_code=404, detail="Card not found")
    card = cards[card_id].copy()
    card["review_count"] = review_counts.get(card_id, 0)
    return card

@app.post("/cards")
def create_card(card: CardCreate, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    global card_id_counter
    card_id_counter += 1
    cards[card_id_counter] = {
        "id": card_id_counter,
        "front": card.front,
        "back": card.back,
        "difficulty": card.difficulty,
        "created_by": user,
        "created_at": datetime.datetime.utcnow().isoformat()
    }
    review_counts[card_id_counter] = 0
    return cards[card_id_counter]

@app.patch("/cards/{card_id}/review")
def review_card(card_id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    if card_id not in cards:
        raise HTTPException(status_code=404, detail="Card not found")
    review_counts[card_id] = review_counts.get(card_id, 0) + 1
    return {"review_count": review_counts[card_id]}

