from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import uvicorn

app = FastAPI()

users = {}
tokens = {}
parking_spots = {}
bookings = {}
next_user_id = 1
next_spot_id = 1
next_booking_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ParkingSpot(BaseModel):
    location: str
    price_per_hour: float
    availability: bool = True

class BookingRequest(BaseModel):
    spot_id: int
    start_time: str
    end_time: str

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    token = secrets.token_hex(16)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/parking-spots")
def create_spot(spot: ParkingSpot, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_spot_id
    spot_id = next_spot_id
    next_spot_id += 1
    parking_spots[spot_id] = {
        "id": spot_id,
        "location": spot.location,
        "price_per_hour": spot.price_per_hour,
        "availability": spot.availability
    }
    return parking_spots[spot_id]

@app.get("/parking-spots/{spot_id}")
def get_spot(spot_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if spot_id not in parking_spots:
        raise HTTPException(status_code=404, detail="Spot not found")
    return parking_spots[spot_id]

@app.get("/parking-spots")
def list_spots(authorization: str = Header(None)):
    get_current_user(authorization)
    return list(parking_spots.values())

@app.post("/bookings")
def create_booking(booking: BookingRequest, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if booking.spot_id not in parking_spots:
        raise HTTPException(status_code=404, detail="Spot not found")
    if not parking_spots[booking.spot_id]["availability"]:
        raise HTTPException(status_code=400, detail="Spot not available")
    global next_booking_id
    booking_id = next_booking_id
    next_booking_id += 1
    bookings[booking_id] = {
        "id": booking_id,
        "user_id": user_id,
        "spot_id": booking.spot_id,
        "start_time": booking.start_time,
        "end_time": booking.end_time
    }
    parking_spots[booking.spot_id]["availability"] = False
    return bookings[booking_id]

@app.get("/bookings/{booking_id}")
def get_booking(booking_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if booking_id not in bookings:
        raise HTTPException(status_code=404, detail="Booking not found")
    return bookings[booking_id]

@app.get("/bookings")
def list_bookings(authorization: str = Header(None)):
    get_current_user(authorization)
    return list(bookings.values())

