from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import hashlib
import random
import string

app = FastAPI()

users = {}
tokens = {}
documents = {}
document_versions = {}
next_user_id = 1
next_doc_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization[7:]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class DocumentCreate(BaseModel):
    content: str

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    user_id = next_user_id
    next_user_id += 1
    users[req.username] = {"id": user_id, "password": hashlib.sha256(req.password.encode()).hexdigest()}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    if users[req.username]["password"] != hashlib.sha256(req.password.encode()).hexdigest():
        raise HTTPException(status_code=400, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/documents")
def create_document(doc: DocumentCreate, authorization: str = Header(None)):
    global next_doc_id
    user = get_current_user(authorization)
    doc_id = next_doc_id
    next_doc_id += 1
    documents[doc_id] = {"id": doc_id, "content": doc.content, "version": 1, "created_by": user}
    document_versions[doc_id] = {1: doc.content}
    return documents[doc_id]

@app.get("/documents/{doc_id}")
def get_document(doc_id: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if doc_id not in documents:
        raise HTTPException(status_code=404, detail="Document not found")
    return documents[doc_id]

@app.post("/documents/{doc_id}/versions")
def create_version(doc_id: int, doc: DocumentCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if doc_id not in documents:
        raise HTTPException(status_code=404, detail="Document not found")
    current = documents[doc_id]
    new_version = current["version"] + 1
    current["content"] = doc.content
    current["version"] = new_version
    document_versions[doc_id][new_version] = doc.content
    return current

@app.get("/documents/{doc_id}/versions/{version}")
def get_document_version(doc_id: int, version: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if doc_id not in documents:
        raise HTTPException(status_code=404, detail="Document not found")
    if version not in document_versions[doc_id]:
        raise HTTPException(status_code=404, detail="Version not found")
    return {"doc_id": doc_id, "version": version, "content": document_versions[doc_id][version]}

@app.get("/documents/{doc_id}/diff")
def diff_document(doc_id: int, version1: int, version2: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if doc_id not in documents:
        raise HTTPException(status_code=404, detail="Document not found")
    if version1 not in document_versions[doc_id] or version2 not in document_versions[doc_id]:
        raise HTTPException(status_code=404, detail="Version not found")
    lines1 = document_versions[doc_id][version1].splitlines()
    lines2 = document_versions[doc_id][version2].splitlines()
    diff_lines = []
    import difflib
    for line in difflib.unified_diff(lines1, lines2, lineterm='', fromfile=f'v{version1}', tofile=f'v{version2}'):
        diff_lines.append(line)
    return {"doc_id": doc_id, "version1": version1, "version2": version2, "diff": diff_lines}

