    if reservation_id not in reservations:
        raise HTTPException(status_code=404, detail="Reservation not found")
    return reservations[reservation_id]

@app.post("/reservations")
def create_reservation(party_size: int, time: str, table_preference: str = "", special_requests: str = "", authorization: str = Header(None)):
    global reservation_id_counter
    user_id = get_current_user(authorization)
    rid = reservation_id_counter
    reservation_id_counter += 1
    reservations[rid] = {
        "id": rid,
        "user_id": user_id,
        "party_size": party_size,
        "time": time,
        "table_preference": table_preference,
        "special_requests": special_requests,
        "status": "confirmed"
    }
    return reservations[rid]

@app.put("/reservations/{reservation_id}")
def update_reservation(reservation_id: int, party_size: Optional[int] = None, time: Optional[str] = None, table_preference: Optional[str] = None, special_requests: Optional[str] = None, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if reservation_id not in reservations:
        raise HTTPException(status_code=404, detail="Reservation not found")
    res = reservations[reservation_id]
    if res["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your reservation")
    if party_size is not None:
        res["party_size"] = party_size
    if time is not None:
        res["time"] = time
