def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = {"password": req.password, "votes": {}}
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/polls")
def create_poll(poll: PollCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global poll_id_counter
    poll_id = poll_id_counter
    poll_id_counter += 1
    polls[poll_id] = {
        "id": poll_id,
        "question": poll.question,
        "options": poll.options,
