    if update.results_privacy is not None:
        poll["results_privacy"] = update.results_privacy
    return poll

@app.post("/polls/{poll_id}/vote")
def vote(poll_id: int, vote: VoteRequest, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if poll_id not in polls:
        raise HTTPException(status_code=404, detail="Poll not found")
    poll = polls[poll_id]
    if vote.option_index < 0 or vote.option_index >= len(poll["options"]):
        raise HTTPException(status_code=400, detail="Invalid option")
    if not poll["allow_multiple_votes"]:
        for option_votes in poll["votes"].values():
            if user in option_votes:
                raise HTTPException(status_code=400, detail="Already voted")
    poll["votes"][vote.option_index].append(user)
    return {"message": "Voted"}

