users = {}
tokens = {}
classes = {}
waitlists = {}
bookings = {}
class_id_counter = 1
user_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class UserCreate(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class ClassCreate(BaseModel):
    name: str
    time: str
    instructor: str
    capacity: int
    difficulty: str
    recurring: bool = False
    recurring_end_date: Optional[str] = None

class ClassUpdate(BaseModel):
    time: Optional[str] = None
    instructor: Optional[str] = None
    capacity: Optional[int] = None
    difficulty: Optional[str] = None

class BookingCreate(BaseModel):
    class_id: int

@app.post("/signup")
def signup(user: UserCreate):
    global user_id_counter
    if any(u["username"] == user.username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username exists")
    uid = user_id_counter
    users[uid] = {"id": uid, "username": user.username, "password": user.password}
    user_id_counter += 1
    token = generate_token()
    tokens[token] = uid
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            token = generate_token()
            tokens[token] = uid
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/classes")
