    global class_id_counter
    get_current_user(authorization)
    cid = class_id_counter
    classes[cid] = {
        "id": cid,
        "name": cls.name,
        "time": cls.time,
        "instructor": cls.instructor,
        "capacity": cls.capacity,
        "difficulty": cls.difficulty,
        "recurring": cls.recurring,
        "recurring_end_date": cls.recurring_end_date,
        "booked_count": 0
    }
    waitlists[cid] = []
    class_id_counter += 1
    return classes[cid]

@app.get("/classes/{class_id}")
def get_class(class_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if class_id not in classes:
        raise HTTPException(status_code=404, detail="Class not found")
    return classes[class_id]

@app.put("/classes/{class_id}")
def update_class(class_id: int, update: ClassUpdate, authorization: str = Header(None)):
    get_current_user(authorization)
    if class_id not in classes:
        raise HTTPException(status_code=404, detail="Class not found")
    cls = classes[class_id]
    if update.time is not None:
        cls["time"] = update.time
    if update.instructor is not None:
        cls["instructor"] = update.instructor
    if update.capacity is not None:
        cls["capacity"] = update.capacity
    if update.difficulty is not None:
        cls["difficulty"] = update.difficulty
    return cls

@app.post("/bookings")
def create_booking(booking: BookingCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    cid = booking.class_id
    if cid not in classes:
        raise HTTPException(status_code=404, detail="Class not found")
    cls = classes[cid]
    if cls["booked_count"] < cls["capacity"]:
        bid = len(bookings) + 1
        bookings[bid] = {"id": bid, "user_id": user_id, "class_id": cid}
        cls["booked_count"] += 1
        return bookings[bid]
    else:
        if user_id in waitlists[cid]:
            raise HTTPException(status_code=400, detail="Already on waitlist")
        waitlists[cid].append(user_id)
        return {"message": "Added to waitlist", "waitlist_position": len(waitlists[cid])}

@app.get("/bookings/{booking_id}")
def get_booking(booking_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if booking_id not in bookings:
        raise HTTPException(status_code=404, detail="Booking not found")
    return bookings[booking_id]

@app.get("/classes")
def list_classes(authorization: str = Header(None)):
    get_current_user(authorization)
    return list(classes.values())

