from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import datetime

app = FastAPI()

users = {}
tokens = {}
challenges = {}
challenge_id_counter = 1
leaderboard = {}
daily_progress = {}

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ChallengeCreate(BaseModel):
    name: str
    goal: str
    duration: int
    participants: list[str]
    reward: str

class ChallengeUpdate(BaseModel):
    name: Optional[str] = None
    goal: Optional[str] = None
    duration: Optional[int] = None
    participants: Optional[list[str]] = None
    reward: Optional[str] = None

class ProgressUpdate(BaseModel):
    user: str
    progress: int

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = req.password
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if users.get(req.username) != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.get("/challenges/{challenge_id}")
def get_challenge(challenge_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    challenge = challenges.get(challenge_id)
    if not challenge:
        raise HTTPException(status_code=404, detail="Challenge not found")
    return challenge

@app.post("/challenges")
def create_challenge(challenge: ChallengeCreate, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    global challenge_id_counter
    cid = challenge_id_counter
    challenge_id_counter += 1
    challenges[cid] = {
        "id": cid,
        "name": challenge.name,
        "goal": challenge.goal,
        "duration": challenge.duration,
        "participants": challenge.participants,
        "reward": challenge.reward,
        "created_by": user
    }
    leaderboard[cid] = {p: 0 for p in challenge.participants}
    daily_progress[cid] = {}
    return challenges[cid]

@app.patch("/challenges/{challenge_id}")
def update_challenge(challenge_id: int, update: ChallengeUpdate, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    challenge = challenges.get(challenge_id)
    if not challenge:
        raise HTTPException(status_code=404, detail="Challenge not found")
    if challenge["created_by"] != user:
        raise HTTPException(status_code=403, detail="Not your challenge")
    if update.name is not None:
        challenge["name"] = update.name
    if update.goal is not None:
        challenge["goal"] = update.goal
    if update.duration is not None:
        challenge["duration"] = update.duration
    if update.participants is not None:
        challenge["participants"] = update.participants
        if challenge_id not in leaderboard:
            leaderboard[challenge_id] = {}
        for p in update.participants:
            if p not in leaderboard[challenge_id]:
                leaderboard[challenge_id][p] = 0
    if update.reward is not None:
        challenge["reward"] = update.reward
    return challenge

@app.post("/challenges/{challenge_id}/progress")
def add_progress(challenge_id: int, progress: ProgressUpdate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    challenge = challenges.get(challenge_id)
    if not challenge:
        raise HTTPException(status_code=404, detail="Challenge not found")
    if progress.user not in challenge["participants"]:
        raise HTTPException(status_code=400, detail="User not in challenge")
    today = str(datetime.date.today())
