    survey = surveys.get(survey_id)
    if not survey:
        raise HTTPException(status_code=404, detail="Survey not found")
    return survey

@app.post("/surveys/{survey_id}/responses")
def create_response(survey_id: int, answer: str, authorization: str = Header(None)):
    get_current_user(authorization)
    if survey_id not in surveys:
        raise HTTPException(status_code=404, detail="Survey not found")
    global next_response_id
    response_id = next_response_id
    next_response_id += 1
    responses[response_id] = {"id": response_id, "survey_id": survey_id, "answer": answer}
    return responses[response_id]

