from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import secrets
import uvicorn

app = FastAPI()

users = {}
tokens = {}
snippets = {}
snippet_versions = {}
orders = {}
products = {}

class UserCreate(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class SnippetCreate(BaseModel):
    content: str

class SnippetVersionCreate(BaseModel):
    content: str

class OrderCreate(BaseModel):
    product_id: int
    quantity: int

class ProductCreate(BaseModel):
    name: str
    price: float

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(user: UserCreate):
    if user.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[user.username] = {"username": user.username, "password": user.password}
    return {"message": "User created"}

@app.post("/login")
def login(user: UserLogin):
    if user.username not in users or users[user.username]["password"] != user.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = user.username
    return {"token": token}

@app.post("/snippets")
def create_snippet(snippet: SnippetCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    new_id = len(snippets) + 1
    snippets[new_id] = {"id": new_id, "content": snippet.content}
    return snippets[new_id]

@app.get("/snippets/{snippet_id}")
def get_snippet(snippet_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if snippet_id not in snippets:
        raise HTTPException(status_code=404, detail="Snippet not found")
    return snippets[snippet_id]

@app.post("/snippets/{snippet_id}/versions")
def create_snippet_version(snippet_id: int, version: SnippetVersionCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    if snippet_id not in snippets:
        raise HTTPException(status_code=404, detail="Snippet not found")
    if snippet_id not in snippet_versions:
        snippet_versions[snippet_id] = {}
    new_version_id = len(snippet_versions[snippet_id]) + 1
    snippet_versions[snippet_id][new_version_id] = {"id": new_version_id, "content": version.content}
    return snippet_versions[snippet_id][new_version_id]

@app.get("/snippets/{snippet_id}/versions/{version_id}/raw")
def get_snippet_version_raw(snippet_id: int, version_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if snippet_id not in snippet_versions or version_id not in snippet_versions[snippet_id]:
        raise HTTPException(status_code=404, detail="Version not found")
    return {"content": snippet_versions[snippet_id][version_id]["content"]}

@app.post("/orders")
def create_order(order: OrderCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    new_id = len(orders) + 1
    orders[new_id] = {"id": new_id, "product_id": order.product_id, "quantity": order.quantity}
