    get_user_from_token(authorization)
    global next_property_id
    prop_id = next_property_id
    next_property_id += 1
    properties[prop_id] = {"id": prop_id, **prop.dict()}
    return properties[prop_id]

@app.get("/properties/{prop_id}")
