        "username": "testuser",
        "password": "testpass123"
    })
    if login_resp.status_code != 200:
        return False
    login_data = login_resp.json()
    if "token" not in login_data or "user_id" not in login_data:
        return False
    token = login_data["token"]
    user_id = login_data["user_id"]

    # Create profile
    headers = {"Authorization": f"Bearer {token}"}
    profile_resp = session.post(f"{BASE_URL}/profile", json={
        "skills_offered": ["python", "fastapi"],
        "skills_wanted": ["javascript", "react"]
    }, headers=headers)
    if profile_resp.status_code != 200:
        return False
    profile_data = profile_resp.json()
    if "id" not in profile_data or "user_id" not in profile_data:
        return False
    profile_id = profile_data["id"]

    # Fetch own profile
    get_profile_resp = session.get(f"{BASE_URL}/profile/{profile_id}", headers=headers)
    if get_profile_resp.status_code != 200:
        return False
    get_profile_data = get_profile_resp.json()
    if get_profile_data.get("user_id") != user_id:
