from pydantic import BaseModel
from typing import Optional, List
import time
import secrets

app = FastAPI()

users = {}
tokens = {}
jobs = {}
saves = {}
job_views = {}
next_user_id = 1
next_job_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class JobCreate(BaseModel):
    title: str
    salary_range: str
    skill: str
    remote: bool = False
    employment_type: str

