class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class CarCreate(BaseModel):
    type: str
    location: str
    daily_rate: float
    license_plate: str
    mileage_allowance: Optional[int] = None
    insurance_included: Optional[bool] = False

