    username: str
    password: str

class SubmissionCreate(BaseModel):
    film_title: str
    runtime_minutes: int
    festival: str
    year: int
    status: str
    has_q_and_a: bool = False

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(400, "User exists")
    users[req.username] = req.password
    return {"ok": True}

@app.post("/login")
def login(req: LoginRequest):
    if users.get(req.username) != req.password:
        raise HTTPException(401, "Bad credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

def get_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(401, "No auth")
    token = authorization.replace("Bearer ", "")
    user = tokens.get(token)
    if not user:
        raise HTTPException(401, "Invalid token")
    return user

@app.post("/submissions")
def create_submission(sub: SubmissionCreate, user: str = Header(None)):
    get_user(user)
    global submission_id
    sid = submission_id
    submissions[sid] = sub.dict()
    submissions[sid]["id"] = sid
    submission_id += 1
    return submissions[sid]

@app.get("/submissions/{sid}")
def get_submission(sid: int, user: str = Header(None)):
    get_user(user)
    sub = submissions.get(sid)
    if not sub:
        raise HTTPException(404, "Not found")
    return sub

@app.get("/submissions")
def list_submissions(festival: str = None, year: int = None, status: str = None, user: str = Header(None)):
