    result = []
    for sub in submissions.values():
        if festival:
            festivals = [f.strip() for f in festival.split(",")]
            if sub["festival"] not in festivals:
                continue
        if year is not None and sub["year"] != year:
            continue
        if status:
            statuses = [s.strip() for s in status.split(",")]
            if sub["status"] not in statuses:
                continue
        result.append({
            "film_title": sub["film_title"],
            "runtime_minutes": sub["runtime_minutes"],
            "has_q_and_a": sub["has_q_and_a"]
        })
    return result

