from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import hashlib
import secrets
from datetime import datetime

app = FastAPI()

users = {}
tokens = {}
trips = {}
items = {}
trip_counter = 0
item_counter = 0
user_counter = 0

CATEGORIES = {
    "clothing": 1,
    "toiletries": 2,
    "electronics": 3,
    "documents": 4,
    "health": 5,
    "misc": 6
}

@app.post("/signup")
def signup(username: str, password: str):
    global user_counter
    if username in users:
        raise HTTPException(400, "User exists")
    user_counter += 1
    users[username] = {"id": user_counter, "password": hashlib.sha256(password.encode()).hexdigest()}
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"user_id": user_counter, "token": token}

@app.post("/login")
def login(username: str, password: str):
    if username not in users:
        raise HTTPException(400, "Invalid credentials")
    if users[username]["password"] != hashlib.sha256(password.encode()).hexdigest():
        raise HTTPException(400, "Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

def get_user(token: str = Header(...)):
    if token not in tokens:
        raise HTTPException(401, "Invalid token")
    return tokens[token]

@app.post("/trips")
def create_trip(destination: str, start_date: str, end_date: str, token: str = Header(...)):
    global trip_counter
    user = get_user(token)
    trip_counter += 1
    trips[trip_counter] = {
        "id": trip_counter,
        "user": user,
        "destination": destination,
        "start_date": start_date,
        "end_date": end_date,
        "items": []
    }
    return trips[trip_counter]

@app.get("/trips/{trip_id}")
def get_trip(trip_id: int, token: str = Header(...)):
    user = get_user(token)
    if trip_id not in trips:
        raise HTTPException(404, "Trip not found")
    return trips[trip_id]

@app.post("/items")
def create_item(trip_id: int, name: str, quantity: int = 1, category: str = "misc", token: str = Header(...)):
    global item_counter
    user = get_user(token)
    if trip_id not in trips:
        raise HTTPException(404, "Trip not found")
    if trips[trip_id]["user"] != user:
        raise HTTPException(403, "Not your trip")
    if category not in CATEGORIES:
        raise HTTPException(400, "Invalid category")
    item_counter += 1
    items[item_counter] = {
        "id": item_counter,
        "trip_id": trip_id,
        "name": name,
        "quantity": quantity,
        "category": category
    }
    trips[trip_id]["items"].append(item_counter)
    return items[item_counter]

@app.get("/items/{item_id}")
def get_item(item_id: int, token: str = Header(...)):
    user = get_user(token)
    if item_id not in items:
        raise HTTPException(404, "Item not found")
    return items[item_id]

@app.get("/trips/{trip_id}/checklist")
def get_checklist(trip_id: int, token: str = Header(...)):
    user = get_user(token)
    if trip_id not in trips:
        raise HTTPException(404, "Trip not found")
    if trips[trip_id]["user"] != user:
        raise HTTPException(403, "Not your trip")
    trip_items = [items[i] for i in trips[trip_id]["items"]]
    trip_items.sort(key=lambda x: CATEGORIES.get(x["category"], 99))
    return trip_items

