from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List, Dict
import secrets
import uuid

app = FastAPI()

# In-memory stores
users = {}
guests = {}
tables = {}
rsvps = {}
seating_charts = {}
tokens = {}
next_user_id = 1
next_guest_id = 1
next_table_id = 1
next_rsvp_id = 1
next_chart_id = 1

# Auth helpers
def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class GuestCreate(BaseModel):
    name: str
    meal_preference: Optional[str] = None

class GuestUpdate(BaseModel):
    name: Optional[str] = None
    meal_preference: Optional[str] = None

class TableCreate(BaseModel):
    table_number: int
    capacity: int

class RSVPCreate(BaseModel):
    guest_id: int
    status: str  # "accepted", "declined", "pending"

class SeatingChartCreate(BaseModel):
    name: str
    table_assignments: Dict[int, List[int]]  # table_id -> list of guest_ids

# --- Auth Endpoints ---
@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for user in users.values():
        if user["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    token = secrets.token_hex(32)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = secrets.token_hex(32)
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# --- Guest Endpoints ---
@app.get("/guests/{guest_id}")
def get_guest(guest_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if guest_id not in guests:
        raise HTTPException(status_code=404, detail="Guest not found")
    return guests[guest_id]

@app.post("/guests")
def create_guest(guest: GuestCreate, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    global next_guest_id
    guest_id = next_guest_id
    next_guest_id += 1
    guests[guest_id] = {"id": guest_id, "name": guest.name, "meal_preference": guest.meal_preference}
    return guests[guest_id]

@app.get("/guests")
def list_guests(authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    return list(guests.values())

# --- Table Endpoints ---
@app.get("/tables/{table_id}")
def get_table(table_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if table_id not in tables:
        raise HTTPException(status_code=404, detail="Table not found")
    return tables[table_id]

@app.post("/tables")
def create_table(table: TableCreate, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    global next_table_id
    table_id = next_table_id
    next_table_id += 1
    tables[table_id] = {"id": table_id, "table_number": table.table_number, "capacity": table.capacity, "assigned_guests": []}
    return tables[table_id]

@app.get("/tables")
def list_tables(authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    return list(tables.values())

# --- RSVP Endpoints ---
@app.get("/rsvps/{rsvp_id}")
def get_rsvp(rsvp_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if rsvp_id not in rsvps:
        raise HTTPException(status_code=404, detail="RSVP not found")
    return rsvps[rsvp_id]

@app.post("/rsvps")
def create_rsvp(rsvp: RSVPCreate, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    global next_rsvp_id
    if rsvp.guest_id not in guests:
        raise HTTPException(status_code=404, detail="Guest not found")
    rsvp_id = next_rsvp_id
    next_rsvp_id += 1
    rsvps[rsvp_id] = {"id": rsvp_id, "guest_id": rsvp.guest_id, "status": rsvp.status}
    guests[rsvp.guest_id]["rsvp_status"] = rsvp.status
    return rsvps[rsvp_id]

@app.get("/rsvps")
def list_rsvps(authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    return list(rsvps.values())

# --- Seating Chart Endpoints ---
@app.get("/seating_charts/{chart_id}")
def get_seating_chart(chart_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if chart_id not in seating_charts:
        raise HTTPException(status_code=404, detail="Seating chart not found")
    return seating_charts[chart_id]

@app.post("/seating_charts")
def create_seating_chart(chart: SeatingChartCreate, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    global next_chart_id
    # Validate all tables and guests exist
    for table_id in chart.table_assignments:
        if table_id not in tables:
            raise HTTPException(status_code=404, detail=f"Table {table_id} not found")
        for guest_id in chart.table_assignments[table_id]:
            if guest_id not in guests:
