import datetime

app = FastAPI()

users = {}
pledges = {}
installments = {}
tokens = {}
pledge_id_counter = 1
installment_id_counter = 1
user_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PledgeCreate(BaseModel):
    donor_name: str
    total_amount: float
    installment_plan: Optional[List[float]] = None

class InstallmentCreate(BaseModel):
    pledge_id: int
    amount: float
    due_date: str

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/pledges")
def create_pledge(pledge: PledgeCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global pledge_id_counter
    pid = pledge_id_counter
    pledge_id_counter += 1
    pledges[pid] = {
        "id": pid,
        "donor_name": pledge.donor_name,
        "total_amount": pledge.total_amount,
        "fulfilled": False,
        "created_at": datetime.datetime.now().isoformat()
    }
    if pledge.installment_plan:
        for amount in pledge.installment_plan:
            global installment_id_counter
            iid = installment_id_counter
            installment_id_counter += 1
            installments[iid] = {
                "id": iid,
                "pledge_id": pid,
                "amount": amount,
                "paid": False,
                "due_date": None
            }
    return pledges[pid]

@app.get("/pledges/{pledge_id}")
def get_pledge(pledge_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    p = pledges.get(pledge_id)
    if not p:
        raise HTTPException(status_code=404, detail="Pledge not found")
    return p

@app.post("/installments")
def create_installment(inst: InstallmentCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    if inst.pledge_id not in pledges:
        raise HTTPException(status_code=404, detail="Pledge not found")
    global installment_id_counter
    iid = installment_id_counter
    installment_id_counter += 1
    installments[iid] = {
        "id": iid,
        "pledge_id": inst.pledge_id,
        "amount": inst.amount,
        "due_date": inst.due_date,
        "paid": False
    }
    return installments[iid]

@app.get("/installments/{installment_id}")
def get_installment(installment_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    i = installments.get(installment_id)
    if not i:
        raise HTTPException(status_code=404, detail="Installment not found")
    return i

@app.post("/reconcile/{pledge_id}")
def reconcile_pledge(pledge_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    p = pledges.get(pledge_id)
    if not p:
        raise HTTPException(status_code=404, detail="Pledge not found")
    total_paid = sum(i["amount"] for i in installments.values() if i["pledge_id"] == pledge_id and i["paid"])
    if total_paid >= p["total_amount"]:
        p["fulfilled"] = True
        return {"status": "fulfilled", "pledge_id": pledge_id}
    else:
        remaining = p["total_amount"] - total_paid
        return {"status": "partial", "fulfilled": False, "remaining": remaining}

@app.get("/alerts")
def get_alerts(authorization: str = Header(None)):
    get_current_user(authorization)
    alerts = []
    for pid, p in pledges.items():
        if p["fulfilled"]:
            continue
        due_soon = []
        for iid, i in installments.items():
            if i["pledge_id"] == pid and not i["paid"] and i["due_date"]:
                due_date = datetime.datetime.fromisoformat(i["due_date"])
                if due_date <= datetime.datetime.now() + datetime.timedelta(days=7):
                    due_soon.append(i)
        if due_soon:
            alerts.append({"pledge_id": pid, "donor": p["donor_name"], "due_installments": due_soon})
    return alerts

