# SQLite setup
conn = sqlite3.connect(":memory:", check_same_thread=False)
c = conn.cursor()
c.execute("""CREATE TABLE recipes (
    id INTEGER PRIMARY KEY,
    name TEXT,
    calories INTEGER,
    protein REAL,
    ingredients TEXT,
    macros TEXT
)""")
conn.commit()

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class RecipeCreate(BaseModel):
    name: str
    calories: int
    protein: float
    ingredients: str = ""
    macros: str = ""

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[req.username] = {"id": user_id, "password": hash_password(req.password)}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = user["id"]
    return {"token": token}

@app.post("/recipes")
def create_recipe(recipe: RecipeCreate, authorization: str = Header(None)):
    global recipe_id_counter
    get_user_id_from_token(authorization)
    recipe_id = recipe_id_counter
    recipe_id_counter += 1
    recipes[recipe_id] = recipe.dict()
    c.execute("INSERT INTO recipes VALUES (?,?,?,?,?,?)",
              (recipe_id, recipe.name, recipe.calories, recipe.protein,
               recipe.ingredients, recipe.macros))
    conn.commit()
    return {"id": recipe_id, **recipe.dict()}

@app.get("/recipes/{recipe_id}")
