    get_user_id_from_token(authorization)
    recipe = recipes.get(recipe_id)
    if not recipe:
        raise HTTPException(status_code=404, detail="Recipe not found")
    return {"id": recipe_id, **recipe}

@app.get("/recipes")
def search_recipes(calories: int = None, protein: float = None, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    query = "SELECT id, name, calories, protein, ingredients, macros FROM recipes WHERE 1=1"
    params = []
    if calories is not None:
        query += " AND calories <= ?"
        params.append(calories)
    if protein is not None:
        query += " AND protein >= ?"
        params.append(protein)
