    conn.execute("INSERT INTO holdings (id, sector, pe_ratio, dividend_yield) VALUES (?, ?, ?, ?)",
                 (stock_id, stock.sector, stock.pe_ratio, stock.dividend_yield))
    conn.commit()
    return stocks[stock_id]

