from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
from datetime import datetime, date
import secrets
import time

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
events = {}
tickets = {}
orders = {}

# ID counters
user_id_counter = 1
event_id_counter = 1
ticket_id_counter = 1
order_id_counter = 1

# Auth helper
def get_user_id(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(401, "Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(401, "Invalid token")
    return user_id

# Models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class EventCreate(BaseModel):
    name: str
    venue: str
    date: date
    premium_price: float
    standard_price: float
    premium_available: int = 0
    standard_available: int = 0

class TicketSearchParams(BaseModel):
    venue: Optional[str] = None
    from_date: Optional[date] = None
    to_date: Optional[date] = None
    tier: Optional[str] = None

# Endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    uid = user_id_counter
    user_id_counter += 1
    users[uid] = {"username": req.username, "password": req.password}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(401, "Invalid credentials")

@app.get("/events/{event_id}")
def get_event(event_id: int):
    event = events.get(event_id)
    if not event:
        raise HTTPException(404, "Event not found")
    return event

@app.post("/events")
def create_event(event: EventCreate, authorization: str = Header(None)):
    get_user_id(authorization)
    global event_id_counter
    eid = event_id_counter
    event_id_counter += 1
    events[eid] = {
        "id": eid,
        "name": event.name,
        "venue": event.venue,
        "date": str(event.date),
        "premium_price": event.premium_price,
        "standard_price": event.standard_price,
        "premium_available": event.premium_available,
        "standard_available": event.standard_available
    }
    return events[eid]

@app.get("/tickets")
def search_tickets(
    venue: Optional[str] = None,
    from_date: Optional[date] = None,
    to_date: Optional[date] = None,
    tier: Optional[str] = None,
    authorization: str = Header(None)
):
    get_user_id(authorization)
    results = []
    for eid, event in events.items():
        if venue and event["venue"] != venue:
            continue
        event_date = datetime.strptime(event["date"], "%Y-%m-%d").date()
        if from_date and event_date < from_date:
            continue
        if to_date and event_date > to_date:
            continue
        if tier == "premium" and event["premium_available"] > 0:
            results.append({"event_id": eid, "venue": event["venue"], "date": event["date"], "tier": "premium", "price": event["premium_price"], "available": event["premium_available"]})
        elif tier == "standard" and event["standard_available"] > 0:
            results.append({"event_id": eid, "venue": event["venue"], "date": event["date"], "tier": "standard", "price": event["standard_price"], "available": event["standard_available"]})
        elif tier is None:
            if event["premium_available"] > 0:
                results.append({"event_id": eid, "venue": event["venue"], "date": event["date"], "tier": "premium", "price": event["premium_price"], "available": event["premium_available"]})
            if event["standard_available"] > 0:
                results.append({"event_id": eid, "venue": event["venue"], "date": event["date"], "tier": "standard", "price": event["standard_price"], "available": event["standard_available"]})
    return results

@app.get("/tickets/{ticket_id}")
def get_ticket(ticket_id: int, authorization: str = Header(None)):
    get_user_id(authorization)
    ticket = tickets.get(ticket_id)
    if not ticket:
        raise HTTPException(404, "Ticket not found")
    return ticket

@app.post("/tickets")
def create_ticket(event_id: int, tier: str, authorization: str = Header(None)):
    user_id = get_user_id(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(404, "Event not found")
    if tier == "premium":
        if event["premium_available"] <= 0:
            raise HTTPException(400, "No premium tickets available")
        event["premium_available"] -= 1
        price = event["premium_price"]
    elif tier == "standard":
        if event["standard_available"] <= 0:
            raise HTTPException(400, "No standard tickets available")
        event["standard_available"] -= 1
        price = event["standard_price"]
    else:
        raise HTTPException(400, "Invalid tier")
    global ticket_id_counter
    tid = ticket_id_counter
    ticket_id_counter += 1
    tickets[tid] = {
        "id": tid,
        "event_id": event_id,
        "user_id": user_id,
        "tier": tier,
        "price": price,
        "purchased_at": time.time()
    }
    return tickets[tid]

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: str = Header(None)):
    get_user_id(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(404, "Order not found")
    return order

@app.post("/orders")
def create_order(event_id: int, tier: str, quantity: int = 1, authorization: str = Header(None)):
    user_id = get_user_id(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(404, "Event not found")
    if tier == "premium":
        if event["premium_available"] < quantity:
            raise HTTPException(400, f"Only {event['premium_available']} premium tickets available")
        event["premium_available"] -= quantity
        price = event["premium_price"]
    elif tier == "standard":
        if event["standard_available"] < quantity:
            raise HTTPException(400, f"Only {event['standard_available']} standard tickets available")
        event["standard_available"] -= quantity
        price = event["standard_price"]
    else:
        raise HTTPException(400, "Invalid tier")
    global order_id_counter
    oid = order_id_counter
    order_id_counter += 1
    orders[oid] = {
        "id": oid,
        "user_id": user_id,
        "event_id": event_id,
        "tier": tier,
        "quantity": quantity,
        "total_price": price * quantity,
        "created_at": time.time()
    }
    return orders[oid]

