app = FastAPI()

# In-memory stores
users = {}
tokens = {}
parking_spots = {}
spot_id_counter = 0

# Auth helper
def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ParkingSpotCreate(BaseModel):
    lat: float
    lon: float
    price_per_hour: float
    available: bool = True

class ParkingSpotUpdate(BaseModel):
    lat: Optional[float] = None
    lon: Optional[float] = None
    price_per_hour: Optional[float] = None
    available: Optional[bool] = None

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = hashlib.sha256(req.password.encode()).hexdigest()
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if users[req.username] != hashlib.sha256(req.password.encode()).hexdigest():
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.get("/spots/{spot_id}")
def get_spot(spot_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if spot_id not in parking_spots:
        raise HTTPException(status_code=404, detail="Spot not found")
    return parking_spots[spot_id]

@app.post("/spots")
def create_spot(spot: ParkingSpotCreate, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    global spot_id_counter
    spot_id_counter += 1
    parking_spots[spot_id_counter] = {
        "id": spot_id_counter,
        "lat": spot.lat,
        "lon": spot.lon,
        "price_per_hour": spot.price_per_hour,
        "available": spot.available
    }
    return parking_spots[spot_id_counter]

@app.get("/spots")
def search_spots(
    lat: float,
    lon: float,
    price_max: float,
    available: bool = True,
    authorization: str = Header(None)
):
    get_user_id_from_token(authorization)
    results = []
    for spot in parking_spots.values():
        if spot["available"] != available:
            continue
        if spot["price_per_hour"] > price_max:
            continue
        # Simple Euclidean distance (approx, ignoring curvature)
        dlat = spot["lat"] - lat
        dlon = spot["lon"] - lon
        dist = math.sqrt(dlat*dlat + dlon*dlon)
        results.append((dist, spot))
    results.sort(key=lambda x: x[0])
    return [spot for _, spot in results]

