import sqlite3
from datetime import datetime
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import hashlib
import secrets

app = FastAPI()

# SQLite setup
conn = sqlite3.connect(":memory:", check_same_thread=False)
conn.row_factory = sqlite3.Row
cursor = conn.cursor()

cursor.execute("""
CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    token TEXT
)
""")

cursor.execute("""
CREATE TABLE classes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL,
    instructor TEXT NOT NULL,
    time_of_day TEXT NOT NULL,
    capacity INTEGER NOT NULL,
    booked INTEGER DEFAULT 0
)
""")

cursor.execute("""
CREATE TABLE bookings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    class_id INTEGER NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id),
    FOREIGN KEY (class_id) REFERENCES classes(id)
)
""")

# Seed some classes
sample_classes = [
    ("yoga", "Alice", "morning", 10),
    ("yoga", "Bob", "evening", 5),
    ("pilates", "Alice", "afternoon", 8),
    ("spinning", "Charlie", "evening", 6),
    ("yoga", "X", "evening", 3),
]
for c in sample_classes:
    cursor.execute("INSERT INTO classes (type, instructor, time_of_day, capacity) VALUES (?, ?, ?, ?)", c)
conn.commit()

class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class ClassCreate(BaseModel):
    type: str
    instructor: str
    time_of_day: str
    capacity: int

class BookingCreate(BaseModel):
    class_id: int

def get_user_by_token(token: str):
    cursor.execute("SELECT * FROM users WHERE token = ?", (token,))
    return cursor.fetchone()

@app.post("/signup")
def signup(user: UserSignup):
    password_hash = hashlib.sha256(user.password.encode()).hexdigest()
    token = secrets.token_hex(16)
    try:
        cursor.execute("INSERT INTO users (username, password_hash, token) VALUES (?, ?, ?)",
                       (user.username, password_hash, token))
        conn.commit()
        return {"id": cursor.lastrowid, "token": token}
    except sqlite3.IntegrityError:
        raise HTTPException(status_code=400, detail="Username already exists")

@app.post("/login")
def login(user: UserLogin):
    password_hash = hashlib.sha256(user.password.encode()).hexdigest()
    cursor.execute("SELECT * FROM users WHERE username = ? AND password_hash = ?",
                   (user.username, password_hash))
    row = cursor.fetchone()
    if not row:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    cursor.execute("UPDATE users SET token = ? WHERE id = ?", (token, row["id"]))
    conn.commit()
    return {"token": token}

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user = get_user_by_token(token)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid token")
    cursor.execute("SELECT id, username FROM users WHERE id = ?", (user_id,))
    row = cursor.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="User not found")
    return dict(row)

@app.get("/classes/{class_id}")
def get_class(class_id: int, authorization: str = Header(None)):
