    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user = get_user_by_token(token)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid token")

    cursor.execute("SELECT * FROM classes WHERE id = ?", (booking.class_id,))
    cls = cursor.fetchone()
    if not cls:
        raise HTTPException(status_code=404, detail="Class not found")
    if cls["booked"] >= cls["capacity"]:
        raise HTTPException(status_code=400, detail="Class is full")

    cursor.execute("INSERT INTO bookings (user_id, class_id) VALUES (?, ?)",
                   (user["id"], booking.class_id))
    cursor.execute("UPDATE classes SET booked = booked + 1 WHERE id = ?", (booking.class_id,))
    conn.commit()
    return {"id": cursor.lastrowid}

