import secrets
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

users = {}
tokens = {}
books = {}
book_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class BookCreate(BaseModel):
    title: str
    author: str
    genre: str
    isbn: str
    page_count: int

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = req.password
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.get("/books/{book_id}")
def get_book(book_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if book_id not in books:
        raise HTTPException(status_code=404, detail="Book not found")
    return books[book_id]

@app.post("/books")
def create_book(book: BookCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global book_id_counter
    book_id = book_id_counter
    book_id_counter += 1
    books[book_id] = {"id": book_id, **book.dict()}
    return books[book_id]

@app.get("/books")
def search_books(author: Optional[str] = None, genre: Optional[str] = None, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    results = []
    for book in books.values():
        if author and book["author"] != author:
            continue
        if genre and book["genre"] != genre:
            continue
        results.append(book)
    return results

