        params.append(fuel_type)
    cur = conn.execute(query, params)
    rows = cur.fetchall()
    return [{"id": r[0], "status": r[1], "fuel_type": r[2], "last_service_date": r[3]} for r in rows]

@app.post("/cars")
def create_car(car: CarCreate, authorization: str = Header(None)):
    global next_car_id
    get_current_user(authorization)
    if car.last_service_date is None:
        car.last_service_date = datetime.now().isoformat()
    conn.execute("INSERT INTO cars (id, status, fuel_type, last_service_date) VALUES (?, ?, ?, ?)",
                 (next_car_id, car.status, car.fuel_type, car.last_service_date))
