    ('Taco Bell', 'Crunchwrap Supreme', 4.99, 6, 'gluten'),
    ('Taco Bell', 'Black Bean Burrito', 3.49, 5, 'vegan,gluten-free'),
]
conn.executemany('INSERT INTO items (restaurant, name, price, prep_time, dietary_tags) VALUES (?, ?, ?, ?, ?)', sample_items)
