import os
import shutil
import hashlib
import json
from pathlib import Path
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel

app = FastAPI()

AUTH_TOKENS = {}
USERS = {}
USER_ID = 0

DOCUMENTS = {}
DOC_ID = 0

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token(user_id):
    return hashlib.sha256(f"{user_id}:{os.urandom(16).hex()}".encode()).hexdigest()

def require_auth(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Unauthorized")
    token = authorization.split(" ")[1]
    if token not in AUTH_TOKENS:
        raise HTTPException(status_code=401, detail="Invalid token")
    return AUTH_TOKENS[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class DocumentCreate(BaseModel):
    content: str
    filename: str = "document.txt"

@app.post("/signup")
def signup(req: SignupRequest):
    global USER_ID
    if req.username in USERS:
        raise HTTPException(status_code=400, detail="Username taken")
    USER_ID += 1
    USERS[req.username] = {"id": USER_ID, "password_hash": hash_password(req.password)}
    return {"id": USER_ID, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = USERS.get(req.username)
    if not user or user["password_hash"] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token(user["id"])
    AUTH_TOKENS[token] = user["id"]
    return {"token": token}

@app.post("/document")
def create_document(req: DocumentCreate, authorization: str = Header(None)):
    user_id = require_auth(authorization)
    global DOC_ID
    DOC_ID += 1
    doc_path = Path(f"docs/{DOC_ID}")
    doc_path.mkdir(parents=True, exist_ok=True)
    v1_path = doc_path / "v1"
    v1_path.mkdir(parents=True, exist_ok=True)
    file_path = v1_path / req.filename
    file_path.write_text(req.content)

    DOCUMENTS[DOC_ID] = {
        "id": DOC_ID,
        "filename": req.filename,
        "current_version": 1,
        "versions": [1],
        "owner": user_id
    }

    # Update full-text search index
    index_path = Path("search_index.json")
    if index_path.exists():
        with open(index_path) as f:
            index = json.load(f)
    else:
        index = {}
    words = set(req.content.lower().split())
    for word in words:
        if word not in index:
            index[word] = []
        if DOC_ID not in index[word]:
            index[word].append(DOC_ID)
    with open(index_path, "w") as f:
        json.dump(index, f)

    return {"id": DOC_ID, "version": 1}

@app.get("/document/{doc_id}")
def get_document_latest(doc_id: int, authorization: str = Header(None)):
    require_auth(authorization)
    doc = DOCUMENTS.get(doc_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    version = doc["current_version"]
    file_path = Path(f"docs/{doc_id}/v{version}/{doc['filename']}")
    if not file_path.exists():
        raise HTTPException(status_code=404, detail="File not found")
    return {"id": doc_id, "version": version, "content": file_path.read_text()}

@app.get("/document/{doc_id}/{version}")
def get_document_version(doc_id: int, version: int, authorization: str = Header(None)):
    require_auth(authorization)
    doc = DOCUMENTS.get(doc_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    if version not in doc["versions"]:
        raise HTTPException(status_code=404, detail="Version not found")
    file_path = Path(f"docs/{doc_id}/v{version}/{doc['filename']}")
    if not file_path.exists():
        raise HTTPException(status_code=404, detail="File not found")
    return {"id": doc_id, "version": version, "content": file_path.read_text()}

@app.post("/document/{doc_id}/version")
def create_version(doc_id: int, req: DocumentCreate, authorization: str = Header(None)):
    user_id = require_auth(authorization)
    doc = DOCUMENTS.get(doc_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    if doc["owner"] != user_id:
        raise HTTPException(status_code=403, detail="Not your document")

    new_version = doc["current_version"] + 1
    v_path = Path(f"docs/{doc_id}/v{new_version}")
    v_path.mkdir(parents=True, exist_ok=True)
    file_path = v_path / doc["filename"]
    file_path.write_text(req.content)

    doc["current_version"] = new_version
    doc["versions"].append(new_version)

    # Update search index
    index_path = Path("search_index.json")
    if index_path.exists():
        with open(index_path) as f:
            index = json.load(f)
    else:
        index = {}
    words = set(req.content.lower().split())
    for word in words:
        if word not in index:
            index[word] = []
        if doc_id not in index[word]:
            index[word].append(doc_id)
    with open(index_path, "w") as f:
        json.dump(index, f)

    return {"id": doc_id, "version": new_version}

@app.get("/search")
def search(q: str = "", authorization: str = Header(None)):
    require_auth(authorization)
    if not q:
        return {"results": []}
    index_path = Path("search_index.json")
    if not index_path.exists():
        return {"results": []}
    with open(index_path) as f:
        index = json.load(f)
    words = q.lower().split()
    results = set()
    for word in words:
        if word in index:
            results.update(index[word])
    return {"results": list(results)}

