app = FastAPI()

# In-memory stores
users = {}
tokens = {}
bugs = {}
bug_attachments = {}
next_user_id = 1
next_bug_id = 1

# Simple token auth
def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Signup
class SignupRequest(BaseModel):
    username: str
    password: str

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for user in users.values():
        if user["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

# Login
class LoginRequest(BaseModel):
    username: str
    password: str

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Bug CRUD
class BugCreate(BaseModel):
    title: str
    description: str = ""

@app.get("/bugs/{bug_id}")
def get_bug(bug_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if bug_id not in bugs:
        raise HTTPException(status_code=404, detail="Bug not found")
    return bugs[bug_id]

@app.post("/bugs")
def create_bug(bug: BugCreate, authorization: str = Header(None)):
    global next_bug_id
    user_id = get_user_from_token(authorization)
    bug_id = next_bug_id
    next_bug_id += 1
    bugs[bug_id] = {"id": bug_id, "title": bug.title, "description": bug.description, "user_id": user_id, "attachments": []}
    bug_attachments[bug_id] = {}
    return bugs[bug_id]

# Attachment endpoints
