async def upload_attachments(bug_id: int, files: list[UploadFile] = File(...), descriptions: list[str] = Form(None), authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    if bug_id not in bugs:
        raise HTTPException(status_code=404, detail="Bug not found")

    bug_dir = Path(f"/bugs/{bug_id}")
    bug_dir.mkdir(parents=True, exist_ok=True)

    if bug_id not in bug_attachments:
        bug_attachments[bug_id] = {}

    if descriptions is None:
        descriptions = [""] * len(files)

    results = []
    for i, file in enumerate(files):
        description = descriptions[i] if i < len(descriptions) else ""
        file_path = bug_dir / file.filename
        with open(file_path, "wb") as f:
            content = await file.read()
            f.write(content)

        attachment_info = {"filename": file.filename, "description": description, "path": str(file_path)}
        bug_attachments[bug_id][file.filename] = attachment_info
        bugs[bug_id]["attachments"].append(file.filename)
        results.append(attachment_info)

