    if filename not in bug_attachments.get(bug_id, {}):
        raise HTTPException(status_code=404, detail="Attachment not found")

    file_path = Path(f"/bugs/{bug_id}/{filename}")
    if not file_path.exists():
        raise HTTPException(status_code=404, detail="File not found on disk")

    return {"filename": filename, "description": bug_attachments[bug_id][filename]["description"]}

