    global next_order_id
    user_id = get_user_from_token(authorization)
    order_id = next_order_id
    next_order_id += 1
    orders[order_id] = {"id": order_id, "item": order.item, "quantity": order.quantity, "user_id": user_id}
    return orders[order_id]

