    user = get_current_user(authorization)
    if contract_id not in contracts:
        raise HTTPException(status_code=404, detail="Contract not found")
    return contracts[contract_id]

@app.post("/contracts")
def create_contract(req: ContractCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    new_id = max(contracts.keys()) + 1 if contracts else 1
    contracts[new_id] = {"id": new_id, "name": req.name}
    return contracts[new_id]

@app.get("/contracts/{contract_id}/versions/{version_num}/{filename}")
def get_signed_pdf(contract_id: int, version_num: int, filename: str, authorization: str = Header(None), x_user_id: str = Header(None)):
    user = get_current_user(authorization)
    if not x_user_id:
        raise HTTPException(status_code=400, detail="x-user-id header required for tracking")
    file_path = os.path.join("/legal_docs", filename)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="File not found")
    access_log = {
        "user_id": x_user_id,
        "contract_id": contract_id,
        "version_num": version_num,
        "filename": filename,
        "timestamp": "tracked"
    }
    doc_id = max(documents.keys()) + 1 if documents else 1
    documents[doc_id] = access_log
    return FileResponse(file_path, media_type="application/pdf", filename=filename)

