    users[req.username] = {"id": user_id, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    auth_tokens[token] = {"user_id": user["id"], "expires": datetime.utcnow() + AUTH_TOKEN_VALIDITY}
    return {"token": token}

@app.post("/orders")
def create_order(req: OrderRequest, authorization: str = Header(None)):
    authenticate(authorization)
    global next_order_id
    order_id = next_order_id
    next_order_id += 1
    orders[order_id] = {
        "id": order_id,
        "company": req.company,
        "shareholder": req.shareholder,
        "shares": req.shares
    }
    return orders[order_id]

