    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    cert_id = order_id
    filename = f"{certs_dir}/{cert_id}.pdf"
    buffer = BytesIO()
    p = canvas.Canvas(buffer)
    p.drawString(100, 750, f"CERTIFICATE OF SHARES")
    p.drawString(100, 700, f"Company: {order['company']}")
    p.drawString(100, 680, f"Shareholder: {order['shareholder']}")
    p.drawString(100, 660, f"Number of Shares: {order['shares']}")
