import uuid
from fastapi import FastAPI, HTTPException, Header, UploadFile, File
from fastapi.responses import FileResponse

app = FastAPI()

users = {}
tokens = {}
photos = {}
photo_id_counter = 1

PROFILES_DIR = "profiles"
os.makedirs(PROFILES_DIR, exist_ok=True)

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="Username taken")
    user_id = len(users) + 1
    users[username] = {"id": user_id, "password": password}
    return {"user_id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    user = users.get(username)
    if not user or user["password"] != password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = user["id"]
    return {"token": token}

@app.post("/profile/{user_id}/photos")
async def upload_photo(user_id: int, file: UploadFile = File(...), authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if current_user != user_id:
        raise HTTPException(status_code=403, detail="Not your profile")
    global photo_id_counter
    photo_id = photo_id_counter
    photo_id_counter += 1
    user_dir = os.path.join(PROFILES_DIR, str(user_id))
    os.makedirs(user_dir, exist_ok=True)
    file_path = os.path.join(user_dir, f"{photo_id}.jpg")
    with open(file_path, "wb") as f:
        shutil.copyfileobj(file.file, f)
    photos[photo_id] = {"id": photo_id, "user_id": user_id, "path": file_path}
    return {"photo_id": photo_id}

@app.get("/profile/{user_id}/photos/{photo_id}")
def get_photo(user_id: int, photo_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    photo = photos.get(photo_id)
    if not photo or photo["user_id"] != user_id:
        raise HTTPException(status_code=404, detail="Photo not found")
    return FileResponse(photo["path"])

@app.delete("/profile/{user_id}/photos/{photo_id}")
def delete_photo(user_id: int, photo_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if current_user != user_id:
        raise HTTPException(status_code=403, detail="Not your profile")
    photo = photos.get(photo_id)
    if not photo or photo["user_id"] != user_id:
        raise HTTPException(status_code=404, detail="Photo not found")
    os.remove(photo["path"])
    del photos[photo_id]
    return {"ok": True}

