    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ProfileCreate(BaseModel):
    name: str

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer" or not token:
        raise HTTPException(status_code=401, detail="Invalid auth header")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    salt = os.urandom(16).hex()
    pw_hash = hashlib.sha256((req.password + salt).encode()).hexdigest()
    users[user_id] = {"username": req.username, "pw_hash": pw_hash, "salt": salt}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username:
            pw_hash = hashlib.sha256((req.password + u["salt"]).encode()).hexdigest()
            if pw_hash == u["pw_hash"]:
                token = str(uuid.uuid4())
                tokens[token] = uid
                return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/profiles/{profile_id}")
def get_profile(profile_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    profile = profiles.get(profile_id)
    if not profile:
        raise HTTPException(status_code=404, detail="Profile not found")
    return profile

@app.post("/profiles")
def create_profile(req: ProfileCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global next_profile_id
    profile_id = next_profile_id
    next_profile_id += 1
    profile = {"id": profile_id, "name": req.name, "user_id": user_id, "photo_count": 0}
    profiles[profile_id] = profile
    return profile

@app.get("/profiles/{profile_id}/photos/{photo_index}")
def get_profile_photo(profile_id: int, photo_index: int):
    profile = profiles.get(profile_id)
    if not profile:
        raise HTTPException(status_code=404, detail="Profile not found")
    filepath = os.path.join(PROFILE_PICS_DIR, f"profile_{profile_id}_photo_{photo_index}.jpg")
    if not os.path.exists(filepath):
        raise HTTPException(status_code=404, detail="Photo not found")

    img = Image.open(filepath)
    exif = img.getexif()
    orientation = exif.get(0x0112)

    buf = BytesIO()
    img.save(buf, format="JPEG", exif=exif if orientation else b"")
    buf.seek(0)

    return StreamingResponse(buf, media_type="image/jpeg")

