def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ListingCreate(BaseModel):
    title: str
    description: str = ""

class MediaCreate(BaseModel):
    filename: str

@app.post("/signup")
def signup(req: SignupRequest):
    global user_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_counter
    user_counter += 1
    users[req.username] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/listings")
def create_listing(listing: ListingCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global listing_counter
    listing_id = listing_counter
    listing_counter += 1
    listings[listing_id] = {"id": listing_id, "title": listing.title, "description": listing.description, "owner": user, "media": []}
    return listings[listing_id]

@app.get("/listings/{listing_id}")
def get_listing(listing_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if listing_id not in listings:
        raise HTTPException(status_code=404, detail="Listing not found")
    return listings[listing_id]

@app.post("/listings/{listing_id}/media")
