import uuid
import shutil
from datetime import datetime
from typing import Dict, Optional
from fastapi import FastAPI, HTTPException, Header, UploadFile, File, Form
from fastapi.responses import FileResponse

app = FastAPI()

# In-memory storage
users: Dict[int, dict] = {}
tokens: Dict[str, int] = {}
tickets: Dict[int, dict] = {}
next_user_id = 1
next_ticket_id = 1

# Ensure base directory exists
BASE_DIR = "support"
os.makedirs(BASE_DIR, exist_ok=True)

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str = Form(...), password: str = Form(...)):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str = Form(...), password: str = Form(...)):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = str(uuid.uuid4())
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/ticket")
def create_ticket(subject: str = Form(...), description: str = Form(...), authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_ticket_id
    ticket_id = next_ticket_id
    next_ticket_id += 1
    ticket_dir = os.path.join(BASE_DIR, str(ticket_id))
    os.makedirs(ticket_dir, exist_ok=True)
    tickets[ticket_id] = {"id": ticket_id, "subject": subject, "description": description, "user_id": user_id}
    return {"id": ticket_id, "subject": subject, "description": description}

@app.get("/ticket/{ticket_id}")
def get_ticket(ticket_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    ticket = tickets.get(ticket_id)
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    return ticket

@app.post("/ticket/{ticket_id}/attachments")
def upload_attachment(ticket_id: int, file: UploadFile = File(...), authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    ticket = tickets.get(ticket_id)
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    ticket_dir = os.path.join(BASE_DIR, str(ticket_id))
    os.makedirs(ticket_dir, exist_ok=True)
    file_path = os.path.join(ticket_dir, file.filename)
    with open(file_path, "wb") as f:
        shutil.copyfileobj(file.file, f)
    return {"filename": file.filename, "ticket_id": ticket_id}

@app.get("/ticket/{ticket_id}/attachments/{filename}")
def get_attachment(ticket_id: int, filename: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    ticket = tickets.get(ticket_id)
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    file_path = os.path.join(BASE_DIR, str(ticket_id), filename)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="File not found")
    # Log the view
    log_entry = f"{datetime.now().isoformat()} - Agent {user_id} viewed file {filename} in ticket {ticket_id}\n"
    log_file = os.path.join(BASE_DIR, "access.log")
    with open(log_file, "a") as f:
        f.write(log_entry)
    return FileResponse(file_path)

