from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
warehouses = {}
items = {}
next_user_id = 1
next_warehouse_id = 1
next_item_id = 1
next_audit_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="User exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": hashlib.sha256(password.encode()).hexdigest(), "role": "viewer"}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == hashlib.sha256(password.encode()).hexdigest():
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/warehouse")
def create_warehouse(name: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_warehouse_id
    wh_id = next_warehouse_id
    next_warehouse_id += 1
    warehouses[wh_id] = {"id": wh_id, "name": name, "admin_id": user_id, "admins": [user_id]}
    users[user_id]["role"] = "admin"
    return warehouses[wh_id]

@app.get("/warehouse/{warehouse_id}")
def get_warehouse(warehouse_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    wh = warehouses.get(warehouse_id)
    if not wh:
        raise HTTPException(status_code=404, detail="Not found")
    return wh

@app.post("/warehouse/{warehouse_id}/promote")
def promote_user(warehouse_id: int, user_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    wh = warehouses.get(warehouse_id)
    if not wh:
        raise HTTPException(status_code=404, detail="Warehouse not found")
    if current_user != wh["admin_id"]:
        raise HTTPException(status_code=403, detail="Only warehouse admin can promote")
    target = users.get(user_id)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if user_id not in wh["admins"]:
        wh["admins"].append(user_id)
    target["role"] = "admin"
    return {"msg": "Promoted", "user_id": user_id}

@app.post("/item")
def create_item(sku: str, warehouse_id: int, bin_location: str = "", reorder_point: int = 0, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    wh = warehouses.get(warehouse_id)
    if not wh:
        raise HTTPException(status_code=404, detail="Warehouse not found")
    if user_id not in wh["admins"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    global next_item_id, next_audit_id
    item_id = next_item_id
    next_item_id += 1
    audit_id = next_audit_id
    next_audit_id += 1
    items[item_id] = {
        "id": item_id,
        "sku": sku,
        "warehouse_id": warehouse_id,
        "bin_location": bin_location,
        "reorder_point": reorder_point,
        "audit_trail": [{"audit_id": audit_id, "action": "created", "user_id": user_id}]
    }
    return items[item_id]

@app.get("/item/{item_id}")
def get_item(item_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    item = items.get(item_id)
    if not item:
        raise HTTPException(status_code=404, detail="Not found")
    return item

@app.post("/item/{item_id}/audit")
def add_audit_entry(item_id: int, action: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    item = items.get(item_id)
    if not item:
        raise HTTPException(status_code=404, detail="Item not found")
    global next_audit_id
    audit_id = next_audit_id
    next_audit_id += 1
