from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict, List
import secrets
import time

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
stores = {}
categories = {}
deals = {}
click_tracking = {}
savings_history = {}
deal_hunters = set()

# ID counters
user_id_counter = 1
store_id_counter = 1
category_id_counter = 1
deal_id_counter = 1

# Auth helper
def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid auth")
    return tokens[token]

# Models
class SignupRequest(BaseModel):
    username: str
    favorite_stores: Optional[List[int]] = []
    favorite_categories: Optional[List[int]] = []

class LoginRequest(BaseModel):
    username: str

class StoreCreate(BaseModel):
    name: str

class CategoryCreate(BaseModel):
    name: str

class DealCreate(BaseModel):
    store_id: int
    category_id: int
    title: str
    description: str
    coupon_code: Optional[str] = None
    discount_percent: Optional[float] = None
    url: str

class ClickTrack(BaseModel):
    deal_id: int

# Endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "favorite_stores": req.favorite_stores,
        "favorite_categories": req.favorite_categories,
        "is_deal_hunter": False
    }
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=404, detail="User not found")

@app.post("/promote/{user_id}")
def promote_to_deal_hunter(user_id: int, authorization: Optional[str] = Header(None)):
    curator_id = get_current_user(authorization)
    # Assume any authenticated user can promote (MVP)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["is_deal_hunter"] = True
    deal_hunters.add(user_id)
    return {"message": f"User {user_id} promoted to deal hunter"}

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/stores")
def create_store(req: StoreCreate):
    global store_id_counter
    store_id = store_id_counter
    store_id_counter += 1
    stores[store_id] = {"id": store_id, "name": req.name}
    return stores[store_id]

@app.get("/stores/{store_id}")
def get_store(store_id: int):
    if store_id not in stores:
        raise HTTPException(status_code=404, detail="Store not found")
    return stores[store_id]

@app.post("/categories")
def create_category(req: CategoryCreate):
    global category_id_counter
    cat_id = category_id_counter
    category_id_counter += 1
    categories[cat_id] = {"id": cat_id, "name": req.name}
    return categories[cat_id]

@app.get("/categories/{category_id}")
def get_category(category_id: int):
    if category_id not in categories:
        raise HTTPException(status_code=404, detail="Category not found")
    return categories[category_id]

@app.post("/deals")
def create_deal(req: DealCreate, authorization: Optional[str] = Header(None)):
    global deal_id_counter
    user_id = get_current_user(authorization)
    if user_id not in deal_hunters:
        raise HTTPException(status_code=403, detail="Only deal hunters can submit deals")
    if req.store_id not in stores:
        raise HTTPException(status_code=400, detail="Invalid store_id")
    if req.category_id not in categories:
        raise HTTPException(status_code=400, detail="Invalid category_id")
    deal_id = deal_id_counter
    deal_id_counter += 1
    deals[deal_id] = {
        "id": deal_id,
        "store_id": req.store_id,
        "category_id": req.category_id,
        "title": req.title,
        "description": req.description,
        "coupon_code": req.coupon_code,
        "discount_percent": req.discount_percent,
        "url": req.url,
        "submitted_by": user_id,
        "verified": False,
        "clicks": 0
    }
    return deals[deal_id]

@app.get("/deals/{deal_id}")
def get_deal(deal_id: int):
    if deal_id not in deals:
        raise HTTPException(status_code=404, detail="Deal not found")
    return deals[deal_id]

@app.post("/deals/{deal_id}/verify")
def verify_deal(deal_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if user_id not in deal_hunters:
        raise HTTPException(status_code=403, detail="Only deal hunters can verify deals")
    if deal_id not in deals:
        raise HTTPException(status_code=404, detail="Deal not found")
    deals[deal_id]["verified"] = True
    return {"message": "Deal verified", "deal_id": deal_id}

@app.post("/clicks")
def track_click(req: ClickTrack, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if req.deal_id not in deals:
        raise HTTPException(status_code=404, detail="Deal not found")
    deals[req.deal_id]["clicks"] += 1
    click_key = f"{user_id}_{req.deal_id}"
    if click_key not in click_tracking:
        click_tracking[click_key] = {"user_id": user_id, "deal_id": req.deal_id, "count": 0}
    click_tracking[click_key]["count"] += 1
    return {"message": "Click tracked"}

@app.post("/savings")
def record_savings(deal_id: int, amount: float, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if deal_id not in deals:
        raise HTTPException(status_code=404, detail="Deal not found")
    key = f"{user_id}_{deal_id}"
    if key not in savings_history:
        savings_history[key] = {"user_id": user_id, "deal_id": deal_id, "total_saved": 0.0}
    savings_history[key]["total_saved"] += amount
    return savings_history[key]

@app.get("/users/{user_id}/savings")
def get_user_savings(user_id: int):
    user_savings = []
    for key, val in savings_history.items():
        if val["user_id"] == user_id:
            user_savings.append(val)
    return user_savings

@app.get("/deals")
def list_deals():
    return list(deals.values())

