        raise HTTPException(status_code=400, detail="Shift full")
    # Find volunteer record for this user
    volunteer = None
    for v in volunteers.values():
        if v["user_id"] == user_id:
            volunteer = v
            break
    if not volunteer:
        raise HTTPException(status_code=400, detail="No volunteer profile found. Create one first.")
    if volunteer["id"] in shift["assigned"]:
        raise HTTPException(status_code=400, detail="Already signed up")
    shift["assigned"].append(volunteer["id"])
    return {"message": "Signed up", "shift": shift}

