from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
from datetime import datetime
import secrets

app = FastAPI()

users = {}
reports = {}
tokens = {}
verifiers = {}
resolution_history = []

user_id_counter = 1
report_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ReportCreate(BaseModel):
    description: str
    location: str

class ReportUpdate(BaseModel):
    description: Optional[str] = None
    location: Optional[str] = None

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[req.username] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = user["username"]
    return {"token": token}

@app.post("/reports")
def create_report(report: ReportCreate, authorization: str = Header(None)):
    global report_id_counter
    username = get_current_user(authorization)
    report_id = report_id_counter
    report_id_counter += 1
    reports[report_id] = {
        "id": report_id,
        "description": report.description,
        "location": report.location,
        "reported_by": username,
        "status": "open",
        "created_at": datetime.now().isoformat()
    }
    resolution_history.append({
        "report_id": report_id,
        "action": "created",
        "by": username,
        "timestamp": datetime.now().isoformat()
    })
    return reports[report_id]

@app.get("/reports/{report_id}")
def get_report(report_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    report = reports.get(report_id)
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")
    return report

@app.get("/reports")
def list_reports(authorization: str = Header(None)):
    get_current_user(authorization)
    return list(reports.values())

@app.post("/reports/{report_id}/promote-verifier")
def promote_verifier(report_id: int, authorization: str = Header(None)):
    username = get_current_user(authorization)
    report = reports.get(report_id)
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")
    if report["status"] == "closed":
        raise HTTPException(status_code=400, detail="Report already closed")
    verifiers[username] = verifiers.get(username, []) + [report_id]
    resolution_history.append({
        "report_id": report_id,
        "action": "promoted_verifier",
        "by": username,
        "timestamp": datetime.now().isoformat()
    })
    return {"message": f"{username} promoted to verifier for report {report_id}"}

@app.post("/reports/{report_id}/confirm-match")
def confirm_match(report_id: int, authorization: str = Header(None)):
    username = get_current_user(authorization)
    report = reports.get(report_id)
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")
    if report["status"] == "closed":
        raise HTTPException(status_code=400, detail="Report already closed")
    if username not in verifiers or report_id not in verifiers[username]:
        raise HTTPException(status_code=403, detail="Not a verifier for this report")
    report["status"] = "closed"
    resolution_history.append({
        "report_id": report_id,
        "action": "confirmed_match",
        "by": username,
        "timestamp": datetime.now().isoformat()
    })
    return {"message": "Match confirmed and report closed"}

@app.get("/reports/{report_id}/history")
def get_history(report_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    report = reports.get(report_id)
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")
    return [h for h in resolution_history if h["report_id"] == report_id]

