import requests
import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Signup
    signup_resp = session.post(f"{BASE_URL}/signup", json={
        "username": "testuser",
        "password": "testpass"
    })
    if signup_resp.status_code != 200:
        return False
    user_data = signup_resp.json()
    if "id" not in user_data or "username" not in user_data:
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", json={
        "username": "testuser",
        "password": "testpass"
    })
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    # Create a report
    headers = {"Authorization": f"Bearer {token}"}
    create_resp = session.post(f"{BASE_URL}/reports", json={
        "description": "Test report",
        "location": "Test location"
    }, headers=headers)
    if create_resp.status_code != 200:
        return False
    report = create_resp.json()
    report_id = report.get("id")
    if not report_id:
        return False
    if report.get("reported_by") != "testuser":
        return False

    # Fetch the own report
    fetch_resp = session.get(f"{BASE_URL}/reports/{report_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    fetched_report = fetch_resp.json()
    if fetched_report.get("id") != report_id:
        return False
    if fetched_report.get("reported_by") != "testuser":
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

