from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets
import uuid

app = FastAPI()

users = {}
tokens = {}
carriers = {}
dispatchers = {}
drivers = {}
shipments = {}
delivery_history = {}

user_id_counter = 1
carrier_id_counter = 1
dispatcher_id_counter = 1
driver_id_counter = 1
shipment_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": username, "password": password, "role": "sender"}
    token = secrets.token_hex(16)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/carriers")
def create_carrier(name: str, authorization: Optional[str] = Header(None)):
    global carrier_id_counter
    user_id = get_current_user(authorization)
    carrier_id = carrier_id_counter
    carrier_id_counter += 1
    carriers[carrier_id] = {"id": carrier_id, "name": name, "owner_id": user_id, "dispatchers": []}
    return carriers[carrier_id]

@app.get("/carriers/{carrier_id}")
def get_carrier(carrier_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if carrier_id not in carriers:
        raise HTTPException(status_code=404, detail="Carrier not found")
    return carriers[carrier_id]

@app.post("/carriers/{carrier_id}/promote-dispatcher")
def promote_dispatcher(carrier_id: int, user_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if carrier_id not in carriers:
        raise HTTPException(status_code=404, detail="Carrier not found")
    if carriers[carrier_id]["owner_id"] != current_user:
        raise HTTPException(status_code=403, detail="Not carrier owner")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["role"] = "dispatcher"
    if user_id not in carriers[carrier_id]["dispatchers"]:
        carriers[carrier_id]["dispatchers"].append(user_id)
    return {"message": "User promoted to dispatcher"}

@app.post("/drivers")
def create_driver(name: str, authorization: Optional[str] = Header(None)):
    global driver_id_counter
    user_id = get_current_user(authorization)
    if users[user_id]["role"] != "dispatcher":
        raise HTTPException(status_code=403, detail="Only dispatchers can create drivers")
    driver_id = driver_id_counter
    driver_id_counter += 1
    drivers[driver_id] = {"id": driver_id, "name": name, "created_by": user_id}
    return drivers[driver_id]

@app.get("/drivers/{driver_id}")
def get_driver(driver_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if driver_id not in drivers:
        raise HTTPException(status_code=404, detail="Driver not found")
    return drivers[driver_id]

@app.post("/shipments")
def create_shipment(tracking_number: str, description: str = "", authorization: Optional[str] = Header(None)):
    global shipment_id_counter
    user_id = get_current_user(authorization)
    shipment_id = shipment_id_counter
    shipment_id_counter += 1
    shipments[shipment_id] = {
        "id": shipment_id,
        "tracking_number": tracking_number,
        "description": description,
        "sender_id": user_id,
        "assigned_driver_id": None,
        "status": "created"
    }
    delivery_history[shipment_id] = [{"status": "created", "timestamp": "now"}]
    return shipments[shipment_id]

@app.get("/shipments/{shipment_id}")
def get_shipment(shipment_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    return shipments[shipment_id]

