    admin_ids = [uid for uid, u in users.items() if u.get("role") == "admin"]
    if min(admin_ids) != admin_id:
        raise HTTPException(status_code=403, detail="Only the first admin can promote")
    if req.role not in ("fulfiller", "manager"):
        raise HTTPException(status_code=400, detail="Role must be 'fulfiller' or 'manager'")
    target = users.get(user_id)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    target["role"] = req.role
    target["promoted_by"] = admin_id
    if req.expiration:
        try:
            target["promotion_expires"] = datetime.fromisoformat(req.expiration)
        except:
            raise HTTPException(status_code=400, detail="Invalid expiration date format")
    else:
        target["promotion_expires"] = None
    return {"message": f"User {user_id} promoted to {req.role}"}

