    user_id = get_current_user(authorization)
    global next_profile_id
    pid = next_profile_id
    next_profile_id += 1
    profiles[pid] = {"id": pid, "user_id": user_id, "name": profile.name, "age": profile.age, "bio": profile.bio}
    return {"profile_id": pid}

@app.get("/profile/{profile_id}")
def get_profile(profile_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if profile_id not in profiles:
        raise HTTPException(status_code=404, detail="Profile not found")
    return profiles[profile_id]

@app.post("/swipe")
def swipe(target_id: int, direction: str, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if target_id not in profiles:
        raise HTTPException(status_code=404, detail="Target profile not found")
    if user_id not in swipes:
        swipes[user_id] = {"count": 0, "last_reset": datetime.now()}
    user_swipes = swipes[user_id]
    user = users[user_id]
    if user.get("role") != "premium":
        if (datetime.now() - user_swipes["last_reset"]).seconds > 86400:
            user_swipes["count"] = 0
            user_swipes["last_reset"] = datetime.now()
        if user_swipes["count"] >= 10:
            raise HTTPException(status_code=403, detail="Daily swipe limit reached")
        user_swipes["count"] += 1
    return {"message": f"Swiped {direction} on profile {target_id}"}

