from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import secrets
from datetime import datetime

app = FastAPI()

# In-memory storage
users = {}
sessions = {}
goals = {}
mentors = {}
programs = {}
tokens = {}
next_ids = {"users": 1, "sessions": 1, "goals": 1, "mentors": 1, "programs": 1}
program_admins = set()

# Auth helpers
def get_user_from_token(authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(401, "Invalid token")

# Models
class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class SessionCreate(BaseModel):
    title: str
    mentor_id: int
    industry_tags: List[str] = []
    experience_level: str = "beginner"

class GoalCreate(BaseModel):
    session_id: int
    description: str
    target_date: Optional[str] = None

class MenteeProgress(BaseModel):
    goal_id: int
    status: str = "in_progress"
    notes: Optional[str] = None

class MentorCreate(BaseModel):
    name: str
    bio: Optional[str] = None
    expertise: List[str] = []

class ProgramCreate(BaseModel):
    name: str
    description: Optional[str] = None

# Endpoints
@app.post("/signup")
def signup(user: UserSignup):
    uid = next_ids["users"]
    users[uid] = {"id": uid, "username": user.username, "password": user.password}
    token = secrets.token_hex(16)
    tokens[uid] = token
    next_ids["users"] += 1
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            token = secrets.token_hex(16)
            tokens[uid] = token
            return {"user_id": uid, "token": token}
    raise HTTPException(401, "Invalid credentials")

@app.post("/mentors")
def create_mentor(mentor: MentorCreate, authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    mid = next_ids["mentors"]
    mentors[mid] = {
        "id": mid,
        "name": mentor.name,
        "bio": mentor.bio,
        "expertise": mentor.expertise,
        "created_by": user_id,
        "is_admin": False
    }
    next_ids["mentors"] += 1
    # First mentor becomes admin
    if len(mentors) == 1:
        mentors[mid]["is_admin"] = True
        program_admins.add(mid)
    return mentors[mid]

@app.get("/mentors/{mentor_id}")
def get_mentor(mentor_id: int):
    if mentor_id not in mentors:
        raise HTTPException(404, "Mentor not found")
    return mentors[mentor_id]

@app.post("/programs")
def create_program(program: ProgramCreate, authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    pid = next_ids["programs"]
    programs[pid] = {
        "id": pid,
        "name": program.name,
        "description": program.description,
        "created_by": user_id,
        "members": []
    }
    next_ids["programs"] += 1
    return programs[pid]

@app.get("/programs/{program_id}")
def get_program(program_id: int):
    if program_id not in programs:
        raise HTTPException(404, "Program not found")
