from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
subscriptions = {}
orders = {}
subscription_tiers = {"basic": 9.99, "premium": 19.99, "deluxe": 29.99}
next_user_id = 1
next_subscription_id = 1
next_order_id = 1
curators = set()

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str, flavor_preferences: str, shipping_address: str, tier: str = "basic"):
    global next_user_id
    if tier not in subscription_tiers:
        raise HTTPException(status_code=400, detail="Invalid tier")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": username,
        "password": password,
        "flavor_preferences": flavor_preferences,
        "shipping_address": shipping_address,
        "tier": tier,
        "role": "customer"
    }
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/subscribe")
def subscribe(user_id: int, tier: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if tier not in subscription_tiers:
        raise HTTPException(status_code=400, detail="Invalid tier")
    global next_subscription_id
    sub_id = next_subscription_id
    next_subscription_id += 1
    subscriptions[sub_id] = {
        "id": sub_id,
        "user_id": user_id,
        "tier": tier,
        "active": True
    }
    users[user_id]["tier"] = tier
    return {"subscription_id": sub_id, "message": "Subscribed"}

@app.get("/subscription/{subscription_id}")
def get_subscription(subscription_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    sub = subscriptions.get(subscription_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    return sub

@app.post("/order")
def create_order(user_id: int, items: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    global next_order_id
    order_id = next_order_id
    next_order_id += 1
    orders[order_id] = {
        "id": order_id,
        "user_id": user_id,
        "items": items,
        "status": "pending"
    }
    return {"order_id": order_id}

@app.get("/order/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order

@app.post("/promote/{user_id}")
def promote_to_curator(user_id: int, authorization: Optional[str] = Header(None)):
    owner_id = get_current_user(authorization)
    # In MVP, first user is owner
    if owner_id != 1:
        raise HTTPException(status_code=403, detail="Only owner can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["role"] = "curator"
    curators.add(user_id)
    return {"message": f"User {user_id} promoted to curator"}

@app.get("/curator/revenue")
def get_monthly_revenue(authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if user_id not in curators and user_id != 1:
        raise HTTPException(status_code=403, detail="Not a curator")
    total = sum(subscription_tiers[sub["tier"]] for sub in subscriptions.values() if sub["active"])
    return {"monthly_revenue": total}

