    next_subscription_id += 1
    subscriptions[sub_id] = {
        "id": sub_id,
        "user_id": user_id,
        "tier": tier,
        "active": True
    }
    users[user_id]["tier"] = tier
    return {"subscription_id": sub_id, "message": "Subscribed"}

@app.get("/subscription/{subscription_id}")
def get_subscription(subscription_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    sub = subscriptions.get(subscription_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    if sub["user_id"] != current_user_id:
        raise HTTPException(status_code=403, detail="Not authorized to view this subscription")
    return sub

@app.post("/order")
def create_order(user_id: int, items: str, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if current_user_id != user_id:
        raise HTTPException(status_code=403, detail="Cannot create order for another user")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    global next_order_id
    order_id = next_order_id
    next_order_id += 1
    orders[order_id] = {
        "id": order_id,
        "user_id": user_id,
        "items": items,
        "status": "pending"
    }
    return {"order_id": order_id}

@app.get("/order/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    if order["user_id"] != current_user_id:
        raise HTTPException(status_code=403, detail="Not authorized to view this order")
    return order

@app.post("/promote/{user_id}")
def promote_to_curator(user_id: int, authorization: Optional[str] = Header(None)):
    owner_id = get_current_user(authorization)
    # In MVP, first user is owner
    if owner_id != 1:
        raise HTTPException(status_code=403, detail="Only owner can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["role"] = "curator"
    curators.add(user_id)
    return {"message": f"User {user_id} promoted to curator"}

@app.get("/curator/revenue")
def get_monthly_revenue(authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if user_id not in curators and user_id != 1:
        raise HTTPException(status_code=403, detail="Not a curator")
    total = sum(subscription_tiers[sub["tier"]] for sub in subscriptions.values() if sub["active"])
    return {"monthly_revenue": total}

