    if not r:
        raise HTTPException(status_code=404, detail="Rating not found")
    return r

@app.get("/ratings")
def list_ratings(vinyl_id: Optional[int] = None):
    if vinyl_id:
        return [r for r in ratings.values() if r["vinyl_id"] == vinyl_id]
    return list(ratings.values())

@app.post("/promote/{user_id}")
def promote_seller(user_id: int, authorization: str = Header(None)):
    admin_id = get_user_from_token(authorization)
    require_admin(admin_id)
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    user["verified_seller"] = True
    return {"message": f"User {user_id} is now a verified seller"}

@app.get("/users/{user_id}")
def get_user(user_id: int):
    u = users.get(user_id)
    if not u:
        raise HTTPException(status_code=404, detail="User not found")
    return {k: v for k, v in u.items() if k != "password"}

@app.get("/sale-history/{seller_id}")
def sale_history(seller_id: int):
    return [o for o in orders.values() if o["seller_id"] == seller_id]

