from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List, Dict
from datetime import datetime
import secrets

app = FastAPI()

# In-memory stores
users = {}
trips = {}
activities = {}
hotels = {}
bookings = {}
change_logs = []
tokens = {}
next_user_id = 1
next_trip_id = 1
next_activity_id = 1
next_hotel_id = 1
next_booking_id = 1
next_log_id = 1

class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class TripCreate(BaseModel):
    destination: str
    start_date: str
    end_date: str
    budget_cap: float

class ActivityCreate(BaseModel):
    trip_id: int
    name: str
    date: str
    cost: float

class HotelCreate(BaseModel):
    trip_id: int
    name: str
    check_in: str
    check_out: str
    cost: float

class BookingCreate(BaseModel):
    trip_id: int
    activity_id: Optional[int] = None
    hotel_id: Optional[int] = None

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid token")
    token = authorization.split(" ")[1]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

def log_change(user_id: int, resource_type: str, resource_id: int, action: str, details: str):
    global next_log_id
    change_logs.append({
        "log_id": next_log_id,
        "user_id": user_id,
        "resource_type": resource_type,
        "resource_id": resource_id,
        "action": action,
        "details": details,
        "timestamp": datetime.now().isoformat()
    })
    next_log_id += 1

@app.post("/signup")
def signup(user: UserSignup):
    global next_user_id
    if any(u["username"] == user.username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    users[user_id] = {"id": user_id, "username": user.username, "password": user.password, "role": "owner"}
    next_user_id += 1
    return {"id": user_id, "username": user.username}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/trips")
def create_trip(trip: TripCreate, authorization: str = Header(...)):
    global next_trip_id
    user_id = get_current_user(authorization)
    trip_id = next_trip_id
    trips[trip_id] = {
        "id": trip_id,
        "destination": trip.destination,
        "start_date": trip.start_date,
        "end_date": trip.end_date,
        "budget_cap": trip.budget_cap,
        "owner_id": user_id,
        "collaborators": [user_id],
        "editors": [user_id]
    }
    next_trip_id += 1
    log_change(user_id, "trip", trip_id, "created", f"Trip to {trip.destination} created")
    return trips[trip_id]

@app.get("/trips/{trip_id}")
def get_trip(trip_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if user_id not in trip["collaborators"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    return trip

@app.post("/promote/{user_id}")
def promote_to_editor(user_id: int, trip_id: int, authorization: str = Header(...)):
    current_user = get_current_user(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if trip["owner_id"] != current_user:
        raise HTTPException(status_code=403, detail="Only trip owner can promote")
    if user_id not in trip["collaborators"]:
        raise HTTPException(status_code=400, detail="User is not a collaborator")
    if user_id not in trip["editors"]:
        trip["editors"].append(user_id)
    log_change(current_user, "trip", trip_id, "promoted", f"User {user_id} promoted to editor")
    return {"message": f"User {user_id} promoted to editor"}

@app.post("/activities")
def create_activity(activity: ActivityCreate, authorization: str = Header(...)):
    global next_activity_id
    user_id = get_current_user(authorization)
    trip = trips.get(activity.trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if user_id not in trip["editors"]:
        raise HTTPException(status_code=403, detail="Only editors can add activities")
    activity_id = next_activity_id
    activities[activity_id] = {
        "id": activity_id,
        "trip_id": activity.trip_id,
        "name": activity.name,
        "date": activity.date,
        "cost": activity.cost,
        "created_by": user_id
    }
    next_activity_id += 1
    log_change(user_id, "activity", activity_id, "created", f"Activity {activity.name} added to trip {activity.trip_id}")
    return activities[activity_id]

@app.get("/activities/{activity_id}")
def get_activity(activity_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    activity = activities.get(activity_id)
    if not activity:
        raise HTTPException(status_code=404, detail="Activity not found")
    trip = trips.get(activity["trip_id"])
    if not trip or user_id not in trip["collaborators"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    return activity

@app.post("/hotels")
def create_hotel(hotel: HotelCreate, authorization: str = Header(...)):
    global next_hotel_id
    user_id = get_current_user(authorization)
    trip = trips.get(hotel.trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if user_id not in trip["editors"]:
        raise HTTPException(status_code=403, detail="Only editors can add hotels")
    hotel_id = next_hotel_id
    hotels[hotel_id] = {
        "id": hotel_id,
        "trip_id": hotel.trip_id,
        "name": hotel.name,
        "check_in": hotel.check_in,
        "check_out": hotel.check_out,
        "cost": hotel.cost,
        "created_by": user_id
    }
    next_hotel_id += 1
    log_change(user_id, "hotel", hotel_id, "created", f"Hotel {hotel.name} added to trip {hotel.trip_id}")
    return hotels[hotel_id]

@app.get("/hotels/{hotel_id}")
def get_hotel(hotel_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    hotel = hotels.get(hotel_id)
    if not hotel:
        raise HTTPException(status_code=404, detail="Hotel not found")
    trip = trips.get(hotel["trip_id"])
    if not trip or user_id not in trip["collaborators"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    return hotel

@app.post("/bookings")
def create_booking(booking: BookingCreate, authorization: str = Header(...)):
    global next_booking_id
    user_id = get_current_user(authorization)
    trip = trips.get(booking.trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if user_id not in trip["editors"]:
        raise HTTPException(status_code=403, detail="Only editors can create bookings")
    if booking.activity_id and booking.activity_id not in activities:
        raise HTTPException(status_code=400, detail="Activity not found")
    if booking.hotel_id and booking.hotel_id not in hotels:
        raise HTTPException(status_code=400, detail="Hotel not found")
    booking_id = next_booking_id
    bookings[booking_id] = {
        "id": booking_id,
        "trip_id": booking.trip_id,
        "activity_id": booking.activity_id,
        "hotel_id": booking.hotel_id,
        "created_by": user_id
    }
    next_booking_id += 1
    log_change(user_id, "booking", booking_id, "created", f"Booking created for trip {booking.trip_id}")
    return bookings[booking_id]

@app.get("/bookings/{booking_id}")
def get_booking(booking_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    booking = bookings.get(booking_id)
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    trip = trips.get(booking["trip_id"])
    if not trip or user_id not in trip["collaborators"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    return booking

@app.get("/change_logs")
def get_change_logs(authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    return change_logs

