class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class TripCreate(BaseModel):
    destination: str
    start_date: str
    end_date: str
    budget_cap: float

class ActivityCreate(BaseModel):
    trip_id: int
    name: str
    date: str
    cost: float

class HotelCreate(BaseModel):
    trip_id: int
    name: str
    check_in: str
    check_out: str
    cost: float

class BookingCreate(BaseModel):
    trip_id: int
    activity_id: Optional[int] = None
    hotel_id: Optional[int] = None

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid token")
    token = authorization.split(" ")[1]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

def log_change(user_id: int, resource_type: str, resource_id: int, action: str, details: str):
    global next_log_id
    change_logs.append({
        "log_id": next_log_id,
        "user_id": user_id,
        "resource_type": resource_type,
        "resource_id": resource_id,
        "action": action,
        "details": details,
        "timestamp": datetime.now().isoformat()
    })
    next_log_id += 1

@app.post("/signup")
def signup(user: UserSignup):
    global next_user_id
    if any(u["username"] == user.username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    users[user_id] = {"id": user_id, "username": user.username, "password": user.password, "role": "owner"}
    next_user_id += 1
    return {"id": user_id, "username": user.username}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/trips")
def create_trip(trip: TripCreate, authorization: str = Header(...)):
    global next_trip_id
    user_id = get_current_user(authorization)
    trip_id = next_trip_id
    trips[trip_id] = {
        "id": trip_id,
        "destination": trip.destination,
        "start_date": trip.start_date,
        "end_date": trip.end_date,
        "budget_cap": trip.budget_cap,
        "owner_id": user_id,
        "collaborators": [user_id],
        "editors": [user_id]
    }
    next_trip_id += 1
    log_change(user_id, "trip", trip_id, "created", f"Trip to {trip.destination} created")
    return trips[trip_id]

@app.get("/trips/{trip_id}")
def get_trip(trip_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if user_id not in trip["collaborators"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    return trip

@app.post("/promote/{user_id}")
def promote_to_editor(user_id: int, trip_id: int, authorization: str = Header(...)):
    current_user = get_current_user(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if trip["owner_id"] != current_user:
        raise HTTPException(status_code=403, detail="Only trip owner can promote")
    if user_id not in trip["collaborators"]:
        raise HTTPException(status_code=400, detail="User is not a collaborator")
    if user_id not in trip["editors"]:
        trip["editors"].append(user_id)
    log_change(current_user, "trip", trip_id, "promoted", f"User {user_id} promoted to editor")
    return {"message": f"User {user_id} promoted to editor"}

@app.post("/activities")
def create_activity(activity: ActivityCreate, authorization: str = Header(...)):
    global next_activity_id
    user_id = get_current_user(authorization)
    trip = trips.get(activity.trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    if user_id not in trip["editors"]:
        raise HTTPException(status_code=403, detail="Only editors can add activities")
    activity_id = next_activity_id
    activities[activity_id] = {
        "id": activity_id,
        "trip_id": activity.trip_id,
        "name": activity.name,
        "date": activity.date,
        "cost": activity.cost,
        "created_by": user_id
    }
    next_activity_id += 1
