from typing import Optional
import random
import string

app = FastAPI()

users = {}
next_user_id = 1
tokens = {}
questions = {}
next_question_id = 1
subjects = {}
next_subject_id = 1
difficulties = {}
next_difficulty_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, interests: str = ""):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    role = "admin" if user_id == 1 else "student"
    users[user_id] = {
        "id": user_id,
        "username": username,
        "interests": interests,
        "role": role
    }
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token, "role": role}

@app.post("/login")
def login(username: str):
    for uid, u in users.items():
        if u["username"] == username:
            token = generate_token()
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=404, detail="User not found")

@app.post("/promote/{user_id}")
def promote_user(user_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] != "admin":
        raise HTTPException(status_code=403, detail="Only admin can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["role"] = "question_curator"
    return {"message": f"User {user_id} promoted to question_curator"}

@app.post("/subjects")
def create_subject(name: str, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] not in ["admin", "question_curator"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    global next_subject_id
    sid = next_subject_id
    next_subject_id += 1
    subjects[sid] = {"id": sid, "name": name}
    return subjects[sid]

@app.get("/subjects/{subject_id}")
def get_subject(subject_id: int):
    if subject_id not in subjects:
        raise HTTPException(status_code=404, detail="Subject not found")
    return subjects[subject_id]

@app.post("/difficulties")
def create_difficulty(level: str, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] not in ["admin", "question_curator"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    global next_difficulty_id
    did = next_difficulty_id
    next_difficulty_id += 1
    difficulties[did] = {"id": did, "level": level}
    return difficulties[did]

@app.get("/difficulties/{difficulty_id}")
def get_difficulty(difficulty_id: int):
    if difficulty_id not in difficulties:
        raise HTTPException(status_code=404, detail="Difficulty not found")
    return difficulties[difficulty_id]

@app.post("/questions")
def create_question(question_text: str, answer: str, subject_id: int, difficulty_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] not in ["admin", "question_curator"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    if subject_id not in subjects:
        raise HTTPException(status_code=404, detail="Subject not found")
    if difficulty_id not in difficulties:
        raise HTTPException(status_code=404, detail="Difficulty not found")
    global next_question_id
    qid = next_question_id
    next_question_id += 1
    questions[qid] = {
        "id": qid,
        "question_text": question_text,
        "answer": answer,
        "subject_id": subject_id,
        "difficulty_id": difficulty_id,
        "approved": False,
        "created_by": current_user_id
    }
    return questions[qid]

@app.post("/questions/{question_id}/approve")
def approve_question(question_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] not in ["admin", "question_curator"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    if question_id not in questions:
        raise HTTPException(status_code=404, detail="Question not found")
    questions[question_id]["approved"] = True
    return {"message": "Question approved"}

@app.get("/questions/{question_id}")
def get_question(question_id: int):
    if question_id not in questions:
        raise HTTPException(status_code=404, detail="Question not found")
    return questions[question_id]

@app.get("/daily")
def get_daily_question(authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    user = users[current_user_id]
    approved = [q for q in questions.values() if q["approved"]]
    if not approved:
        raise HTTPException(status_code=404, detail="No approved questions available")
    if user["interests"]:
        interest_subjects = [s["id"] for s in subjects.values() if s["name"].lower() in user["interests"].lower()]
        if interest_subjects:
            filtered = [q for q in approved if q["subject_id"] in interest_subjects]
            if filtered:
                return random.choice(filtered)
    return random.choice(approved)

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/users")
def create_user(username: str, interests: str = ""):
    return signup(username, interests)

