from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
clubs = {}
reading_lists = {}
discussions = {}
next_user_id = 1
next_club_id = 1
next_list_id = 1
next_discussion_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password, "reading_history": []}
    return {"user_id": user_id}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/user/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/user")
def create_user(username: str, password: str):
    return signup(username, password)

@app.post("/club")
def create_club(name: str, authorization: Optional[str] = Header(None)):
    creator_id = get_current_user(authorization)
    global next_club_id
    club_id = next_club_id
    next_club_id += 1
    clubs[club_id] = {"id": club_id, "name": name, "creator_id": creator_id, "moderators": [creator_id], "members": [creator_id]}
    return {"club_id": club_id}

@app.get("/club/{club_id}")
def get_club(club_id: int):
    if club_id not in clubs:
        raise HTTPException(status_code=404, detail="Club not found")
    return clubs[club_id]

@app.post("/promote/{user_id}")
def promote_to_moderator(user_id: int, club_id: int, authorization: Optional[str] = Header(None)):
    requester_id = get_current_user(authorization)
    if club_id not in clubs:
        raise HTTPException(status_code=404, detail="Club not found")
    club = clubs[club_id]
    if requester_id != club["creator_id"]:
        raise HTTPException(status_code=403, detail="Only creator can promote")
    if user_id not in club["members"]:
        raise HTTPException(status_code=400, detail="User is not a member")
    if user_id not in club["moderators"]:
        club["moderators"].append(user_id)
    return {"status": "promoted"}

@app.post("/reading-list")
def create_reading_list(name: str, club_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_list_id
    list_id = next_list_id
    next_list_id += 1
    reading_lists[list_id] = {"id": list_id, "name": name, "club_id": club_id, "owner_id": user_id, "books": [], "progress": {}}
    return {"list_id": list_id}

@app.get("/reading-list/{list_id}")
def get_reading_list(list_id: int):
    if list_id not in reading_lists:
        raise HTTPException(status_code=404, detail="Reading list not found")
    return reading_lists[list_id]

@app.post("/reading-list/{list_id}/progress")
def update_progress(list_id: int, book_title: str, pages_read: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if list_id not in reading_lists:
        raise HTTPException(status_code=404, detail="Reading list not found")
    rl = reading_lists[list_id]
    if rl["owner_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your list")
    rl["progress"][book_title] = pages_read
