from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import secrets
import time

app = FastAPI()

users = {}
businesses = {}
reviews = {}
booking_requests = {}
tokens = {}
next_user_id = 1
next_business_id = 1
next_review_id = 1
next_booking_id = 1

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str
    role: str = "business_owner"

class LoginRequest(BaseModel):
    username: str
    password: str

class BusinessCreate(BaseModel):
    name: str
    category: str
    service_areas: List[str]
    price_range: str
    description: Optional[str] = None

class ReviewCreate(BaseModel):
    business_id: int
    rating: int
    comment: Optional[str] = None

class BookingCreate(BaseModel):
    business_id: int
    message: Optional[str] = None

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password,
        "role": req.role,
        "created_at": time.time()
    }
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/businesses")
def create_business(biz: BusinessCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global next_business_id
    biz_id = next_business_id
    next_business_id += 1
    businesses[biz_id] = {
        "id": biz_id,
        "owner_id": user_id,
        "name": biz.name,
        "category": biz.category,
        "service_areas": biz.service_areas,
        "price_range": biz.price_range,
        "description": biz.description,
        "featured": False,
        "created_at": time.time()
    }
    return businesses[biz_id]

@app.get("/businesses/{business_id}")
def get_business(business_id: int):
    if business_id not in businesses:
        raise HTTPException(status_code=404, detail="Business not found")
    return businesses[business_id]

@app.get("/businesses")
def search_businesses(category: Optional[str] = None, service_area: Optional[str] = None, price_range: Optional[str] = None):
    results = list(businesses.values())
    if category:
        results = [b for b in results if b["category"].lower() == category.lower()]
    if service_area:
        results = [b for b in results if service_area.lower() in [a.lower() for a in b["service_areas"]]]
    if price_range:
        results = [b for b in results if b["price_range"].lower() == price_range.lower()]
    results.sort(key=lambda b: (not b["featured"], b["id"]))
    return results

@app.post("/promote/{user_id}")
def promote_business(user_id: int, authorization: str = Header(None)):
    admin_id = get_current_user(authorization)
    admin = users.get(admin_id)
    if not admin or admin["role"] != "city_admin":
        raise HTTPException(status_code=403, detail="Only city admins can promote")
    promoted = []
    for biz_id, biz in businesses.items():
        if biz["owner_id"] == user_id:
            biz["featured"] = True
            promoted.append(biz)
    if not promoted:
        raise HTTPException(status_code=404, detail="No businesses found for this user")
    return {"message": "Businesses promoted", "businesses": promoted}

@app.post("/reviews")
def create_review(review: ReviewCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if review.business_id not in businesses:
        raise HTTPException(status_code=404, detail="Business not found")
    global next_review_id
    rev_id = next_review_id
    next_review_id += 1
    reviews[rev_id] = {
        "id": rev_id,
        "user_id": user_id,
        "business_id": review.business_id,
        "rating": review.rating,
        "comment": review.comment,
        "created_at": time.time()
    }
    return reviews[rev_id]

@app.get("/reviews/{review_id}")
def get_review(review_id: int):
    if review_id not in reviews:
        raise HTTPException(status_code=404, detail="Review not found")
    return reviews[review_id]

@app.get("/reviews")
def get_reviews_for_business(business_id: int):
    return [r for r in reviews.values() if r["business_id"] == business_id]

@app.post("/booking_requests")
def create_booking(booking: BookingCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if booking.business_id not in businesses:
        raise HTTPException(status_code=404, detail="Business not found")
    global next_booking_id
    bk_id = next_booking_id
    next_booking_id += 1
    booking_requests[bk_id] = {
        "id": bk_id,
        "user_id": user_id,
        "business_id": booking.business_id,
        "message": booking.message,
        "status": "pending",
        "created_at": time.time()
    }
    return booking_requests[bk_id]

@app.get("/booking_requests/{booking_id}")
def get_booking(booking_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if booking_id not in booking_requests:
        raise HTTPException(status_code=404, detail="Booking not found")
    booking = booking_requests[booking_id]
    business = businesses.get(booking["business_id"])
    if booking["user_id"] != user_id and (not business or business["owner_id"] != user_id):
        raise HTTPException(status_code=403, detail="Not authorized to view this booking")
    return booking

@app.get("/booking_requests")
def get_booking_requests_for_business(business_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    business = businesses.get(business_id)
    if not business or business["owner_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not authorized to view these bookings")
    return [b for b in booking_requests.values() if b["business_id"] == business_id]

