from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets
import datetime

app = FastAPI()

users = {}
doctors = {}
patients = {}
appointments = {}
notes = {}
tokens = {}
counters = {"users": 0, "doctors": 0, "patients": 0, "appointments": 0, "notes": 0}

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(401, "No auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(401, "Invalid token")
    return tokens[token]["user_id"]

def get_doctor(user_id: int):
    if user_id not in doctors:
        raise HTTPException(403, "Not a doctor")
    return doctors[user_id]

@app.post("/signup")
def signup(name: str, email: str, password: str, role: str = "patient"):
    counters["users"] += 1
    user_id = counters["users"]
    users[user_id] = {"id": user_id, "name": name, "email": email, "password": password, "role": role}
    if role == "patient":
        counters["patients"] += 1
        patients[user_id] = {"user_id": user_id, "appointments": []}
    return {"user_id": user_id}

@app.post("/login")
def login(email: str, password: str):
    for uid, u in users.items():
        if u["email"] == email and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = {"user_id": uid, "expires": datetime.datetime.now() + datetime.timedelta(days=30)}
            return {"token": token}
    raise HTTPException(401, "Invalid credentials")

@app.post("/promote/{user_id}")
def promote(user_id: int, authorization: Optional[str] = Header(None)):
    admin_id = get_current_user(authorization)
    # any staff can promote
    if users[admin_id]["role"] not in ("staff", "admin"):
        raise HTTPException(403, "Only staff can promote")
    if user_id not in users:
        raise HTTPException(404, "User not found")
    users[user_id]["role"] = "doctor"
    if user_id not in doctors:
        counters["doctors"] += 1
        doctors[user_id] = {"user_id": user_id, "patients": []}
    return {"message": "Promoted", "user_id": user_id}

@app.post("/appointments")
def create_appointment(patient_id: int, doctor_id: int, time: str, reason: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if user_id != patient_id and users[user_id]["role"] not in ("staff", "admin", "doctor"):
        raise HTTPException(403, "Not authorized")
    if patient_id not in patients:
        raise HTTPException(404, "Patient not found")
    if doctor_id not in doctors:
        raise HTTPException(404, "Doctor not found")
    counters["appointments"] += 1
    appt_id = counters["appointments"]
    appointments[appt_id] = {
        "id": appt_id,
        "patient_id": patient_id,
        "doctor_id": doctor_id,
        "time": time,
        "reason": reason,
        "status": "scheduled"
    }
    patients[patient_id]["appointments"].append(appt_id)
    return appointments[appt_id]

@app.get("/appointments/{appt_id}")
def get_appointment(appt_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if appt_id not in appointments:
        raise HTTPException(404, "Appointment not found")
    return appointments[appt_id]

@app.get("/patients/{patient_id}/appointments")
def get_patient_appointments(patient_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if patient_id not in patients:
        raise HTTPException(404, "Patient not found")
    appt_ids = patients[patient_id]["appointments"]
    return [appointments[aid] for aid in appt_ids]

@app.post("/notes")
def create_note(appointment_id: int, content: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    doctor = get_doctor(user_id)
    if appointment_id not in appointments:
        raise HTTPException(404, "Appointment not found")
    if appointments[appointment_id]["doctor_id"] != user_id:
        raise HTTPException(403, "Not your appointment")
    counters["notes"] += 1
    note_id = counters["notes"]
    notes[note_id] = {
        "id": note_id,
        "appointment_id": appointment_id,
        "doctor_id": user_id,
        "content": content,
        "created_at": str(datetime.datetime.now())
    }
    return notes[note_id]

@app.get("/notes/{note_id}")
def get_note(note_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if note_id not in notes:
        raise HTTPException(404, "Note not found")
    return notes[note_id]

@app.get("/patients/{patient_id}")
def get_patient(patient_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if patient_id not in patients:
        raise HTTPException(404, "Patient not found")
    return patients[patient_id]

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    current = get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(404, "User not found")
    u = users[user_id].copy()
    u.pop("password", None)
    return u

