from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List, Dict
import secrets
import datetime

app = FastAPI()

users = {}
tokens = {}
trails = {}
hikes = {}
gear_checklists = {}
weather_alerts = []
trail_conditions = {}
trail_closures = {}
next_user_id = 1
next_trail_id = 1
next_hike_id = 1
next_gear_id = 1
next_alert_id = 1

class UserCreate(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class TrailCreate(BaseModel):
    name: str
    difficulty: str
    length_km: float
    description: Optional[str] = None

class HikeCreate(BaseModel):
    trail_id: int
    user_id: int
    notes: Optional[str] = None
    photo_urls: Optional[List[str]] = None

class GearChecklistCreate(BaseModel):
    trail_id: int
    items: List[str]

class WeatherAlertCreate(BaseModel):
    trail_id: int
    alert: str
    severity: str

class ConditionUpdate(BaseModel):
    trail_id: int
    condition: str

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

def require_steward(user):
    if not user.get("is_steward"):
        raise HTTPException(status_code=403, detail="Not a trail steward")

@app.post("/signup")
def signup(user: UserCreate):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {
        "id": uid,
        "username": user.username,
        "password": user.password,
        "is_steward": False
    }
    return {"user_id": uid, "message": "User created"}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            token = secrets.token_hex(16)
            tokens[token] = u
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/promote/{user_id}")
def promote_user(user_id: int, authorization: str = Header(None)):
    admin = get_current_user(authorization)
    if admin.get("username") != "admin":
        raise HTTPException(status_code=403, detail="Only admin can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["is_steward"] = True
    return {"message": f"User {user_id} promoted to trail steward"}

@app.post("/trails")
def create_trail(trail: TrailCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global next_trail_id
    tid = next_trail_id
    next_trail_id += 1
    trails[tid] = {
        "id": tid,
        "name": trail.name,
        "difficulty": trail.difficulty,
        "length_km": trail.length_km,
        "description": trail.description,
        "created_by": user["id"]
    }
    return trails[tid]

@app.get("/trails/{trail_id}")
def get_trail(trail_id: int):
    if trail_id not in trails:
        raise HTTPException(status_code=404, detail="Trail not found")
    return trails[trail_id]

@app.post("/hikes")
def create_hike(hike: HikeCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if hike.trail_id not in trails:
        raise HTTPException(status_code=404, detail="Trail not found")
    global next_hike_id
    hid = next_hike_id
    next_hike_id += 1
    hikes[hid] = {
        "id": hid,
        "trail_id": hike.trail_id,
        "user_id": hike.user_id,
        "notes": hike.notes,
        "photo_urls": hike.photo_urls or [],
        "timestamp": datetime.datetime.now().isoformat()
    }
    return hikes[hid]

@app.get("/hikes/{hike_id}")
def get_hike(hike_id: int):
    if hike_id not in hikes:
        raise HTTPException(status_code=404, detail="Hike not found")
    return hikes[hike_id]

@app.post("/conditions")
def update_condition(condition: ConditionUpdate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    require_steward(user)
    if condition.trail_id not in trails:
        raise HTTPException(status_code=404, detail="Trail not found")
    trail_conditions[condition.trail_id] = {
        "trail_id": condition.trail_id,
        "condition": condition.condition,
        "updated_by": user["id"],
        "updated_at": datetime.datetime.now().isoformat()
    }
    return trail_conditions[condition.trail_id]

@app.post("/closures")
def mark_closure(trail_id: int, closed: bool = True, authorization: str = Header(None)):
    user = get_current_user(authorization)
    require_steward(user)
    if trail_id not in trails:
        raise HTTPException(status_code=404, detail="Trail not found")
    trail_closures[trail_id] = {
        "trail_id": trail_id,
        "closed": closed,
        "updated_by": user["id"],
        "updated_at": datetime.datetime.now().isoformat()
    }
    return trail_closures[trail_id]

@app.get("/closures/{trail_id}")
def get_closure(trail_id: int):
    if trail_id not in trail_closures:
        return {"trail_id": trail_id, "closed": False}
    return trail_closures[trail_id]

@app.post("/weather-alerts")
def create_weather_alert(alert: WeatherAlertCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global next_alert_id
    aid = next_alert_id
    next_alert_id += 1
    weather_alerts.append({
        "id": aid,
        "trail_id": alert.trail_id,
        "alert": alert.alert,
        "severity": alert.severity,
        "created_by": user["id"],
        "created_at": datetime.datetime.now().isoformat()
    })
    return weather_alerts[-1]

@app.get("/weather-alerts/{alert_id}")
def get_weather_alert(alert_id: int):
    for a in weather_alerts:
        if a["id"] == alert_id:
            return a
    raise HTTPException(status_code=404, detail="Alert not found")

@app.get("/weather-alerts")
def list_weather_alerts(trail_id: Optional[int] = None):
    if trail_id:
        return [a for a in weather_alerts if a["trail_id"] == trail_id]
    return weather_alerts

@app.post("/gear-checklists")
def create_gear_checklist(checklist: GearChecklistCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if checklist.trail_id not in trails:
        raise HTTPException(status_code=404, detail="Trail not found")
    global next_gear_id
    gid = next_gear_id
    next_gear_id += 1
    gear_checklists[gid] = {
        "id": gid,
        "trail_id": checklist.trail_id,
        "items": checklist.items,
        "created_by": user["id"]
    }
    return gear_checklists[gid]

@app.get("/gear-checklists/{checklist_id}")
def get_gear_checklist(checklist_id: int):
    if checklist_id not in gear_checklists:
        raise HTTPException(status_code=404, detail="Checklist not found")
    return gear_checklists[checklist_id]

@app.get("/gear-checklists")
def list_gear_checklists(trail_id: Optional[int] = None):
    if trail_id:
        return [c for c in gear_checklists.values() if c["trail_id"] == trail_id]
    return list(gear_checklists.values())

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return {k: v for k, v in users[user_id].items() if k != "password"}

