from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets

app = FastAPI()

users = {}
instruments = {}
genres = {}
projects = {}
project_members = {}
project_tracks = {}
project_versions = {}

user_id_counter = 1
instrument_id_counter = 1
genre_id_counter = 1
project_id_counter = 1
track_id_counter = 1
version_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    for uid, u in users.items():
        if u.get("token") == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    uid = user_id_counter
    user_id_counter += 1
    token = secrets.token_hex(16)
    users[uid] = {"id": uid, "username": username, "password": password, "token": token, "instruments": [], "genres": []}
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            return {"user_id": uid, "token": u["token"]}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/instruments")
def create_instrument(name: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global instrument_id_counter
    iid = instrument_id_counter
    instrument_id_counter += 1
    instruments[iid] = {"id": iid, "name": name}
    return instruments[iid]

@app.get("/instruments/{instrument_id}")
def get_instrument(instrument_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if instrument_id not in instruments:
        raise HTTPException(status_code=404, detail="Instrument not found")
    return instruments[instrument_id]

@app.post("/genres")
def create_genre(name: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global genre_id_counter
    gid = genre_id_counter
    genre_id_counter += 1
    genres[gid] = {"id": gid, "name": name}
    return genres[gid]

@app.get("/genres/{genre_id}")
def get_genre(genre_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if genre_id not in genres:
        raise HTTPException(status_code=404, detail="Genre not found")
    return genres[genre_id]

@app.post("/users/{user_id}/instruments")
def add_instrument_to_user(user_id: int, instrument_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if current_user != user_id:
        raise HTTPException(status_code=403, detail="Not your account")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if instrument_id not in instruments:
        raise HTTPException(status_code=404, detail="Instrument not found")
    if instrument_id not in users[user_id]["instruments"]:
        users[user_id]["instruments"].append(instrument_id)
    return {"status": "ok"}

@app.post("/users/{user_id}/genres")
def add_genre_to_user(user_id: int, genre_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if current_user != user_id:
        raise HTTPException(status_code=403, detail="Not your account")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if genre_id not in genres:
        raise HTTPException(status_code=404, detail="Genre not found")
    if genre_id not in users[user_id]["genres"]:
        users[user_id]["genres"].append(genre_id)
    return {"status": "ok"}

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/projects")
def create_project(name: str, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    global project_id_counter
    pid = project_id_counter
    project_id_counter += 1
    projects[pid] = {"id": pid, "name": name, "producer_id": None}
    project_members[pid] = [current_user]
    project_tracks[pid] = {}
    project_versions[pid] = {}
    return projects[pid]

@app.get("/projects/{project_id}")
def get_project(project_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    return projects[project_id]

@app.post("/projects/{project_id}/join")
def join_project(project_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
