from fastapi import FastAPI, HTTPException, Header, Depends
from typing import Optional
import secrets
import datetime

app = FastAPI()

users = {}
tokens = {}
medications = {}
refill_requests = {}
refill_history = {}
pharmacists = {}
family_profiles = {}

user_id_counter = 1
medication_id_counter = 1
refill_request_id_counter = 1
refill_history_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(name: str, email: str, password: str, medications_list: Optional[list] = None):
    global user_id_counter
    if any(u.get("email") == email for u in users.values()):
        raise HTTPException(status_code=400, detail="Email already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "name": name,
        "email": email,
        "password": password,
        "medications": medications_list or []
    }
    for med in users[user_id]["medications"]:
        global medication_id_counter
        med_id = medication_id_counter
        medication_id_counter += 1
        med["id"] = med_id
        med["user_id"] = user_id
        med["refill_count"] = 0
        med["last_refill"] = None
        medications[med_id] = med
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(email: str, password: str):
    user = None
    for u in users.values():
        if u["email"] == email and u["password"] == password:
            user = u
            break
    if not user:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = user["id"]
    return {"token": token, "user_id": user["id"]}

@app.get("/users/{user_id}")
def get_user(user_id: int, user: int = Depends(get_current_user)):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.get("/medications/{medication_id}")
def get_medication(medication_id: int, user: int = Depends(get_current_user)):
    if medication_id not in medications:
        raise HTTPException(status_code=404, detail="Medication not found")
    return medications[medication_id]

@app.get("/refill_requests/{refill_request_id}")
def get_refill_request(refill_request_id: int, user: int = Depends(get_current_user)):
    if refill_request_id not in refill_requests:
        raise HTTPException(status_code=404, detail="Refill request not found")
    return refill_requests[refill_request_id]

@app.get("/refill_history/{refill_history_id}")
def get_refill_history(refill_history_id: int, user: int = Depends(get_current_user)):
    if refill_history_id not in refill_history:
        raise HTTPException(status_code=404, detail="Refill history not found")
    return refill_history[refill_history_id]

@app.get("/pharmacists/{pharmacist_id}")
def get_pharmacist(pharmacist_id: int, user: int = Depends(get_current_user)):
    if pharmacist_id not in pharmacists:
        raise HTTPException(status_code=404, detail="Pharmacist not found")
    return pharmacists[pharmacist_id]

@app.get("/family_profiles/{profile_id}")
def get_family_profile(profile_id: int, user: int = Depends(get_current_user)):
    if profile_id not in family_profiles:
        raise HTTPException(status_code=404, detail="Family profile not found")
    return family_profiles[profile_id]

@app.post("/medications")
def create_medication(name: str, dosage: str, frequency: str, user: int = Depends(get_current_user)):
    global medication_id_counter
    med_id = medication_id_counter
    medication_id_counter += 1
    med = {
        "id": med_id,
        "name": name,
        "dosage": dosage,
        "frequency": frequency,
        "user_id": user,
        "refill_count": 0,
        "last_refill": None
    }
    medications[med_id] = med
    users[user]["medications"].append(med)
    return med

@app.post("/refill_requests")
def create_refill_request(medication_id: int, quantity: int, user: int = Depends(get_current_user)):
    if medication_id not in medications:
        raise HTTPException(status_code=404, detail="Medication not found")
    if medications[medication_id]["user_id"] != user:
        raise HTTPException(status_code=403, detail="Not your medication")
    global refill_request_id_counter
    req_id = refill_request_id_counter
    refill_request_id_counter += 1
    req = {
        "id": req_id,
        "medication_id": medication_id,
        "user_id": user,
        "quantity": quantity,
        "status": "pending",
        "created_at": str(datetime.datetime.now())
    }
    refill_requests[req_id] = req
    return req

@app.post("/refill_requests/bulk")
def create_bulk_refill_request(medication_ids: list, quantities: list, user: int = Depends(get_current_user)):
    if len(medication_ids) != len(quantities):
        raise HTTPException(status_code=400, detail="Mismatched lists")
    results = []
    for med_id, qty in zip(medication_ids, quantities):
        if med_id not in medications:
            results.append({"medication_id": med_id, "error": "Not found"})
            continue
        if medications[med_id]["user_id"] != user:
            results.append({"medication_id": med_id, "error": "Not your medication"})
            continue
        global refill_request_id_counter
        req_id = refill_request_id_counter
        refill_request_id_counter += 1
        req = {
            "id": req_id,
            "medication_id": med_id,
            "user_id": user,
            "quantity": qty,
            "status": "pending",
            "created_at": str(datetime.datetime.now())
        }
        refill_requests[req_id] = req
        results.append({"medication_id": med_id, "refill_request_id": req_id})
    return {"results": results}

@app.post("/pharmacy/promote-pharmacist")
def promote_to_pharmacist(user_id: int, family_member_ids: list, user: int = Depends(get_current_user)):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User to promote not found")
    if user_id != user:
        raise HTTPException(status_code=403, detail="You can only promote yourself")
    pharmacists[user_id] = {
        "user_id": user_id,
        "family_member_ids": family_member_ids,
        "promoted_at": str(datetime.datetime.now())
    }
    profile_id = hash(str(user_id) + str(family_member_ids)) % 1000000
    family_profiles[profile_id] = {
        "id": profile_id,
        "pharmacist_user_id": user_id,
        "member_ids": family_member_ids
    }
    return {"message": "Pharmacist promoted", "pharmacist_id": user_id, "family_profile_id": profile_id}

@app.post("/refill_requests/{refill_request_id}/fulfill")
def fulfill_refill(refill_request_id: int, user: int = Depends(get_current_user)):
    if refill_request_id not in refill_requests:
        raise HTTPException(status_code=404, detail="Refill request not found")
    req = refill_requests[refill_request_id]
    if req["user_id"] != user and user not in pharmacists.get(req["user_id"], {}).get("family_member_ids", []):
        raise HTTPException(status_code=403, detail="Not authorized")
    req["status"] = "fulfilled"
    med_id = req["medication_id"]
    if med_id in medications:
        medications[med_id]["refill_count"] += 1
        medications[med_id]["last_refill"] = str(datetime.datetime.now())
    global refill_history_id_counter
    hist_id = refill_history_id_counter
    refill_history_id_counter += 1
    history_entry = {
        "id": hist_id,
        "refill_request_id": refill_request_id,
        "medication_id": med_id,
        "user_id": req["user_id"],
        "quantity": req["quantity"],
        "fulfilled_at": str(datetime.datetime.now()),
        "fulfilled_by": user
    }
    refill_history[hist_id] = history_entry
    return {"message": "Refill fulfilled", "history_id": hist_id}

