@app.post("/refill_requests/{refill_request_id}/fulfill")
def fulfill_refill(refill_request_id: int, user: int = Depends(get_current_user)):
    if refill_request_id not in refill_requests:
        raise HTTPException(status_code=404, detail="Refill request not found")
    req = refill_requests[refill_request_id]
    pharmacist_info = pharmacists.get(user, {})
    is_family_member = req["user_id"] in pharmacist_info.get("family_member_ids", [])
    if req["user_id"] != user and not is_family_member:
        raise HTTPException(status_code=403, detail="Not authorized")
    req["status"] = "fulfilled"
    med_id = req["medication_id"]
    if med_id in medications:
        medications[med_id]["refill_count"] += 1
        medications[med_id]["last_refill"] = str(datetime.datetime.now())
    global refill_history_id_counter
    hist_id = refill_history_id_counter
    refill_history_id_counter += 1
    history_entry = {
        "id": hist_id,
        "refill_request_id": refill_request_id,
        "medication_id": med_id,
        "user_id": req["user_id"],
        "quantity": req["quantity"],
        "fulfilled_at": str(datetime.datetime.now()),
        "fulfilled_by": user
    }
    refill_history[hist_id] = history_entry
    return {"message": "Refill fulfilled", "history_id": hist_id}

