    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class WorkoutCreate(BaseModel):
    name: str
    description: Optional[str] = None

class GoalCreate(BaseModel):
    description: str

@app.post("/signup")
def signup(req: SignupRequest):
    global admin_id, admin_token
    user_id = resource_counters["users"]
    resource_counters["users"] += 1
    users[user_id] = {"username": req.username, "password": req.password, "role": "user", "goals": []}
    token = str(uuid.uuid4())
    tokens[token] = user_id
    if admin_id is None:
        users[user_id]["role"] = "admin"
        admin_id = user_id
        admin_token = token
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/promote/{user_id}")
def promote(user_id: int, role: str = Header(None), token: str = Header(None)):
    current_user = get_current_user(token)
    if users[current_user]["role"] != "admin":
        raise HTTPException(status_code=403, detail="Only admin can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if role not in ("trainer", "nutritionist"):
        raise HTTPException(status_code=400, detail="Role must be 'trainer' or 'nutritionist'")
    users[user_id]["role"] = role
    return {"message": f"User {user_id} promoted to {role}"}

@app.post("/workouts")
def create_workout(workout: WorkoutCreate, token: str = Header(None)):
    current_user = get_current_user(token)
    workout_id = resource_counters["workouts"]
    resource_counters["workouts"] += 1
    workouts[workout_id] = {"id": workout_id, "name": workout.name, "description": workout.description, "trainer_id": current_user if users[current_user]["role"] == "trainer" else None}
    return workouts[workout_id]

@app.get("/workouts/{workout_id}")
def get_workout(workout_id: int, token: str = Header(None)):
    current_user = get_current_user(token)
    if workout_id not in workouts:
        raise HTTPException(status_code=404, detail="Workout not found")
    w = workouts[workout_id]
    if w["trainer_id"] is not None and w["trainer_id"] != current_user and users[current_user]["role"] not in ("admin", "trainer"):
        raise HTTPException(status_code=403, detail="Access denied")
    return w

@app.post("/goals")
def create_goal(goal: GoalCreate, token: str = Header(None)):
    current_user = get_current_user(token)
    goal_id = resource_counters["goals"]
    resource_counters["goals"] += 1
    goals[goal_id] = {"id": goal_id, "description": goal.description, "user_id": current_user}
    users[current_user]["goals"].append(goal_id)
    return goals[goal_id]

@app.get("/goals/{goal_id}")
def get_goal(goal_id: int, token: str = Header(None)):
    current_user = get_current_user(token)
    if goal_id not in goals:
        raise HTTPException(status_code=404, detail="Goal not found")
    g = goals[goal_id]
    if g["user_id"] != current_user and users[current_user]["role"] not in ("admin", "trainer", "nutritionist"):
        raise HTTPException(status_code=403, detail="Access denied")
    return g

@app.get("/users/{user_id}")
def get_user(user_id: int, token: str = Header(None)):
    current_user = get_current_user(token)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if user_id != current_user and users[current_user]["role"] not in ("admin", "trainer", "nutritionist"):
        raise HTTPException(status_code=403, detail="Access denied")
    return users[user_id]

