        venue_id = upd.get("id")
        if not venue_id or venue_id not in venues:
            results.append({"id": venue_id, "status": "not_found"})
            continue
        venue = venues[venue_id]
        if venue.get("owner_id") != user_id:
            results.append({"id": venue_id, "status": "forbidden"})
