    session = requests.Session()

    # Sign up
    signup_resp = session.post(f"{BASE_URL}/signup", params={"username": "testuser", "password": "testpass"})
    if signup_resp.status_code != 200:
        return False
    user_data = signup_resp.json()
    if "id" not in user_data or user_data["username"] != "testuser":
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", params={"username": "testuser", "password": "testpass"})
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    # Create a playlist
    headers = {"Authorization": f"Bearer {token}"}
    create_resp = session.post(f"{BASE_URL}/playlists", params={"name": "My Playlist", "description": "Test"}, headers=headers)
