import requests
import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Signup
    signup_resp = session.post(f"{BASE_URL}/signup", json={"username": "testuser", "password": "testpass"})
    if signup_resp.status_code not in (200, 201):
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", json={"username": "testuser", "password": "testpass"})
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    # Create voucher
    headers = {"Authorization": f"Bearer {token}"}
    voucher_data = {
        "code": "DISCOUNT10",
        "discount_percentage": 10.0,
        "expiry_date": "2025-12-31",
        "merchant_roles": ["admin"],
        "usage_limit": 100
    }
    create_resp = session.post(f"{BASE_URL}/vouchers", json=voucher_data, headers=headers)
    if create_resp.status_code != 200:
        return False
    created_voucher = create_resp.json()
    voucher_id = created_voucher.get("id")
    if not voucher_id:
        return False
    if created_voucher.get("created_by") != "testuser":
        return False

    # Fetch own voucher
    fetch_resp = session.get(f"{BASE_URL}/vouchers/{voucher_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    fetched_voucher = fetch_resp.json()
    if fetched_voucher.get("id") != voucher_id:
        return False
    if fetched_voucher.get("created_by") != "testuser":
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

