from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
from typing import Optional
import secrets
import hashlib

app = FastAPI()

users = {}
tokens = {}
providers = {}
appointments = {}
reschedule_history = {}
next_user_id = 1
next_provider_id = 1
next_appointment_id = 1

def auth_required(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization[7:]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="Already exists")
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "username": username, "password": hashlib.sha256(password.encode()).hexdigest()}
    return {"id": uid, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == hashlib.sha256(password.encode()).hexdigest():
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/providers")
def create_provider(name: str, specialty: str, authorization: str = Header(None)):
    auth_required(authorization)
    global next_provider_id
    pid = next_provider_id
    next_provider_id += 1
    providers[pid] = {"id": pid, "name": name, "specialty": specialty}
    return providers[pid]

@app.get("/providers/{provider_id}")
def get_provider(provider_id: int, authorization: str = Header(None)):
    auth_required(authorization)
    if provider_id not in providers:
        raise HTTPException(status_code=404)
    return providers[provider_id]

@app.post("/appointments")
def create_appointment(provider_id: int, patient_name: str, date: str, time: str, authorization: str = Header(None)):
    user_id = auth_required(authorization)
    global next_appointment_id
    if provider_id not in providers:
        raise HTTPException(status_code=404, detail="Provider not found")

    dt_str = f"{date} {time}"
    try:
        dt = datetime.strptime(dt_str, "%Y-%m-%d %H:%M")
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid date/time format, use YYYY-MM-DD HH:MM")

    # Check slot availability using raw SQL simulation
    slot_available = True
    for apt in appointments.values():
        if apt["provider_id"] == provider_id:
            apt_dt = datetime.strptime(f"{apt['date']} {apt['time']}", "%Y-%m-%d %H:%M")
            if abs((apt_dt - dt).total_seconds()) < 3600:  # 1 hour slot
                slot_available = False
                break

    if not slot_available:
        raise HTTPException(status_code=409, detail="Slot not available")

    aid = next_appointment_id
    next_appointment_id += 1
    appointments[aid] = {
        "id": aid,
        "provider_id": provider_id,
        "patient_name": patient_name,
        "date": date,
        "time": time,
        "status": "scheduled",
        "created_by": user_id,
        "reschedule_count": 0
    }
    reschedule_history[aid] = []
    return appointments[aid]

@app.get("/appointments/{appointment_id}")
def get_appointment(appointment_id: int, authorization: str = Header(None)):
    auth_required(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404)
    return appointments[appointment_id]

@app.get("/appointments")
def get_appointments(
    provider: Optional[int] = None,
    date: Optional[str] = None,
    status: Optional[str] = None,
    authorization: str = Header(None)
):
    auth_required(authorization)
    results = []
    for apt in appointments.values():
        if provider and apt["provider_id"] != provider:
            continue
        if date and apt["date"] != date:
            continue
        if status and apt["status"] != status:
            continue
        results.append(apt)
    return results

@app.put("/appointments/{appointment_id}/reschedule")
def reschedule_appointment(appointment_id: int, new_date: str, new_time: str, authorization: str = Header(None)):
    user_id = auth_required(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404)

    apt = appointments[appointment_id]
    old_dt = f"{apt['date']} {apt['time']}"
    new_dt_str = f"{new_date} {new_time}"
    try:
        new_dt = datetime.strptime(new_dt_str, "%Y-%m-%d %H:%M")
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid date/time format")

    # Check slot availability
    for other_apt in appointments.values():
        if other_apt["id"] != appointment_id and other_apt["provider_id"] == apt["provider_id"]:
            other_dt = datetime.strptime(f"{other_apt['date']} {other_apt['time']}", "%Y-%m-%d %H:%M")
            if abs((other_dt - new_dt).total_seconds()) < 3600:
                raise HTTPException(status_code=409, detail="Slot not available")

    # Track history
    reschedule_history[appointment_id].append({
        "from": old_dt,
        "to": new_dt_str,
        "changed_by": user_id,
        "timestamp": datetime.now().isoformat()
    })

    apt["date"] = new_date
    apt["time"] = new_time
    apt["reschedule_count"] += 1
    apt["status"] = "rescheduled"
    return apt

@app.get("/appointments/{appointment_id}/history")
def get_reschedule_history(appointment_id: int, authorization: str = Header(None)):
    auth_required(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404)
    return reschedule_history.get(appointment_id, [])

