    user_id = get_current_user(authorization)
    if deck_id not in decks:
        raise HTTPException(status_code=404, detail="Deck not found")
    card_id = len(cards) + 1
    cards[card_id] = {"id": card_id, "deck_id": deck_id, "front": front, "back": back}
    decks[deck_id]["cards"].append(card_id)
    return cards[card_id]

@app.get("/deck/{deck_id}/card/{card_id}")
def get_card(deck_id: int, card_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if card_id not in cards or cards[card_id]["deck_id"] != deck_id:
        raise HTTPException(status_code=404, detail="Card not found")
    return cards[card_id]

