from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import secrets

app = FastAPI()

users = {}
tokens = {}
next_user_id = 1
moderator_id = None

class SignupRequest(BaseModel):
    name: str
    industry_tags: List[str] = []
    talk_preferences: List[str] = []
    email: str

class LoginRequest(BaseModel):
    email: str

class ProfileUpdate(BaseModel):
    industry_tags: Optional[List[str]] = None
    talk_preferences: Optional[List[str]] = None

meetings = {}
next_meeting_id = 1

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id, moderator_id
    uid = next_user_id
    next_user_id += 1
    user = {
        "id": uid,
        "name": req.name,
        "email": req.email,
        "industry_tags": req.industry_tags,
        "talk_preferences": req.talk_preferences,
        "meeting_history": [],
        "is_moderator": False
    }
    users[uid] = user
    if moderator_id is None:
        moderator_id = uid
        user["is_moderator"] = True
    token = secrets.token_hex(16)
    tokens[token] = uid
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["email"] == req.email:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"user_id": uid, "token": token}
    raise HTTPException(404, "User not found")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(404, "User not found")
    return users[user_id]

@app.post("/users")
def create_user(req: SignupRequest):
    return signup(req)

@app.post("/mods/{user_id}")
def promote_mod(user_id: int, authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    requester_id = tokens.get(token)
    if requester_id is None or requester_id != moderator_id:
        raise HTTPException(403, "Only the moderator can promote")
    if user_id not in users:
        raise HTTPException(404, "User not found")
    users[user_id]["is_moderator"] = True
    return {"status": "promoted", "user_id": user_id}

@app.post("/meetings")
def create_meeting(participant_ids: List[int], authorization: str = Header(...)):
    global next_meeting_id
    token = authorization.replace("Bearer ", "")
    requester_id = tokens.get(token)
    if requester_id is None:
        raise HTTPException(401, "Invalid token")
    for pid in participant_ids:
        if pid not in users:
            raise HTTPException(404, f"User {pid} not found")
    mid = next_meeting_id
    next_meeting_id += 1
    meeting = {"id": mid, "participants": participant_ids}
    meetings[mid] = meeting
    for pid in participant_ids:
        users[pid]["meeting_history"].append(mid)
    return meeting

@app.get("/meetings/{meeting_id}")
def get_meeting(meeting_id: int):
    if meeting_id not in meetings:
        raise HTTPException(404, "Meeting not found")
    return meetings[meeting_id]

@app.patch("/users/{user_id}")
def update_profile(user_id: int, update: ProfileUpdate, authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    requester_id = tokens.get(token)
    if requester_id is None or requester_id != user_id:
        raise HTTPException(403, "Can only update own profile")
    if user_id not in users:
        raise HTTPException(404, "User not found")
    user = users[user_id]
    if update.industry_tags is not None:
        user["industry_tags"] = update.industry_tags
    if update.talk_preferences is not None:
        user["talk_preferences"] = update.talk_preferences
    return user

@app.get("/meetings")
def list_meetings():
    return list(meetings.values())

