from pydantic import BaseModel
from typing import Optional, List
import random
import string

app = FastAPI()

users = {}
tokens = {}
museums = {}
exhibits = {}
reservations = {}
docent_promotions = {}
next_user_id = 1
next_museum_id = 1
next_exhibit_id = 1
next_reservation_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class MuseumCreate(BaseModel):
    name: str
    location: str

class ExhibitCreate(BaseModel):
    name: str
    museum_id: int

class ReservationCreate(BaseModel):
    exhibit_id: int
    time_slot: str
    group_size: int
    guided_tour: bool = False

class ReservationUpdate(BaseModel):
    time_slot: Optional[str] = None
    group_size: Optional[int] = None
    guided_tour: Optional[bool] = None

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/museums")
def create_museum(museum: MuseumCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_museum_id
    mid = next_museum_id
    next_museum_id += 1
    museums[mid] = {"id": mid, "name": museum.name, "location": museum.location}
    return museums[mid]

@app.get("/museums/{museum_id}")
def get_museum(museum_id: int):
    if museum_id not in museums:
        raise HTTPException(status_code=404, detail="Museum not found")
    return museums[museum_id]

@app.post("/exhibits")
def create_exhibit(exhibit: ExhibitCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    if exhibit.museum_id not in museums:
        raise HTTPException(status_code=404, detail="Museum not found")
    global next_exhibit_id
    eid = next_exhibit_id
    next_exhibit_id += 1
    exhibits[eid] = {"id": eid, "name": exhibit.name, "museum_id": exhibit.museum_id}
    return exhibits[eid]

@app.get("/exhibits/{exhibit_id}")
def get_exhibit(exhibit_id: int):
    if exhibit_id not in exhibits:
        raise HTTPException(status_code=404, detail="Exhibit not found")
    return exhibits[exhibit_id]

@app.post("/reservations")
def create_reservation(reservation: ReservationCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if reservation.exhibit_id not in exhibits:
        raise HTTPException(status_code=404, detail="Exhibit not found")
    global next_reservation_id
    rid = next_reservation_id
    next_reservation_id += 1
    is_docent = False
    if rid == 1:
        is_docent = True
        docent_promotions[user_id] = []
    reservations[rid] = {
        "id": rid,
        "exhibit_id": reservation.exhibit_id,
        "user_id": user_id,
        "time_slot": reservation.time_slot,
        "group_size": reservation.group_size,
        "guided_tour": reservation.guided_tour,
        "docent_user_id": None
    }
    if is_docent:
        reservations[rid]["docent_user_id"] = user_id
    return reservations[rid]

@app.get("/reservations/{reservation_id}")
def get_reservation(reservation_id: int):
    if reservation_id not in reservations:
        raise HTTPException(status_code=404, detail="Reservation not found")
    return reservations[reservation_id]

@app.post("/docents/{user_id}")
def promote_docent(user_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if current_user not in docent_promotions:
        raise HTTPException(status_code=403, detail="Only the first patron (docent) can promote others")
    if user_id in docent_promotions:
        raise HTTPException(status_code=400, detail="User is already a docent")
    docent_promotions[user_id] = []
    docent_promotions[current_user].append(user_id)
    return {"message": f"User {user_id} promoted to docent"}

