from pydantic import BaseModel
from typing import Optional, List
import secrets

app = FastAPI()

users = {}
tokens = {}
tutors = {}
sessions = {}
reviews = {}
next_user_id = 1
next_tutor_id = 1
next_session_id = 1
next_review_id = 1
moderator_id = None

