            current_tutor = tid
            break
    if current_tutor is None:
        raise HTTPException(status_code=403, detail="Only moderators can promote")
    target_tutor = None
    for tid, t in tutors.items():
        if t["user_id"] == user_id:
            target_tutor = tid
            break
    if target_tutor is None:
