from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
coordinators = {}
skills = {}
skill_offers = {}
skill_swaps = {}
exchange_history = {}
time_credits = {}

user_id_counter = 1
skill_id_counter = 1
swap_id_counter = 1
coordinator_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": username, "password": password, "is_coordinator": False}
    time_credits[user_id] = 100
    return {"user_id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/coordinators/{user_id}")
def promote_coordinator(user_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    current_user = users.get(current_user_id)
    if not current_user or not current_user["is_coordinator"]:
        raise HTTPException(status_code=403, detail="Only coordinators can promote others")
    target_user = users.get(user_id)
    if not target_user:
        raise HTTPException(status_code=404, detail="User not found")
    target_user["is_coordinator"] = True
    if user_id not in coordinators:
        coordinators[user_id] = {"user_id": user_id, "promoted_by": current_user_id}
    return {"message": "User promoted to coordinator", "user_id": user_id}

@app.post("/skills")
def offer_skill(skill_name: str, category: str, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    global skill_id_counter
    skill_id = skill_id_counter
    skill_id_counter += 1
    skills[skill_id] = {"id": skill_id, "name": skill_name, "category": category, "offered_by": current_user_id}
    skill_offers[skill_id] = {"skill_id": skill_id, "user_id": current_user_id}
    if not users[current_user_id]["is_coordinator"]:
        users[current_user_id]["is_coordinator"] = True
        coordinators[current_user_id] = {"user_id": current_user_id, "promoted_by": None}
    return {"skill_id": skill_id, "name": skill_name, "category": category}

@app.post("/swaps")
def create_swap(skill_offered_id: int, skill_requested_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    global swap_id_counter
    swap_id = swap_id_counter
    swap_id_counter += 1
    if skill_offered_id not in skills or skill_requested_id not in skills:
        raise HTTPException(status_code=404, detail="Skill not found")
    if current_user_id not in time_credits:
        time_credits[current_user_id] = 100
    if time_credits[current_user_id] < 10:
        raise HTTPException(status_code=400, detail="Not enough time credits")
    time_credits[current_user_id] -= 10
    skill_swaps[swap_id] = {
        "id": swap_id,
        "skill_offered_id": skill_offered_id,
        "skill_requested_id": skill_requested_id,
        "user_id": current_user_id,
        "status": "pending"
    }
