import secrets

app = FastAPI()

users = {}
tokens = {}
learners = {}
next_user_id = 1
next_learner_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth")
    token = authorization.replace("Bearer ", "")
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(name: str, native_language: str, email: str):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "name": name, "native_language": native_language, "email": email}
    token = secrets.token_hex(16)
    tokens[uid] = token
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(email: str):
    for uid, u in users.items():
        if u["email"] == email:
            token = secrets.token_hex(16)
            tokens[uid] = token
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=404, detail="User not found")

@app.get("/learners/{learner_id}")
def get_learner(learner_id: int):
    learner = learners.get(learner_id)
    if not learner:
        raise HTTPException(status_code=404, detail="Learner not found")
    return learner

@app.get("/users/{user_id}")
def get_user(user_id: int):
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return user

@app.post("/learners")
def create_learner(name: str, native_language: str, learning_goals: str, tutor_tier: str, authorization: Optional[str] = Header(None)):
    uid = get_current_user(authorization)
    global next_learner_id
    lid = next_learner_id
    next_learner_id += 1
    learners[lid] = {
        "id": lid,
        "name": name,
        "native_language": native_language,
        "learning_goals": learning_goals,
        "tutor_tier": tutor_tier,
        "owner_id": uid
    }
    return learners[lid]

@app.put("/learners/{learner_id}")
def update_learner(learner_id: int, native_language: Optional[str] = None, learning_goals: Optional[str] = None, tutor_tier: Optional[str] = None, authorization: Optional[str] = Header(None)):
    uid = get_current_user(authorization)
    learner = learners.get(learner_id)
    if not learner:
        raise HTTPException(status_code=404, detail="Learner not found")
    if learner["owner_id"] != uid:
        raise HTTPException(status_code=403, detail="Not authorized to modify this learner")
    if native_language is not None:
        learner["native_language"] = native_language
    if learning_goals is not None:
        learner["learning_goals"] = learning_goals
    if tutor_tier is not None:
        learner["tutor_tier"] = tutor_tier
    return learner

