from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
events = {}
orders = {}
event_id_counter = 1
order_id_counter = 1
user_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class EventCreate(BaseModel):
    name: str
    capacity: int

class PurchaseRequest(BaseModel):
    event_id: int
    quantity: int

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token, "user_id": u["id"]}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/event")
def create_event(event: EventCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global event_id_counter
    event_id = event_id_counter
    event_id_counter += 1
    events[event_id] = {"id": event_id, "name": event.name, "capacity": event.capacity}
    return {"event_id": event_id, "name": event.name, "capacity": event.capacity}

@app.post("/purchase")
def purchase_tickets(purchase: PurchaseRequest, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(purchase.event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if event["capacity"] < purchase.quantity:
        raise HTTPException(status_code=400, detail="Not enough capacity")
    event["capacity"] -= purchase.quantity
    global order_id_counter
