    orders[order_id] = {"id": order_id, "user_id": user_id, "event_id": purchase.event_id, "quantity": purchase.quantity}
    return {"order_id": order_id, "event_id": purchase.event_id, "quantity": purchase.quantity}

@app.get("/events")
def list_events():
    return [{"id": e["id"], "name": e["name"], "remaining": e["capacity"]} for e in events.values()]

@app.get("/event/{event_id}")
def get_event(event_id: int):
