import requests

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    try:
        # Sign up a new user
        signup_resp = requests.post(f"{BASE_URL}/signup", json={
            "username": "testuser",
            "password": "testpass123"
        })
        if signup_resp.status_code != 200:
            print("SPEC_FAIL")
            return False
        user_data = signup_resp.json()
        user_id = user_data.get("user_id")
        if not user_id:
            print("SPEC_FAIL")
            return False

        # Log in with the new user
        login_resp = requests.post(f"{BASE_URL}/login", json={
            "username": "testuser",
            "password": "testpass123"
        })
        if login_resp.status_code != 200:
            print("SPEC_FAIL")
            return False
        login_data = login_resp.json()
        token = login_data.get("token")
        if not token:
            print("SPEC_FAIL")
            return False

        # Create an event
        event_resp = requests.post(f"{BASE_URL}/event", json={
            "name": "Test Event",
            "capacity": 100
        }, headers={"Authorization": f"Bearer {token}"})
        if event_resp.status_code != 200:
            print("SPEC_FAIL")
            return False
        event_data = event_resp.json()
        event_id = event_data.get("event_id")
        if not event_id:
            print("SPEC_FAIL")
            return False

        # Purchase tickets
        purchase_resp = requests.post(f"{BASE_URL}/purchase", json={
            "event_id": event_id,
            "quantity": 2
        }, headers={"Authorization": f"Bearer {token}"})
        if purchase_resp.status_code != 200:
            print("SPEC_FAIL")
            return False
        purchase_data = purchase_resp.json()
        order_id = purchase_data.get("order_id")
        if not order_id:
            print("SPEC_FAIL")
            return False

        # Fetch the order (user's own data)
        order_resp = requests.get(f"{BASE_URL}/order/{order_id}", headers={
            "Authorization": f"Bearer {token}"
        })
        if order_resp.status_code != 200:
            print("SPEC_FAIL")
            return False
        order_data = order_resp.json()
        if order_data.get("user_id") != user_id:
            print("SPEC_FAIL")
            return False

        # Fetch events to verify event exists
        events_resp = requests.get(f"{BASE_URL}/events")
        if events_resp.status_code != 200:
            print("SPEC_FAIL")
            return False
        events_list = events_resp.json()
        if not any(e["id"] == event_id for e in events_list):
            print("SPEC_FAIL")
            return False

        print("SPEC_PASS")
        return True

    except requests.exceptions.ConnectionError:
        print("SPEC_FAIL")
        return False
    except Exception:
        print("SPEC_FAIL")
        return False

if __name__ == "__main__":
    if test_golden_path():
        sys.exit(0)
    else:
        sys.exit(1)

