from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import random
import string

app = FastAPI()

users = {}
tokens = {}
matches = {}
next_user_id = 1
next_match_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(name: str, age: int, city: str, gender: str, interested_in: str):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {
        "id": uid,
        "name": name,
        "age": age,
        "city": city,
        "gender": gender,
        "interested_in": interested_in
    }
    token = generate_token()
    tokens[uid] = token
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(user_id: int, name: str):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if users[user_id]["name"] != name:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[user_id] = token
    return {"token": token}

@app.post("/users")
def create_user(name: str, age: int, city: str, gender: str, interested_in: str):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {
        "id": uid,
        "name": name,
        "age": age,
        "city": city,
        "gender": gender,
        "interested_in": interested_in
    }
    return {"id": uid}

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.get("/matches")
def get_matches(user_id: int, age_range: str, city: str, authorization: str = Header(None)):
    current_uid = get_current_user(authorization)
    if user_id != current_uid:
        raise HTTPException(status_code=403, detail="Can only get matches for yourself")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")

    try:
        age_min, age_max = map(int, age_range.split("-"))
    except:
        raise HTTPException(status_code=400, detail="Invalid age_range format, use e.g. 25-35")

    current_user = users[user_id]
    candidates = []
    for uid, u in users.items():
        if uid == user_id:
            continue
        if u["city"] != city:
            continue
        if u["age"] < age_min or u["age"] > age_max:
            continue
        if u["gender"] != current_user["interested_in"]:
