from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import json, os, secrets, hashlib
from typing import Optional

app = FastAPI()

users = {}
tokens = {}
scores = {}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ScoreRequest(BaseModel):
    score: float

def get_user_from_token(authorization: str):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    for uid, tok in tokens.items():
        if tok == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    uid = str(len(users) + 1)
    users[req.username] = {"id": uid, "password": req.password}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    uid = users[req.username]["id"]
    token = secrets.token_hex(16)
    tokens[uid] = token
    return {"token": token}

@app.post("/grade/{assignment_id}/{student_id}")
def post_grade(assignment_id: int, student_id: int, req: ScoreRequest, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    os.makedirs(f"grades/{assignment_id}", exist_ok=True)
    with open(f"grades/{assignment_id}/{student_id}.json", "w") as f:
        json.dump({"score": req.score}, f)
