from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import json, os, secrets, hashlib
from typing import Optional

app = FastAPI()

users = {}
tokens = {}
scores = {}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ScoreRequest(BaseModel):
    score: float

def get_user_from_token(authorization: str):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    for uid, tok in tokens.items():
        if tok == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    uid = str(len(users) + 1)
    users[req.username] = {"id": uid, "password": req.password}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    uid = users[req.username]["id"]
    token = secrets.token_hex(16)
    tokens[uid] = token
    return {"token": token}

@app.post("/grade/{assignment_id}/{student_id}")
def post_grade(assignment_id: int, student_id: int, req: ScoreRequest, authorization: Optional[str] = Header(None)):
    uid = get_user_from_token(authorization)
    # Enforce that only the owner can post their own grade
    if str(student_id) != str(uid):
        raise HTTPException(status_code=403, detail="Forbidden")
    os.makedirs(f"grades/{assignment_id}", exist_ok=True)
    with open(f"grades/{assignment_id}/{student_id}.json", "w") as f:
        json.dump({"score": req.score}, f)
    return {"status": "saved"}

@app.get("/grade/{assignment_id}/{student_id}")
def get_grade(assignment_id: int, student_id: int, authorization: Optional[str] = Header(None)):
    uid = get_user_from_token(authorization)
    # Enforce that only the owner can view their own grade
    if str(student_id) != str(uid):
        raise HTTPException(status_code=403, detail="Forbidden")
    try:
        with open(f"grades/{assignment_id}/{student_id}.json", "r") as f:
            return json.load(f)
    except FileNotFoundError:
        raise HTTPException(status_code=404, detail="Grade not found")

@app.get("/grade/{assignment_id}/summary")
def get_summary(assignment_id: int, authorization: Optional[str] = Header(None)):
    uid = get_user_from_token(authorization)
    # Return only the current user's grade in the summary
    folder = f"grades/{assignment_id}"
    if not os.path.isdir(folder):
        return {"summary": {}}
    summary = {}
    fname = f"{uid}.json"
    filepath = os.path.join(folder, fname)
    if os.path.exists(filepath):
        with open(filepath) as f:
            data = json.load(f)
        summary[uid] = data["score"]
    return {"summary": summary}

