    max_players: int

class MatchResult(BaseModel):
    winner_id: int
    score: Optional[str] = None

class BulkRegistration(BaseModel):
    player_ids: List[int]

def get_current_user(token: str = Header(None)):
    if token is None or token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

def get_admin_user(token: str = Header(None)):
    user = get_current_user(token)
    if not user.get("is_admin"):
        raise HTTPException(status_code=403, detail="Admin only")
    return user

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password,
        "is_admin": False,
        "is_referee": False
    }
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/tournaments")
def create_tournament(req: TournamentCreate, token: str = Header(None)):
    get_current_user(token)
    global next_tournament_id
    tid = next_tournament_id
    next_tournament_id += 1
    tournaments[tid] = {
        "id": tid,
        "name": req.name,
        "game": req.game,
        "max_players": req.max_players,
        "players": [],
        "referees": [],
        "status": "open",
        "bracket": {}
    }
    return tournaments[tid]

@app.get("/tournaments/{tid}")
def get_tournament(tid: int):
    if tid not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    return tournaments[tid]

@app.post("/tournaments/{tid}/register")
def register_for_tournament(tid: int, token: str = Header(None)):
    user = get_current_user(token)
    if tid not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    t = tournaments[tid]
    if t["status"] != "open":
        raise HTTPException(status_code=400, detail="Tournament open")
    if len(t["players"]) >= t["max_players"]:
        raise HTTPException(status_code=400, detail="Tournament full")
    if user["id"] in t["players"]:
        raise HTTPException(status_code=400, detail="Already registered")
    t["players"].append(user["id"])
    return {"message": "Registered", "player_id": user["id"]}

@app.post("/tournaments/{tid}/bulk-register")
def bulk_register(tid: int, req: BulkRegistration, token: str = Header(None)):
    admin = get_admin_user(token)
    if tid not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    t = tournaments[tid]
    if t["status"] != "open":
        raise HTTPException(status_code=400, detail="Tournament open")
    added = []
    for pid in req.player_ids:
        if pid not in users:
            continue
        if pid in t["players"]:
            continue
        if len(t["players"]) >= t["max_players"]:
            break
        t["players"].append(pid)
        added.append(pid)
    return {"added": added, "total_players": len(t["players"])}

@app.post("/tournaments/{tid}/promote-referee")
def promote_referee(tid: int, player_id: int, token: str = Header(None)):
    admin = get_admin_user(token)
    if tid not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    if player_id not in users:
        raise HTTPException(status_code=404, detail="Player not found")
    t = tournaments[tid]
    if player_id not in t["players"]:
        raise HTTPException(status_code=400, detail="Player not in tournament")
    if player_id in t["referees"]:
        raise HTTPException(status_code=400, detail="Already a referee")
    t["referees"].append(player_id)
    users[player_id]["is_referee"] = True
    return {"message": "Promoted to referee", "referee_id": player_id}

@app.post("/matches")
def create_match(tournament_id: int, player1_id: int, player2_id: int, token: str = Header(None)):
    user = get_current_user(token)
    if tournament_id not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    t = tournaments[tournament_id]
    if player1_id not in t["players"] or player2_id not in t["players"]:
        raise HTTPException(status_code=400, detail="Both players must be registered in the tournament")
    global next_match_id
    mid = next_match_id
    next_match_id += 1
    matches[mid] = {
        "id": mid,
        "tournament_id": tournament_id,
        "player1_id": player1_id,
        "player2_id": player2_id,
        "winner_id": None,
        "score": None,
        "status": "pending",
        "disputed": False,
        "validated_by": None
    }
    return matches[mid]

@app.get("/matches/{mid}")
def get_match(mid: int):
    if mid not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    return matches[mid]

@app.post("/matches/{mid}/result")
def submit_match_result(mid: int, result: MatchResult, token: str = Header(None)):
    user = get_current_user(token)
    if mid not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    m = matches[mid]
    if m["status"] != "pending":
        raise HTTPException(status_code=400, detail="Match already resolved")
    if result.winner_id not in [m["player1_id"], m["player2_id"]]:
        raise HTTPException(status_code=400, detail="Winner must be a player in match")
    m["winner_id"] = result.winner_id
    m["score"] = result.score
    m["status"] = "submitted"
    return m

@app.post("/matches/{mid}/validate")
def validate_match(mid: int, token: str = Header(None)):
    user = get_current_user(token)
    if mid not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    m = matches[mid]
    if m["status"] != "submitted":
        raise HTTPException(status_code=400, detail="Match not submitted")
    tid = m["tournament_id"]
    if tid not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    if user["id"] not in tournaments[tid]["referees"]:
        raise HTTPException(status_code=403, detail="Not a referee for this tournament")
    m["status"] = "validated"
    m["validated_by"] = user["id"]
    return m

@app.post("/matches/{mid}/dispute")
def dispute_match(mid: int, token: str = Header(None)):
    user = get_current_user(token)
    if mid not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    m = matches[mid]
    if m["status"] != "submitted":
        raise HTTPException(status_code=400, detail="Cannot dispute this match")
    tid = m["tournament_id"]
    if tid not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    if user["id"] not in tournaments[tid]["referees"]:
        raise HTTPException(status_code=403, detail="Not a referee for this tournament")
    m["disputed"] = True
    m["status"] = "disputed"
    return m

@app.get("/users/{uid}")
def get_user(uid: int):
    if uid not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return {k: v for k, v in users[uid].items() if k != "password"}

@app.post("/users")
def create_user(req: SignupRequest):
    return signup(req)

