from fastapi import FastAPI, HTTPException, Header
from typing import Optional
from datetime import datetime
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
lists = {}
tasks = {}
completions = {}
collaborators = {}
next_user_id = 1
next_list_id = 1
next_task_id = 1
next_completion_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(401, "No auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(401, "Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(400, "Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": hashlib.sha256(password.encode()).hexdigest()}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == hashlib.sha256(password.encode()).hexdigest():
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(401, "Bad credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(404, "User not found")
    return users[user_id]

@app.post("/lists")
def create_list(name: str, deadline: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_list_id
    list_id = next_list_id
    next_list_id += 1
    lists[list_id] = {"id": list_id, "name": name, "deadline": deadline, "owner_id": user_id, "created_at": datetime.now().isoformat()}
    collaborators[list_id] = [user_id]
    return lists[list_id]

@app.get("/lists/{list_id}")
def get_list(list_id: int):
    if list_id not in lists:
        raise HTTPException(404, "List not found")
    return lists[list_id]

@app.post("/lists/{list_id}/promote-collaborator")
def promote_collaborator(list_id: int, user_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    if list_id not in lists:
        raise HTTPException(404, "List not found")
    if lists[list_id]["owner_id"] != current_user:
        raise HTTPException(403, "Only owner can promote")
    if user_id not in users:
        raise HTTPException(404, "User not found")
    if user_id not in collaborators.get(list_id, []):
        collaborators.setdefault(list_id, []).append(user_id)
    return {"status": "ok", "collaborators": collaborators[list_id]}

@app.post("/tasks")
def create_task(list_id: int, title: str, description: str = "", authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if list_id not in lists:
        raise HTTPException(404, "List not found")
    if user_id not in collaborators.get(list_id, []):
        raise HTTPException(403, "Not a collaborator")
    global next_task_id
    task_id = next_task_id
    next_task_id += 1
    tasks[task_id] = {"id": task_id, "list_id": list_id, "title": title, "description": description, "completed": False, "order": len([t for t in tasks.values() if t["list_id"] == list_id])}
    return tasks[task_id]

@app.get("/tasks/{task_id}")
def get_task(task_id: int):
    if task_id not in tasks:
        raise HTTPException(404, "Task not found")
    return tasks[task_id]

@app.put("/tasks/{task_id}")
def update_task(task_id: int, title: Optional[str] = None, description: Optional[str] = None, completed: Optional[bool] = None, order: Optional[int] = None, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if task_id not in tasks:
        raise HTTPException(404, "Task not found")
    task = tasks[task_id]
    if user_id not in collaborators.get(task["list_id"], []):
        raise HTTPException(403, "Not a collaborator")
    if title is not None:
        task["title"] = title
    if description is not None:
        task["description"] = description
    if completed is not None:
