                    yield chunk

        return Response(
            content=file_stream(),
            status_code=200,
            headers={
                "Content-Length": str(file_size),
                "Content-Type": "video/mp4",
                "Accept-Ranges": "bytes",
                "duration_seconds": str(duration_seconds),
            },
        )

