import os
import json
import hashlib
import secrets
from datetime import datetime
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel

app = FastAPI()

DATA_DIR = "/data/patients"
users = {}
tokens = {}

class UserCreate(BaseModel):
    username: str
    password: str
    role: str = "patient"

class UserLogin(BaseModel):
    username: str
    password: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(user: UserCreate):
    if user.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[user.username] = {
        "username": user.username,
        "password": hash_password(user.password),
        "role": user.role
    }
    return {"message": "User created"}

@app.post("/login")
def login(user: UserLogin):
    if user.username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if users[user.username]["password"] != hash_password(user.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = users[user.username]
    return {"token": token, "role": users[user.username]["role"]}

@app.get("/records/{patient_id}/{filename}")
def get_record(patient_id: str, filename: str, current_user: dict = get_current_user):
    file_path = os.path.join(DATA_DIR, patient_id, filename)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="File not found")

    # Log access
    log_entry = {
        "patient_id": patient_id,
        "filename": filename,
        "timestamp": datetime.utcnow().isoformat(),
        "user_role": current_user["role"],
        "username": current_user["username"]
    }
    log_dir = os.path.join(DATA_DIR, patient_id, ".logs")
    os.makedirs(log_dir, exist_ok=True)
    log_file = os.path.join(log_dir, "access.log")
    with open(log_file, "a") as f:
        f.write(json.dumps(log_entry) + "\n")

    with open(file_path, "r") as f:
        content = f.read()

    return {"filename": filename, "content": content}

