from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import csv
import io
from datetime import datetime, timedelta
import random
import string

app = FastAPI()

# In-memory stores
users = {}
decks = {}
cards = {}
topics = {}
contributors = {}  # {deck_id: {user_id: role}}
spaced_repetition = {}  # {card_id: {user_id: {interval, ease_factor, next_review, repetitions}}}
tokens = {}  # {token: user_id}
next_ids = {"users": 1, "decks": 1, "cards": 1, "topics": 1}

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(401, "Missing authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(401, "Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username:
            raise HTTPException(400, "Username already exists")
    uid = next_ids["users"]
    next_ids["users"] += 1
    users[uid] = {"id": uid, "username": username, "password": password}
    return {"user_id": uid}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(401, "Invalid credentials")

@app.post("/decks")
def create_deck(name: str, description: str = "", authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    deck_id = next_ids["decks"]
    next_ids["decks"] += 1
    decks[deck_id] = {"id": deck_id, "name": name, "description": description, "creator_id": user_id, "cards": []}
    return {"deck_id": deck_id}

@app.get("/decks/{deck_id}")
def get_deck(deck_id: int):
    deck = decks.get(deck_id)
    if not deck:
        raise HTTPException(404, "Deck not found")
    return deck

@app.post("/cards")
def create_card(deck_id: int, term: str, definition: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    deck = decks.get(deck_id)
    if not deck:
        raise HTTPException(404, "Deck not found")
    if deck["creator_id"] != user_id:
        if deck_id in contributors and user_id in contributors[deck_id]:
            pass
        else:
            raise HTTPException(403, "Not authorized")
    card_id = next_ids["cards"]
    next_ids["cards"] += 1
    cards[card_id] = {"id": card_id, "deck_id": deck_id, "term": term, "definition": definition, "created_by": user_id}
    deck["cards"].append(card_id)
    return {"card_id": card_id}

@app.get("/cards/{card_id}")
def get_card(card_id: int):
    card = cards.get(card_id)
    if not card:
        raise HTTPException(404, "Card not found")
    return card

@app.post("/promote/{user_id}")
def promote_to_contributor(user_id: int, deck_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_current_user(authorization)
    deck = decks.get(deck_id)
    if not deck:
        raise HTTPException(404, "Deck not found")
    if deck["creator_id"] != current_user:
        raise HTTPException(403, "Only deck creator can promote")
    if user_id not in users:
        raise HTTPException(404, "User not found")
    if deck_id not in contributors:
