from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import random
import string
from datetime import datetime

app = FastAPI()

users = {}
tokens = {}
weather_data = {}

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class WeatherRecord(BaseModel):
    city: str
    date: str
    temperature: float
    humidity: float
    wind_speed: float
    condition: str
    alert: Optional[str] = None

class BulkWeatherRequest(BaseModel):
    cities: List[str]
    date: str

user_id_counter = 1
weather_id_counter = 1

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[req.username] = {"id": user_id, "password": req.password}
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = user["id"]
    return {"token": token}

@app.post("/weather")
def create_weather(record: WeatherRecord, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global weather_id_counter
    record_id = weather_id_counter
    weather_id_counter += 1
    weather_data[record_id] = record.dict()
    weather_data[record_id]["id"] = record_id
    weather_data[record_id]["owner_id"] = user_id
    return {"id": record_id}

@app.get("/weather/{record_id}")
def get_weather(record_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    record = weather_data.get(record_id)
    if not record:
        raise HTTPException(status_code=404, detail="Weather record not found")
    if record.get("owner_id") != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return record

@app.get("/weather")
def query_weather(city: str, date: str, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    results = []
    for record in weather_data.values():
        if record["city"] == city and record["date"] == date and record.get("owner_id") == user_id:
            results.append(record)
    if not results:
        raise HTTPException(status_code=404, detail="No weather data found for this city and date")
    return results

@app.post("/weather/bulk")
def bulk_weather(req: BulkWeatherRequest, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    results = {}
    for city in req.cities:
        city_results = []
        for record in weather_data.values():
            if record["city"] == city and record["date"] == req.date and record.get("owner_id") == user_id:
                city_results.append(record)
        results[city] = city_results if city_results else []
    return results

