from pydantic import BaseModel
import uuid
import hashlib
import random
import string
from typing import Optional

app = FastAPI()

users = {}
tokens = {}
stocks = {}
stock_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def hash_password(password: str):
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class StockCreate(BaseModel):
    symbol: str
    company_name: str
    current_price: float
    high_52_week: float

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/stocks")
def create_stock(stock: StockCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global stock_id_counter
    stock_id = stock_id_counter
    stock_id_counter += 1
    stocks[stock_id] = {
        "id": stock_id,
        "symbol": stock.symbol,
        "company_name": stock.company_name,
        "current_price": stock.current_price,
        "high_52_week": stock.high_52_week,
        "owner": user_id  # Track the owner
    }
    # Also index by symbol and company name for fast lookup
    stocks[stock.symbol.upper()] = stock_id
    stocks[stock.company_name.lower()] = stock_id
    return {"id": stock_id}

@app.get("/stocks/{stock_id}")
def get_stock(stock_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    stock = stocks.get(stock_id)
    if not stock:
        raise HTTPException(status_code=404, detail="Stock not found")
    # Check ownership
    if stock.get("owner") != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return stock

@app.get("/stocks")
def search_stocks(symbol: str = None, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if symbol:
        symbol_upper = symbol.upper()
        # Check if it's an ID lookup
        if symbol_upper.isdigit():
            stock = stocks.get(int(symbol_upper))
            if stock and stock.get("owner") == user_id:
                return [stock]
        # Check by symbol or company name
        stock_id = stocks.get(symbol_upper)
        if stock_id:
            stock = stocks.get(stock_id)
            if stock and stock.get("owner") == user_id:
                return [stock]
        # Try company name
        stock_id = stocks.get(symbol.lower())
        if stock_id:
            stock = stocks.get(stock_id)
            if stock and stock.get("owner") == user_id:
                return [stock]
        # Search all stocks for partial match (only owned stocks)
        results = []
        for s in stocks.values():
            if isinstance(s, dict) and "symbol" in s and s.get("owner") == user_id:
                if symbol_upper in s["symbol"].upper() or symbol.lower() in s["company_name"].lower():
                    results.append(s)
        return results
    # Return all stocks owned by the user
    return [s for s in stocks.values() if isinstance(s, dict) and "symbol" in s and s.get("owner") == user_id]

