from datetime import datetime
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
posts = {}
next_user_id = 1
next_post_id = 1

def generate_token():
    return secrets.token_hex(16)

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    if username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[username] = {"id": user_id, "username": username, "password": hashlib.sha256(password.encode()).hexdigest()}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    if username not in users:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    user = users[username]
    if user["password"] != hashlib.sha256(password.encode()).hexdigest():
        raise HTTPException(status_code=400, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = user["id"]
    return {"token": token}

@app.get("/posts/{post_id}")
def get_post(post_id: int):
    if post_id not in posts:
        raise HTTPException(status_code=404, detail="Post not found")
    return posts[post_id]

@app.post("/posts")
def create_post(content: str, author_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    global next_post_id
    post_id = next_post_id
    next_post_id += 1
    posts[post_id] = {
        "id": post_id,
        "content": content,
        "author_id": author_id,
        "created_at": datetime.now().isoformat()
    }
    return posts[post_id]

@app.get("/posts")
def search_posts(hashtag: str = None, start_date: str = None, end_date: str = None, author_id: int = None):
    results = []
    for post in posts.values():
        if hashtag:
            if f"#{hashtag}" not in post["content"]:
                continue
        if author_id is not None:
            if post["author_id"] != author_id:
                continue
        if start_date:
            if post["created_at"] < start_date:
                continue
        if end_date:
            if post["created_at"] > end_date:
                continue
        results.append(post)
    return results

