from fastapi import FastAPI, HTTPException, Header
from typing import Optional
from datetime import datetime, timedelta
import secrets
import time

app = FastAPI()

users = {}
tokens = {}
scores = {}
score_id_counter = 1

# game leaderboard in-memory store
# scores_by_game_region = {(game, region): [{"player_name", "score", "timestamp", "score_id"}]}
scores_by_game_region = {}

def get_user_from_token(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    user_id = len(users) + 1
    users[username] = {"id": user_id, "password": password, "username": username}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    user = users.get(username)
    if not user or user["password"] != password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = user["id"]
    return {"token": token}

@app.post("/scores")
def create_score(game: str, region: str, player_name: str, score: int, authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    global score_id_counter
    score_id = score_id_counter
    score_id_counter += 1
    entry = {
        "score_id": score_id,
        "player_name": player_name,
        "score": score,
        "timestamp": time.time(),
        "user_id": user_id
    }
    key = (game, region)
    if key not in scores_by_game_region:
        scores_by_game_region[key] = []
    scores_by_game_region[key].append(entry)
    scores[score_id] = entry
    return {"score_id": score_id}

@app.get("/leaderboard")
def get_leaderboard(game: str, region: str, timeframe: Optional[str] = "all", authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    key = (game, region)
    entries = scores_by_game_region.get(key, [])
    if not entries:
        return []
    now = time.time()
    if timeframe == "daily":
        cutoff = now - 86400
    elif timeframe == "weekly":
        cutoff = now - 7 * 86400
    else:
        cutoff = 0
    filtered = [e for e in entries if e["timestamp"] >= cutoff]
    sorted_entries = sorted(filtered, key=lambda x: -x["score"])
    result = []
    rank = 1
    for e in sorted_entries:
        result.append({
            "rank": rank,
            "player_name": e["player_name"],
            "score": e["score"]
        })
        rank += 1
    return result

@app.get("/scores/{score_id}")
def get_score(score_id: int, authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    entry = scores.get(score_id)
    if not entry:
        raise HTTPException(status_code=404, detail="Score not found")
    return entry

