from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import hashlib
import random

app = FastAPI()

users = {}
tokens = {}
products = {}
orders = {}
next_user_id = 1
next_product_id = 1
next_order_id = 1

def generate_token():
    return hashlib.sha256(str(random.getrandbits(256)).encode()).hexdigest()

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/products/{product_id}")
def get_product(product_id: int):
    if product_id not in products:
        raise HTTPException(status_code=404, detail="Product not found")
    return products[product_id]

@app.post("/products")
def create_product(name: str, price: float, category: str, stock: int, seller_rating: float, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global next_product_id
    pid = next_product_id
    next_product_id += 1
    products[pid] = {
        "id": pid,
        "name": name,
        "price": price,
        "category": category,
        "stock": stock,
        "seller_rating": seller_rating,
        "seller_id": user_id
    }
    return products[pid]

@app.get("/products")
def search_products(category: Optional[str] = None, min_price: Optional[float] = None, max_price: Optional[float] = None):
    results = []
    for pid, p in products.items():
        if category and p["category"] != category:
            continue
        if min_price is not None and p["price"] < min_price:
            continue
        if max_price is not None and p["price"] > max_price:
            continue
        results.append(p)
    return results

@app.post("/products/bulk-update")
def bulk_update_products(ids: list[int], price: Optional[float] = None, stock: Optional[int] = None, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    updated = []
    for pid in ids:
        if pid not in products:
            continue
        if products[pid]["seller_id"] != user_id:
            continue
        if price is not None:
            products[pid]["price"] = price
        if stock is not None:
            products[pid]["stock"] = stock
        updated.append(products[pid])
    return {"updated": updated}

@app.get("/orders/{order_id}")
def get_order(order_id: int):
    if order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")
    return orders[order_id]

@app.post("/orders")
def create_order(product_id: int, quantity: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if product_id not in products:
        raise HTTPException(status_code=404, detail="Product not found")
    if products[product_id]["stock"] < quantity:
        raise HTTPException(status_code=400, detail="Insufficient stock")
    products[product_id]["stock"] -= quantity
    global next_order_id
    oid = next_order_id
    next_order_id += 1
    orders[oid] = {
        "id": oid,
        "user_id": user_id,
        "product_id": product_id,
        "quantity": quantity,
        "total_price": products[product_id]["price"] * quantity
    }
    return orders[oid]

