import os
import uuid
from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import FileResponse, Response
from PIL import Image
import io
from pathlib import Path

app = FastAPI()

users = {}
tokens = {}
scans = {}
DATA_DIR = Path("/data/medical_images")
DATA_DIR.mkdir(parents=True, exist_ok=True)
THUMB_DIR = Path("/data/thumbnails")
THUMB_DIR.mkdir(parents=True, exist_ok=True)

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization.split(" ")[1]
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(username: str, password: str):
    uid = len(users) + 1
    users[uid] = {"username": username, "password": password}
    return {"id": uid, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = str(uuid.uuid4())
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/scans/{patient_id}/{image_name}")
def get_scan(patient_id: int, image_name: str, authorization: str = Header(...)):
    get_current_user(authorization)
    file_path = DATA_DIR / str(patient_id) / image_name
    if not file_path.exists():
        raise HTTPException(status_code=404, detail="Image not found")
    return FileResponse(file_path, media_type="image/png")

@app.get("/thumbnails/{image_name}")
def get_thumbnail(image_name: str, authorization: str = Header(...)):
    get_current_user(authorization)
    thumb_path = THUMB_DIR / image_name
    if thumb_path.exists():
        return FileResponse(thumb_path, media_type="image/png")
    # try to find the source image in any patient folder
    for patient_dir in DATA_DIR.iterdir():
        if patient_dir.is_dir():
            src_path = patient_dir / image_name
            if src_path.exists():
                img = Image.open(src_path)
                img.thumbnail((128, 128))
                buf = io.BytesIO()
                img.save(buf, format="PNG")
                buf.seek(0)
                with open(thumb_path, "wb") as f:
                    f.write(buf.getvalue())
                return Response(content=buf.getvalue(), media_type="image/png")
    raise HTTPException(status_code=404, detail="Image not found")

